window.SPELL_DATA = [{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内一点创造出一颗酸液泡，以该点5尺球状范围爆发。该球状区域内的每名生物必须通过一次敏捷豁免，否则受到1d6点强酸伤害。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"本法术的伤害会在你达到下列等级时提升1d6：5级（2d6）、11级（3d6）以及17级（4d6）。"},"id":"Acid_Splash","level":0,"nameEn":"Acid Splash","nameZh":"酸液飞溅","range":"60 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"在此法术结束前，每当有生物对你发动攻击检定，该生物的该次攻击检定都将承受1d4减值。","duration":"专注，至多1分钟","higherLevels":null,"id":"Blade_Ward","level":0,"nameEn":"Blade Ward","nameZh":"剑刃防护","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你引导出来自坟墓的刺骨阴冷，对目标进行一次近战法术攻击。命中时，目标将受到1d10点暗蚀伤害，并且直至你下一回合的结束前都无法恢复生命值。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"法术的伤害会在你到达下列等级时增加1d10：5级（2d10）、11级（3d10）以及17级（4d10）。"},"id":"Chill_Touch","level":0,"nameEn":"Chill Touch","nameZh":"颤栗之触","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师","奇械师"],"components":{"material":true,"materials":"一点磷","raw":"V、S、M（一点磷）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内创造至多四个火把大小的光源，使其在法术持续时间内看起来如同火把、灯笼或悬浮珠。或者，你可以将四个光源合并为一个发光的整体形态，使其看上去像一个模糊的中型人形。无论你选择哪种形态，每个光源都会发出10尺半径的微光光照 。\n你可以用附赠动作将光源移动至多60尺至施法距离内的一处空间。一个由此法术创造的光源必须始终位于任一光源周围20尺内，而超出施法距离的光源会随即熄灭。","duration":"专注，至多1分钟","higherLevels":null,"id":"Dancing_Lights","level":0,"nameEn":"Dancing Lights","nameZh":"舞光术","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向自然精魂低语，在施法距离内创造出下述效应之一。\n感知天气Weather Sensor。你创造一个微型 而无害的感官效应，并以之预报你所在地接下来24小时的天气状况。该效应可表现为一个代表晴空的金球、一朵代表雨天的云彩、代表雪日而飘飞的雪花等等。该效应将持续1轮。盛放Blossom。你可以立即让一朵鲜花绽放，让一颗种子破壳，或是让一片叶蕾发芽。感官效应Sensory Effect。 你创造一个无害的感官效应，例如落叶、如幽灵般舞动的小仙灵们、微风、动物的声音或者臭鼬的微弱臭气。该效应只能在5尺的立方 区域内起效。玩火Fire Play。 你点亮/熄灭一根蜡烛、一根火把或一处小篝火。","duration":"立即","higherLevels":null,"id":"Druidcraft","level":0,"nameEn":"Druidcraft","nameZh":"德鲁伊伎俩","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你释放出一束爆裂能量射线，对施法距离内一名生物或一个物件发动一次远程法术攻击。命中时，目标将受1d10点力场伤害。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达5级后此法术将创造出两条射线，11级后三条，17级后四条。你可以使这些射线攻击同一个目标或分别攻击不同的目标。你需要为每条射线分别进行攻击检定。"},"id":"Eldritch_Blast","level":0,"nameEn":"Eldritch Blast","nameZh":"魔能爆","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你操控元素，在施法距离内创造下述效应之一。\n召气Beckon Air。你在一处5尺立方区域内创造一股和风，其足以吹动布料、搅动灰尘、使落叶沙沙作响、关闭开着的门和百叶窗。若开着的门/百叶窗被某人/某物顶住，则其不受该效应影响。召土Beckon Earth。你创造灰尘或沙子组成的薄帷，覆盖在5尺立方区域内的表面上，或者你可以在一堆泥土或沙子中使一个单词以你的手写体出现。召火Beckon Fire。你在一处5尺立方区域内创造一片无害余烬与一股富有色彩和气味的烟。你选择烟的色彩和气味，而余烬可以点燃区域中的蜡烛、火把或油灯。烟的气味会存留1分钟。召水Beckon Water。你在一处5尺立方范围内创造一片凉爽的，使范围内生物和物件略微潮湿的雾气。或者，你可以在一个有开口的容器或表面上创造出一杯干净的水，水会在1分钟内蒸发。塑形元素Sculpt Element。你使1尺立方区域内的泥土、沙子、火焰、烟尘、雾气或水呈现出一个粗略的形状（如一名生物），持续1小时。","duration":"立即","higherLevels":null,"id":"Elementalism","level":0,"nameEn":"Elementalism","nameZh":"四象法门","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你对施法距离内一名生物或物件掷出一把火焰，对目标进行一次远程法术攻击。命中则目标将受到1d10火焰伤害。未被着装或携带的可燃物件被该法术命中时将开始燃烧。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d10：5级（2d10）、11级（3d10）、17级（4d10）。"},"id":"Fire_Bolt","level":0,"nameEn":"Fire Bolt","nameZh":"火焰箭","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一些化妆品","raw":"S、M（一些化妆品）","somatic":true,"verbal":false},"concentration":true,"description":"你魔法性地向施法距离内的一名可见生物散发出友谊感。目标必须成功于一次感知豁免，否则其在法术持续时间内陷入魅惑状态。若目标并非类人生物，或者你正在与其战斗，又或者你在过去24小时内曾对其施展过这道法术，则其进行的此次豁免自动成功。\n若目标受到伤害，或你进行一次攻击检定、造成伤害、迫使任何人进行一次豁免，则法术会提早结束。法术结束时，目标会知道他曾被你魅惑。","duration":"专注，至多1分钟","higherLevels":null,"id":"Friends","level":0,"nameEn":"Friends","nameZh":"交友术","range":"10尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一名自愿生物并选择一项技能。直到法术结束为止，受术生物在进行使用到所选技能的任何属性检定时，该次检定具有1d4加值。","duration":"专注，至多1分钟","higherLevels":null,"id":"Guidance","level":0,"nameEn":"Guidance","nameZh":"神导术","range":"触碰","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","术士","法师","奇械师"],"components":{"material":true,"materials":"一只萤火虫或一片磷光苔藓","raw":"V、M（一只萤火虫或一片磷光苔藓）","somatic":false,"verbal":true},"concentration":false,"description":"你触碰一个体型不超过大型，且未被他人携带/着装的物件。在法术终止前，物件将发出20尺半径的明亮光照以及额外20尺的微光光照。光的颜色由你决定。\n该物件被不透明的东西完全遮盖时，其光照也将被遮挡。此法术将在你再次施展它时提前终止。","duration":"1小时","higherLevels":null,"id":"Light","level":0,"nameEn":"Light","nameZh":"光亮术","range":"触碰","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一只漂浮的幽灵手出现在施法距离内你指定的一点。幽灵手持续存在至法术终止。如果幽灵手与你之间的距离超过30尺，则幽灵手将消失不见。若你再次施展了此法术，现存的幽灵手也将提前消失。\n你可以在施展该法术时使用幽灵手实施一个行为：你可以操控一个物件、打开一扇未上锁的门或容器、将一件物品放入或取出一个打开的容器、或是将小瓶中的内容物倾倒出来。\n在后续的回合中，你可以用魔法 动作控制幽灵手再次实施上述行为之一。而作为那次动作的一部分，你还可以令幽灵手移动至多30尺。\n该幽灵手不能攻击，也不能激活魔法物品或承载超过10磅重的物质。","duration":"1分钟","higherLevels":null,"id":"Mage_Hand","level":0,"nameEn":"Mage Hand","nameZh":"法师之手","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","牧师","德鲁伊","术士","法师"],"components":{"material":true,"materials":"两块天然磁石","raw":"V、S、M（两块天然磁石）","somatic":true,"verbal":true},"concentration":false,"description":"该法术修复你所触碰一个物件上的一处破损或裂缝，例如修复一条断裂的链条、一把碎成两半的钥匙、一件撕裂的斗篷、一个漏了的酒袋等。只要破损或断裂处在任意方向上都不超过 1 尺，你就可以不留痕迹地修复它。\n该法术可以物理性地修复一件魔法物品，但无法恢复其上的魔法。\n（编注：奇械师的职业特性直接给予了这一法术，因此这一法术现不在奇械师法术列表上。）","duration":"立即","higherLevels":null,"id":"Mending","level":0,"nameEn":"Mending","nameZh":"修复术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","法师","奇械师"],"components":{"material":true,"materials":"一段铜线","raw":"S、M（一段铜线）","somatic":true,"verbal":false},"concentration":false,"description":"你用指向施法距离内的一名生物并低声说出一段信息。该目标（且只有该目标）会听到这段信息，并且可以用只有你能听见的低语回复你。\n你可以隔着固态物件施展此法术，但你必须熟悉法术目标并知晓其就在阻挡物后方。魔法性的沉默效应，1尺厚的石头、金属或木料，或是一片薄铅都可以阻挡此法术。","duration":"立即","higherLevels":null,"id":"Message","level":0,"nameEn":"Message","nameZh":"传讯术","range":"120尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"指定施法距离内一个你可见的生物，你试图暂时刺入目标的心灵。目标必须通过一次智力豁免 。豁免失败将受到1d6点心灵伤害，并且其在你的下回合结束前，进行的下一次豁免检定将获得1d4减值。","duration":"1轮","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d6：5级（2d6）、11级（3d6）、17级（4d6）。"},"id":"Mind_Sliver","level":0,"nameEn":"Mind Sliver","nameZh":"心灵之楔","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"少量羊毛","raw":"S、M（少量羊毛）","somatic":true,"verbal":false},"concentration":false,"description":"你在施法距离内创造一段声响或一个物件的影像，并使之维持至法术持续时间结束，详见以下对应效应的描述。你可以再次施展该法术来终止幻象。\n生物用研究动作调查该声响或影像时，其必须进行一次对抗该法术豁免 DC 的智力（调查）检定，检定成功则判断出是幻象。对于识破幻象的生物而言，幻象会变得模糊不清。\n声响Sound。如果你创造一段声响，其音量可以是低声耳语也可以是高声尖叫。它可以是你或其他任何人的嗓音，或者是一头狮子的咆哮、一段鼓声以及任何你指定的其他声响。声响在持续时间内不会减弱，或者你也可以于法术终止前在不同的时间段创造几段分散的声响。影像Image。如果你创造一个物件的影像，比如一把椅子、泥泞的脚印、一个小箱子等，则该物件各方向上大小不得大于5尺立方区域。该影像不具有声音、光亮、味道或任何其他的感官效应。由于影像可以被任何物体穿透，因此与之进行物理互动时都会揭露其幻象的本质。","duration":"1分钟","higherLevels":null,"id":"Minor_Illusion","level":0,"nameEn":"Minor Illusion","nameZh":"次级幻象","range":"30尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向施法距离内一个你可见的生物喷出一股毒气。对目标进行一次远程法术攻击。命中时，目标将受1d12点毒素伤害。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d12：5级（2d12）、11级（3d12）、17级（4d12）。"},"id":"Poison_Spray","level":0,"nameEn":"Poison Spray","nameZh":"毒气喷涌","range":"30尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内创造一个魔法效应。从下述效应中选择一项。如果你多次施展该法术，则可以同时维持至多三个不同的非即时效应。\n感官效应Sensory Effect。 你创造一个立即生效的，无害的感官效应，比如一束火花，一阵风，微弱音乐或古怪的臭味。玩火Fire Play。 你立即点燃或熄灭一根蜡烛、一根火把或一处小篝火。清洁或弄脏Clean or Soil。 你立即清洁或弄脏一个体积不大于1立方尺的物件。次级感觉Minor Sensation。 你使一个不大于1立方尺的非活体物质变冷、变暖或对其调味，持续1小时。魔法印记Magic Mark。 你在一个物件或一个表面上创造一块色斑，一个小印记，或者一个徽记，持续1小时。次级造物Minor Creation。 你创造出一个非魔法小饰品或一张虚幻图像，其大小不能超过你的手掌大小，它会持续存在至下个你的回合结束为止。一个小饰品不能造成伤害，也不值任何钱。","duration":"至多1小时","higherLevels":null,"id":"Prestidigitation","level":0,"nameEn":"Prestidigitation","nameZh":"魔法伎俩","range":"10尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一朵摇曳的火焰出现在你手中，火焰会存在至法术持续时间结束为止。火焰在你手中期间，不会散发任何热量也不会点燃任何东西，发出20尺半径的明亮光照，以及其外20尺范围的微光光照 。此法术会在你再次施展它时提前终止。\n直到法术结束为止，你可以用魔法动作向60尺内的一名生物或一个物件丢出火焰。进行一次远程法术攻击。命中时，目标将受到1d8点火焰伤害。\n戏法强化。 到达特定等级后，此戏法的伤害将增加1d8：5级（2d8）、11级（3d8）、17级（4d8）。","duration":"10分钟","higherLevels":null,"id":"Produce_Flame","level":0,"nameEn":"Produce Flame","nameZh":"燃火术","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一道蓝白色的冰冷光束朝施法距离内的一名生物射去。对目标进行一次远程法术攻击。命中时，目标将受到1d8点寒冷伤害，且其速度将被减少10尺，直到你的下一回合开始为止。\n戏法强化。 到达特定等级后，此戏法的伤害将增加1d8：5级（2d8）、11级（3d8）、17级（4d8）。","duration":"立即","higherLevels":null,"id":"Ray_of_Frost","level":0,"nameEn":"Ray of Frost","nameZh":"冷冻射线","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一名自愿生物并选择一种伤害类型：强酸、钝击、寒冷、火焰、闪电、暗蚀、穿刺、毒素、光耀、挥砍、雷鸣。在此法术结束之前，每当该生物受到所选类型伤害时，那名生物所受的总伤害减少1d4。一名生物一回合只能受到一次该法术的增益。","duration":"专注，至多1分钟","higherLevels":null,"id":"Resistance","level":0,"nameEn":"Resistance","nameZh":"抵抗术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"如同烈焰般的辉光向着施法距离内你能看见的一名生物倾泻而下。目标必须要通过一次敏捷豁免，否则将受到1d8点光耀伤害。在这次豁免检定中，目标无法享受来自半身掩护和四分之三掩护 的增益。\n戏法强化。该法术的伤害会在你达到下列等级时增加1d8：5级（2d8），11 级（3d8），17 级（4d8）。","duration":"立即","higherLevels":null,"id":"Sacred_Flame","level":0,"nameEn":"Sacred Flame","nameZh":"圣火术","range":"60 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊"],"components":{"material":true,"materials":"槲寄生","raw":"V、S、M（槲寄生）","somatic":true,"verbal":true},"concentration":false,"description":"你将自然之力灌入手中持握的一根短棒或长棍中。你在法术持续时间内使用该武器进行近战攻击时，可以用你的施法属性代替力量属性来进行攻击检定和伤害掷骰，且该武器的伤害骰变为d8。此类攻击造成伤害时，你可以选择将其伤害类型改为力场伤害，或是维持武器原本的伤害类型。你再次施展该法术或丢掉该武器时，该法术也随之终止。","duration":"1分钟","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，受术武器的伤害骰会改变：5级（1d10），11级（1d12），17级（2d6）。"},"id":"Shillelagh","level":0,"nameEn":"Shillelagh","nameZh":"橡棍术","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你放出闪电，击向一名你试图触碰的生物。对目标发动一次近战法术攻击。若命中，则目标受到 1d8 点闪电伤害，并且在其下一回合开始前不能执行借机攻击。\n戏法强化。 到达特定等级后，此戏法的伤害将增加1d8：5级（2d8）、11级（3d8）、17级（4d8）。","duration":"立即","higherLevels":null,"id":"Shocking_Grasp","level":0,"nameEn":"Shocking Grasp","nameZh":"电爪","range":"触碰","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向施法距离内的一名生物或一个物件施展术法能量。对目标进行一次远程攻击检定，命中时，目标将受到1d8点伤害。由你选择法术造成何种类型的伤害：强酸，寒冷，火焰，闪电，毒素，心灵或雷鸣。\n如果你在此法术的任一d8骰上丢出了8，你便可以立刻再丢一枚d8，并将其加入此法术的伤害中。施展此法术时，你最多以此法造成的额外d8伤害骰数量等同于你的施法属性调整值。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的初始伤害将增加1d8：5级（2d8）、11级（3d8）、17级（4d8）。"},"id":"Sorcerous_Burst","level":0,"nameEn":"Sorcerous Burst","nameZh":"术法爆发","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"选择施法距离内一名生命值为0但还未死亡的生物，使该生物变为伤势稳定。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此法术的施法距离将翻倍：5级（30尺），11级（60尺），17级（120尺）。"},"id":"Spare_the_Dying","level":0,"nameEn":"Spare the Dying","nameZh":"维生术","range":"15尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你对施法距离内一名生物或一个物件射出一点光芒。对目标进行一次远程法术攻击。命中时，目标将受到1d8点光耀伤害，并且直到你的下个回合结束前，它会散发出10尺微光光照，且无法受益于隐形 状态。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d8：5级（2d8），11 级（3d8），17 级1d8（4d8）。"},"id":"Starry_Wisp","level":0,"nameEn":"Starry Wisp","nameZh":"点点星芒","range":"60 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你在施法距离内显现一道次级奇迹。你在施法距离内创造下述效应之一。如果你多次施展该法术，则可以同时维持至多三个不同的1分钟效应。\n改变眼睛Altered Eyes。 你改变自己眼睛的外观，其效应持续1分钟。扩音Booming Voice。 你的语音音量变为通常情况下的三倍大，其效应持续1分钟。在此期间，你在魅力（威吓）检定上具有优势 。玩火Fire Play。 你使一团火焰闪烁、变亮、变暗或变色，其效应持续1分钟。看不见的手Invisible Hand。 你使一扇没有上锁的门/窗立即打开或关上。幻音Phantom Sound。 指定施法距离内的一点，你使该点发出一道短暂的声音，例如雷鸣声，渡鸦叫声或不祥低语声。震动Tremors。 你在地面上引发无害的震动，其效应持续1分钟。","duration":"1分钟","higherLevels":null,"id":"Thaumaturgy","level":0,"nameEn":"Thaumaturgy","nameZh":"奇术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","奇械师"],"components":{"material":true,"materials":"一根带刺植物茎","raw":"V、S、M（一根带刺植物茎）","somatic":true,"verbal":true},"concentration":false,"description":"你创造出一条藤蔓般的带刺长鞭，并猛抽向施法距离内一个你指定的生物。对目标进行一次近战法术攻击，命中时，目标将受到1d6点穿刺伤害，如果目标生物的体型不超过大型，则你还可以将其朝你所在位置拉近至多10尺。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d6：5级（2d6）、11级（3d6）、17级（4d6）。"},"id":"Thorn_Whip","level":0,"nameEn":"Thorn Whip","nameZh":"荆棘之鞭","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":false,"description":"位于以你为原点5尺光环区域内的每名生物必须成功于一次体质豁免，否则受到1d6点雷鸣伤害。此法术会创造出在100尺内都能听见的巨大声响。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d6：5级（2d6）、11级（3d6）、17级（4d6）。"},"id":"Thunderclap","level":0,"nameEn":"Thunderclap","nameZh":"鸣雷破","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你对着施法距离内一名你可见的生物一指，随后目标10尺内响起一阵哀恸的钟鸣。目标必须通过一次感知豁免，否则将受到1d8点暗蚀伤害。若目标豁免失败时已损失任意数量生命值，则改为令其受到1d12点暗蚀伤害。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害骰将增加一枚：5级（2d8或2d12）、11级（3d8或3d12）、17级（4d8或4d12）。"},"id":"Toll_the_Dead","level":0,"nameEn":"Toll the Dead","nameZh":"亡者丧钟","range":"60尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师","奇械师"],"components":{"material":true,"materials":"一把价值1+CP的你熟练的武器","raw":"S、M（一把价值1+CP的你熟练的武器）","somatic":true,"verbal":false},"concentration":false,"description":"你受到一瞬魔法洞见的指引，使用施展此法术时使用的那把武器发动一次攻击。此次攻击使用你的施法属性（而非力量属性或敏捷属性）进行攻击检定与伤害掷骰。此次攻击造成伤害时，你可以选择将其伤害类型改为光耀伤害，或是维持武器原本的伤害类型。\n（译注：根据术语汇编武器攻击条目，“使用武器发动的攻击”就是“武器攻击”（与“法术攻击”并不冲突）。）","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，无论你选择造成光耀伤害还是原本类型的伤害，本次攻击都会额外造成光耀伤害：5级（1d6）、11级（2d6）、17级（3d6）。"},"id":"True_Strike","level":0,"nameEn":"True Strike","nameZh":"克敌先击","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你对施法距离内一名你能看见或听见的生物连珠炮式地释出一串蕴涵微妙惑控的侮辱。目标必须通过一次感知豁免，否则受到1d6点心灵伤害，且在其下一回合结束前，其进行的下一次攻击检定具有劣势。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d6：5级（2d6）、11级（3d6）、17级（4d6）。"},"id":"Vicious_Mockery","level":0,"nameEn":"Vicious Mockery","nameZh":"恶言相加","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":true,"materials":"一枚艳阳标志","raw":"V、M（一枚艳阳标志）","somatic":false,"verbal":true},"concentration":false,"description":"灼热的光辉喷薄而出，覆盖你周身5尺光环区域。每个区域中你可见且受你选择的生物必须通过一次体质豁免，否则受到1d6点光耀伤害。","duration":"立即","higherLevels":{"kind":"戏法强化","text":"到达特定等级后，此戏法的伤害将增加1d6：5级（2d6）、11级（3d6）、17级（4d6）。"},"id":"Word_of_Radiance","level":0,"nameEn":"Word of Radiance","nameZh":"光耀祷词","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"1 分钟或仪式","classes":["游侠","法师","奇械师"],"components":{"material":true,"materials":"一个小铃铛和一小段银线","raw":"V、S、M（一个小铃铛和一小段银线）","somatic":true,"verbal":true},"concentration":false,"description":"你设置一个针对不速之客的警报。在施法距离内指定一扇门窗或选择一个边长不大于20 尺的立方区域。在法术持续时间内，任何触碰或进入被法术保护区域的生物都会触发警报。施法时，你可以决定哪些生物不会触发警报，还可以选择警报方式为声音警报或是精神警报。\n声音警报Audible Alarm。警报将在其保护区域 60 尺范围内响起持续 10 秒的摇铃声。精神警报Mental Alarm。 如果你距离目标区域不超过 1 里，警报会在你脑海中会传来“乒”的警报声。如果你在睡觉，则警报将使你惊醒。","duration":"8 小时","higherLevels":null,"id":"Alarm","level":1,"nameEn":"Alarm","nameZh":"警报术","range":"30 尺","ritual":true,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","游侠"],"components":{"material":true,"materials":"一点食物","raw":"V、S、M（一点食物）","somatic":true,"verbal":true},"concentration":false,"description":"在施法距离内指定一只你能看见的野兽。该野兽必须通过一次感知豁免，否则在法术持续时间内陷入魅惑状态。如果你或你的盟友对目标造成伤害，法术将提前终止。","duration":"24 小时","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，就可以多选择一个野兽作为目标。"},"id":"Animal_Friendship","level":1,"nameEn":"Animal Friendship","nameZh":"化兽为友","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["魔契师"],"components":{"material":true,"materials":"一块蓝色玻璃碎片","raw":"V、S、M（一块蓝色玻璃碎片）","somatic":true,"verbal":true},"concentration":false,"description":"防护性的魔法寒霜包裹着你。 你获得5临时生命值 。在法术结束之前，若有生物以近战攻击检定命中你，该生物将受到5寒冷伤害。此法术会在你不具有临时生命值时提前结束。","duration":"1 小时","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，临时生命和寒冷伤害就各提升5。"},"id":"Armor_of_Agathys","level":1,"nameEn":"Armor of Agathys","nameZh":"黯冰狱铠","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你祈唤哈达的力量，让触须从你身上蔓延而出。源自你的10尺光环 区域内，每个生物都必须进行一次力量豁免。豁免失败的生物将受到2d6点暗蚀伤害，并其直到下一回合前都无法执行反应。豁免成功的生物仅受到一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，法术的伤害就增加1d6点。"},"id":"Arms_of_Hadar","level":1,"nameEn":"Arms of Hadar","nameZh":"哈达之臂","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","魔契师"],"components":{"material":true,"materials":"一滴血","raw":"V、S、M（一滴血）","somatic":true,"verbal":true},"concentration":true,"description":"你选择施法距离内至多三个你可见的生物，迫使其分别进行一次魅力豁免。在法术终止前，豁免失败于此次魅力豁免的目标进行的每次攻击检定与豁免检定都必须承受1d4的减值。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Bane","level":1,"nameEn":"Bane","nameZh":"灾祸术","range":"30尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":true,"materials":"一枚价值5+GP的圣徽","raw":"V、S、M（一枚价值5+GP的圣徽）","somatic":true,"verbal":true},"concentration":true,"description":"你祝福施法范围内至多三个生物。在法术终止前，受术目标进行的每次攻击检定与豁免检定都将获得1d4的加值。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Bless","level":1,"nameEn":"Bless","nameZh":"祝福术","range":"30尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向前喷射出一片火焰。处于15尺锥状区域内的生物必须进行一次敏捷豁免。豁免失败者受到3d6火焰伤害，豁免成功者受到一半伤害。\n在此锥状区域内的未被着装或携带的易燃物件会开始燃烧。","duration":"立即","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，此法术的伤害就会提升1d6。"},"id":"Burning_Hands","level":1,"nameEn":"Burning Hands","nameZh":"燃烧之手","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"选择法术距离内你可见的一名类人生物，迫使该生物进行一次感知豁免，如果你或者你的同伴正在与它战斗，它进行的这次豁免将具有优势。如果它豁免失败，它陷入魅惑状态直到法术结束，或者直到你或你的同伴对它造成伤害。被魅惑的生物将对你友好。在法术结束时，生物会知道它曾被你魅惑。","duration":"1 小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Charm_Person","level":1,"nameEn":"Charm Person","nameZh":"魅惑类人","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一枚价值50GP+的钻石","raw":"V、S、M（一枚价值50GP+的钻石）","somatic":true,"verbal":true},"concentration":false,"description":"你向施法距离内某个目标掷出一颗能量球。从强酸、寒冷、火焰、闪电、毒素、雷鸣中选择一个作为创造出来的球体的伤害类型，然后对该目标发动一次远程法术攻击。命中时，该目标将受到 3d8 点你所选类型的伤害。\n如果你的d8骰中有两枚（或更多）投出了相同的数字，能量球将会从原目标跃向其周围30尺内由你所选择的另一个目标。你需要对新目标再进行一次攻击检定，然后进行一次新的伤害掷骰。能量球无法再次进行此种跳跃，除非你施展此法术时使用了环阶2+的法术位。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每高一环，法术的伤害就增加1d8。能量球能够跳跃的最大次数等同于所消耗的法术位环阶，但每次施展此法术时，每名生物只能被指定为此法术目标一次。"},"id":"Chromatic_Orb","level":1,"nameEn":"Chromatic Orb","nameZh":"繁彩球","range":"90 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一撮彩色沙子","raw":"V、S、M（一撮彩色沙子）","somatic":true,"verbal":true},"concentration":false,"description":"你射出一道炫目的闪耀彩光。以你为源点的15尺锥状区域内的每个生物必须成功通过一次体质豁免，否则陷入目盲状态，持续至下个你的回合结束。","duration":"立即","higherLevels":null,"id":"Color_Spray","level":1,"nameEn":"Color Spray","nameZh":"七彩喷射","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你对施法距离内一个你能看见的生物说出一个单词的命令。目标生物必须通过一次感知豁免，否则在它自己的下一回合中，其必须服从这道命令行事。从以下选项中选择一条命令：\n过来Approach。目标以最短最直接的路线向你移动，若其到达你5尺范围内，其会结束自己的回合。 放下Drop。目标放下持握的任何东西，然后结束自己的回合。 走开Flee。目标消耗其整个回合，以最快最有效的方式远离你。 趴下Grovel。目标陷入倒地状态并结束自己的回合。 立定Halt。在其回合内，目标不进行移动且不作任何动作和附赠动作。\n升环施法。使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。","duration":"立即","higherLevels":null,"id":"Command","level":1,"nameEn":"Command","nameZh":"命令术","range":"60 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你尝试强令一名生物与你决斗。选择施法距离内一名你可见的生物，该生物必须成功通过一次感知豁免，豁免失败则，该生物对除你之外任何生物进行攻击检定时都具有劣势，且该生物不能自主移动到距离你超过30尺的位置。当你攻击另一名生物时，当你对另一名敌对生物施展法术时，当一名你的盟友对该目标造成伤害或者对其施展伤害性法术时，又或者你在距离该目标超过 30 尺的位置结束你的回合时，该法术提前终止。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Compelled_Duel","level":1,"nameEn":"Compelled Duel","nameZh":"强令对决","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一撮煤灰和盐","raw":"V、S、M（一撮煤灰和盐）","somatic":true,"verbal":true},"concentration":false,"description":"你在法术持续时间内知晓你所听到或看到手语的所有语言的字面意义。你也可以通过触碰书写的文字来读懂其字面意义。以这种方式阅读每页文字需要花费 1 分钟的时间。这个法术并不能解读符号和暗语。","duration":"1 小时","higherLevels":null,"id":"Comprehend_Languages","level":1,"nameEn":"Comprehend Languages","nameZh":"通晓语言","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊"],"components":{"material":true,"materials":"水沙混合物","raw":"V、S、M（水沙混合物）","somatic":true,"verbal":true},"concentration":false,"description":"你选择其一执行：\n造水术Create Water。你在施法距离内一个打开的容器中创造至多10加仑干净的水。作为另一种选项，你使施法距离内一处30尺的立方区域降下雨水并浇灭区域内不受遮盖的火焰。枯水术Destroy Water。你使施法距离内一个打开的容器里至多10加仑水枯竭不见。作为另一种选项，你使施法距离内一片30尺立方 区域的浓雾消失不见。\n升环施法。 使用的法术位每比一环高一环，法术就多创造或多枯竭10加仑额外的水分，另一种选项能影响的立方 区域边长增加5尺。","duration":"立即","higherLevels":null,"id":"Create_or_Destroy_Water","level":1,"nameEn":"Create or Destroy Water","nameZh":"造水术/枯水术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触碰的一名生物恢复等同于2d8+你施法属性调整值点生命值。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的治疗量就增加2d8点。"},"id":"Cure_Wounds","level":1,"nameEn":"Cure Wounds","nameZh":"疗伤术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"此法术会被1尺厚的岩石、泥土或木头，1寸厚的金属，或薄薄一层铅阻隔。","duration":"专注，至多10分钟","higherLevels":null,"id":"Detect_Evil_and_Good","level":1,"nameEn":"Detect Evil and Good","nameZh":"侦测善恶","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，你感受到距你30尺内的魔法效应。若你感知到了此类效应，则你可以用一个魔法动作以看到任何带有该魔法效应的可见生物或物件周围环绕着的微弱灵光，且若该魔法效应属于被法术创造的效应，则你可分辨出其所属的魔法学派。\n此法术会被1尺厚的岩石、泥土或木头，1寸厚的金属，或薄薄一层铅阻隔。","duration":"专注，至多10分钟","higherLevels":null,"id":"Detect_Magic","level":1,"nameEn":"Detect Magic","nameZh":"侦测魔法","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","德鲁伊","圣武士","游侠"],"components":{"material":true,"materials":"一片紫杉叶","raw":"V、S、M（一片紫杉叶）","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，你定位距你30尺内的毒药、有毒生物和魔法疫病。你可以感知到毒药、有毒生物和疫病的种类。\n此法术会被1尺厚的岩石、泥土或木头，1寸厚的金属，或薄薄一层铅阻隔。","duration":"专注，至多10分钟","higherLevels":null,"id":"Detect_Poison_and_Disease","level":1,"nameEn":"Detect Poison and Disease","nameZh":"侦测毒性和疾病","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你改变自身以及随身的衣物、护甲、武器等在你身上的所有物。该效应在法术终止时结束。肉眼看来你的身高可以有1尺的增减，体态可胖可瘦。你必须选择一个和你肢体基础排列方式一致的形态。此外，幻术的影响范围由你决定。\n此法术产生的变化无法应对物理检查。比如，你用此法术添了一顶帽子，那么现实物件会从帽子穿过去，且任何触碰帽子的人将摸不到任何东西。\n如果一名生物想要分辨你是否易容，则必须使用一个研究动作研究你的外貌，并成功于一次对抗你法术豁免DC的智力（调查）检定。","duration":"1小时","higherLevels":null,"id":"Disguise_Self","level":1,"nameEn":"Disguise Self","nameZh":"易容术","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"一名施法距离内你选择的可见生物的心灵中听见一段不协和旋律。目标进行一次感知豁免。豁免失败则受到3d6点心灵伤害，并立即执行其反应（若可用）尽可能往远离你的方向移动，并采取最安全的路径。豁免成功则只受一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，伤害就提高1d6。"},"id":"Dissonant_Whispers","level":1,"nameEn":"Dissonant Whispers","nameZh":"不谐低语","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"直到法术结束之前，你使用武器的攻击在命中时造成额外1d4点光耀伤害。","duration":"1分钟","higherLevels":null,"id":"Divine_Favor","level":1,"nameEn":"Divine Favor","nameZh":"神恩","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到2d8点光耀伤害。若目标为邪魔生物或亡灵生物，则此伤害增加1d8。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的伤害就提高1d8。"},"id":"Divine_Smite","level":1,"nameEn":"Divine Smite","nameZh":"至圣斩","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作，在你用武器命中目标后立即可用","classes":["游侠"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"你命中目标时，目标身上出现一根紧紧将其攫住的藤蔓，使其进行一次力量豁免，大型及更大体型的生物进行该豁免时具有优势。豁免失败，则目标将直到法术结束为止陷入束缚状态。豁免成功，则藤蔓立即枯萎，法术结束。\n处于束缚状态期间，目标在其每回合开始受到1d6点穿刺伤害。目标或其他位于其触及内的生物可用一个动作进行一次对抗法术豁免DC的力量（运动）检定。检定成功则法术结束。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的伤害就提高1d6点。"},"id":"Ensnaring_Strike","level":1,"nameEn":"Ensnaring Strike","nameZh":"捕获打击","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"缠绕的植物在施法距离内从20尺方状区域地面中破土而出。在法术持续时间内，这片被植物覆盖的区域变为困难地形 。法术结束时，这些植物会消失。\n在你施展法术时，该区域内的生物（除你之外）必须成功于一次力量豁免，否则陷入束缚状态，直到法术终止。一名因此被束缚的生物可以用其动作进行一次力量（运动）检定对抗该法术的豁免DC。检定成功则成功摆脱缠绕在其身上的藤蔓并不再被其束缚。","duration":"专注，至多1分钟","higherLevels":null,"id":"Entangle","level":1,"nameEn":"Entangle","nameZh":"纠缠术","range":"90尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你执行疾走动作，且直到法术结束为止，你均能使用附赠动作执行疾走 动作。","duration":"专注，至多10分钟","higherLevels":null,"id":"Expeditious_Retreat","level":1,"nameEn":"Expeditious Retreat","nameZh":"脚底抹油","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","奇械师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"施法距离内一处20尺立方区域内每个物件的轮廓都将被蓝色、绿色、或紫色的光芒所勾勒（颜色由你指定）。区域内的生物则必须进行一次敏捷豁免，豁免失败时会被彩色光芒勾勒出轮廓。受术物件和生物在法术持续时间内发出10尺半径的微光光照 。\n受术生物或物件无法受益于隐形状态，且任何能看见他们的攻击者对其发动的攻击检定具有优势。","duration":"专注，至多1分钟","higherLevels":null,"id":"Faerie_Fire","level":1,"nameEn":"Faerie Fire","nameZh":"妖火","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一滴酒精","raw":"V、S、M（一滴酒精）","somatic":true,"verbal":true},"concentration":false,"description":"你获得2d4+4点临时生命值。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，其给予的临时生命值就增加5。"},"id":"False_Life","level":1,"nameEn":"False Life","nameZh":"虚假生命","range":"自身","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"反应，你或距你60尺内的可见生物坠落时可用","classes":["吟游诗人","术士","法师","奇械师"],"components":{"material":true,"materials":"一小根羽毛或一块羽绒","raw":"V、M（一小根羽毛或一块羽绒）","somatic":false,"verbal":true},"concentration":false,"description":"指定施法距离内至多五个正坠落的生物。受术生物的坠落速度在法术持续时间内降低至每回合60尺。如果该生物在法术终止前落地，则其不会受到任何坠落伤害，且着地后法术对该生物的效应随即终止。","duration":"1分钟","higherLevels":null,"id":"Feather_Fall","level":1,"nameEn":"Feather Fall","nameZh":"羽落术","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1小时或仪式","classes":["法师"],"components":{"material":true,"materials":"价值10+GP的焚香，作为法术耗材","raw":"V、S、M（价值10+GP的焚香，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你获得一只为你服务的魔宠，魔宠精魄可以采用下述你选择的动物形态之一：蝙蝠Bat、猫Cat、蛙Frog、隼Hawk、蜥蜴Lizard、章鱼Octopus、猫头鹰Owl、鼠Rat、渡鸦Raven、蜘蛛Spider、鼬Weasel，你也可以选择其他挑战等级为0的野兽作为魔宠的形态。魔宠出现在施法距离内一处未占据空间，虽然有着所选的生物属性数据，但其生物类型为天族、妖精、邪魔之一（由你选择）而非野兽。你的魔宠可脱离你独立行动，不过它会一直遵循你的命令行事。\n心灵连接Telepathic Connection。你的魔宠距你100尺内期间，你可以与其进行心灵交流。此外，你还能够以一个附赠动作将自己的视觉和听觉切换到魔宠的感官，并一持续至你下一回合开始。在此期间，你同时享有该魔宠自身的特殊感官。\n最后，当你施展施法距离为触碰的法术时，你的魔宠可以帮你传递这道触碰法术。此时你的魔宠必须距你100尺内，且在你施展这道法术时你的魔宠需要执行一个反应才能将其传递。\n战斗Combat。魔宠是你和你盟友的盟友。战斗时，它为自己骰先攻，并在自己回合里行动。魔宠无法攻击，但是它能如常执行其他动作。\n魔宠的消失Disappearance of the Familiar。当魔宠生命值降至0点时，它会消失。它会在你再次施展此法术后重新出现。你可以用一个魔法动作，暂时解散你的魔宠，将其送入一个口袋位面。你也可以选择永久解散它。暂时解散时，你可以用一个魔法动作使其重新出现于距你30尺内任意未占空间中。当魔宠生命值归0或消失进入了口袋位面时，它都会将自己穿着或携带的任何物品留在自己曾占据的空间中。\n独一无二One Familiar Only。你在同一时间不能拥有多于一只魔宠。如果你在已拥有一只魔宠期间施展此法术，作为替代，你会使其采用一个新的符合条件的形态。","duration":"立即","higherLevels":null,"id":"Find_Familiar","level":1,"nameEn":"Find Familiar","nameZh":"寻获魔宠","range":"10尺","ritual":true,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你以施法距离内一点为中心创造一片半径20尺的球状浓雾。球状区域被重度遮蔽。浓雾持续至法术持续时间结束，被强风（比如造风术Gust of Wind创造的风）吹散时法术也将提前结束。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，浓雾的半径就增加20尺。"},"id":"Fog_Cloud","level":1,"nameEn":"Fog Cloud","nameZh":"云雾术","range":"120尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"一根槲寄生","raw":"V、S、M（一根槲寄生）","somatic":true,"verbal":true},"concentration":false,"description":"10颗浆果出现在你手里。果子在法术持续时间内充满魔法。一名生物可以用一个附赠动作 吃下一颗浆果。吃掉一颗浆果者恢复1生命值，且一枚浆果就可以满足该生物一整天的营养需求。\n法术结束时还没有被吃掉的浆果会消失。","duration":"24小时","higherLevels":null,"id":"Goodberry","level":1,"nameEn":"Goodberry","nameZh":"神莓术","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一块猪皮或黄油","raw":"V、S、M（一块猪皮或黄油）","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内指定一点，光滑的不可燃油脂以该点为中心覆盖一处10尺的方状区域。在法术持续时间内。该区域变为困难地形 。\n油脂出现时，站在其范围内的每个生物必须成功通过一次敏捷豁免，否则陷入倒地状态。进入该区域或在区域内结束其回合的生物也必须进行该敏捷豁免，豁免失败则陷入倒地。","duration":"1分钟","higherLevels":null,"id":"Grease","level":1,"nameEn":"Grease","nameZh":"油腻术","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向施法距离内的一名生物掷出一道光箭。对目标进行一次远程法术攻击。命中时，目标受4d6点光耀伤害。在你下个回合结束前，对目标发动的下一次攻击检定具有优势。","duration":"1轮","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的伤害就增加1d6点。"},"id":"Guiding_Bolt","level":1,"nameEn":"Guiding Bolt","nameZh":"光导箭","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"1附赠动作，在你使用远程武器命中一个生物时紧接可用","classes":["游侠"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"当你攻击命中生物时，法术会从你的远程武器或弹药中创造出棘刺，并形成一片棘刺之雨。目标和在目标周围5尺内每个生物必须进行一次敏捷豁免检定，豁免失败者将受到 1d10 点穿刺伤害，豁免成功则受到一半伤害。\n升环施法。使用的法术位每比一环高一环，此法术的伤害就增加 1d10。","duration":"立即","higherLevels":null,"id":"Hail_of_Thorns","level":1,"nameEn":"Hail of Thorns","nameZh":"荆棘之雨","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["吟游诗人","牧师","德鲁伊"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你指定施法距离内一个你能看见的生物并恢复其生命值，恢复量等于2d4+你的施法属性调整值。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的治疗量就增加2d4点。"},"id":"Healing_Word","level":1,"nameEn":"Healing Word","nameZh":"治愈真言","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"反应，当你受到来自60尺内你可见生物的伤害时执行。","classes":["魔契师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"伤害你的生物立刻被绿色的烈焰席卷。该生物必须进行一次敏捷豁免，豁免失败则受到2d10点火焰伤害，豁免成功则受到一半伤害。\n升环施法。 使用的法术位每比一环高一环，此法术的伤害就增加1d10点。","duration":"立即","higherLevels":null,"id":"Hellish_Rebuke","level":1,"nameEn":"Hellish Rebuke","nameZh":"炼狱叱喝","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一个自愿生物使其充满勇气。该生物直至法术终止前免疫恐慌状态，且它将在其每回合开始时获得等同于你施法属性调整值的临时生命值。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Heroism","level":1,"nameEn":"Heroism","nameZh":"英雄气概","range":"触碰","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["魔契师"],"components":{"material":true,"materials":"一只风干的蝾螈眼","raw":"V、S、M（一只风干的蝾螈眼）","somatic":true,"verbal":true},"concentration":true,"description":"你对施法距离内一个你能看见的一个生物施加诅咒。每当你以攻击检定命中该目标时，你对其额外造成1d6暗蚀伤害，直至法术结束。此外，你在施展该法术时选择一项属性，使该目标进行所选属性的属性检定时具有劣势 。\n如果目标在法术终止前 HP 降至 0，则你可以在法术终止前后续的某一回合中使用一个附赠动作 诅咒另一个生物。\n升环施法。 使用二环法术位施展该法术时，其专注可以维持至多4小时。使用三环或四环法术位施展该法术时，其专注可以维持至多8小时。使用环阶5+的法术位施展该法术时，其专注可以维持至多 24 小时。","duration":"专注，至多1小时","higherLevels":null,"id":"Hex","level":1,"nameEn":"Hex","nameZh":"脆弱诅咒","range":"90尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["游侠"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"你指定施法距离内一个你能看见的生物并以魔法标记其作为你的猎物。每当你以攻击检定命中该目标时，你对其额外造成1d6力场伤害，且每当你为寻找目标生物而进行感知（察觉或求生）检定时都具有优势，直至法术结束。\n如果在法术结束前目标 HP 降至 0，则你可以用附赠动作 将标记转移至施法距离内的另一个可见生物。\n升环施法。使用三环或四环法术位施展该法术时，其专注可以维持至多8小时。使用环阶5+的法术位施展该法术时，其专注可以维持至多 24 小时。","duration":"专注，至多1小时","higherLevels":null,"id":"Hunter's_Mark","level":1,"nameEn":"Hunter's Mark","nameZh":"猎人印记","range":"90尺","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一滴水或一块冰","raw":"S、M（一滴水或一块冰）","somatic":true,"verbal":false},"concentration":false,"description":"你制造出一块冰晶裂片，并将它射向施法距离内的一个生物。你对目标进行一次远程法术攻击。若击中，目标受到 1d10 点穿刺伤害。无论击中与否，裂片都会在那之后立刻爆裂。攻击目标和其5尺范围内的每名生物都必须通过一次敏捷豁免检定，否则将受到 2d6 点寒冷伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，寒冷伤害就增加1d6。"},"id":"Ice_Knife","level":1,"nameEn":"Ice Knife","nameZh":"冰刃","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["吟游诗人","法师","奇械师"],"components":{"material":true,"materials":"一颗价值100GP+的珍珠","raw":"V、S、M（一颗价值100GP+的珍珠）","somatic":true,"verbal":true},"concentration":false,"description":"你需要在施法过程中与某个物件保持接触。如果该物件是魔法物品之类的魔法性物件，你将知晓其属性和使用方式，以及了解是否需要同调、剩余多少充能数（若其有）。你还可以发现是否有法术正影响着该物件，以及这些法术具体是什么。如果该物件是由法术创造出来的物件，你将知晓该法术的名称。\n你也可以改为在施法过程中一直接触一名生物，而你将知晓正在影响该生物的那些法术（若有）是哪些法术。","duration":"立即","higherLevels":null,"id":"Identify","level":1,"nameEn":"Identify","nameZh":"鉴定术","range":"触碰","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"价值 10+GP 的墨水，作为法术耗材","raw":"V、S、M（价值 10+GP 的墨水，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你在羊皮纸，纸张或是其他适合书写的材质上书写文字并对其施加一个强力的幻象。其效应将持续至法术终止。\n文件对于你和你施法时所指定的生物而言是一份普通的文件，文件内容即是以你的笔迹传达你写下手稿时想要传达的一切意义。而对于所有其他阅读者而言，该文件看起来就像由难懂的未知文字或魔法文字所书写。此外，你还可以使该文件呈现出完全不同的信息，使其看起来是用另一种笔迹或者语言所书写，不过你必须懂得该语言。\n如果法术被解除，则幻象和原始手稿一同消失不见。\n拥有真实视觉的生物可以读出其内被隐藏的信息。","duration":"10日","higherLevels":null,"id":"Illusory_Script","level":1,"nameEn":"Illusory Script","nameZh":"迷幻手稿","range":"触碰","ritual":true,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你迫使触碰的一名生物进行体质豁免检定，豁免失败将受到 2d10 的暗蚀伤害，豁免成功则受到半数伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比一环高一环，暗蚀伤害就增加1d10。"},"id":"Inflict_Wounds","level":1,"nameEn":"Inflict Wounds","nameZh":"致伤术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":true,"materials":"一只蚱蜢的后腿","raw":"V、S、M（一只蚱蜢的后腿）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个自愿生物。在法术结束前，每该生物他的回合内一次，其可以消耗10尺移动力来跳跃至多30尺距离。","duration":"1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Jump","level":1,"nameEn":"Jump","nameZh":"跳跃术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","游侠","法师","奇械师"],"components":{"material":true,"materials":"一撮泥土","raw":"V、S、M（一撮泥土）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个生物，该目标的速度增加10尺，直至法术结束。","duration":"1 小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外指定一个目标。"},"id":"Longstrider","level":1,"nameEn":"Longstrider","nameZh":"大步奔行","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一块鞣制过的皮革","raw":"V、S、M（一块鞣制过的皮革）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个未着装护甲的自愿生物。直至法术终止前，目标的基础AC变为 13+它的敏捷调整值。当目标穿上护甲时，此法术将提前终止。","duration":"8小时","higherLevels":null,"id":"Mage_Armor","level":1,"nameEn":"Mage Armor","nameZh":"法师护甲","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你创造三枚由魔法力场形成的闪光飞镖，并让每发飞镖袭向施法距离内你能看见的指定生物。每发飞镖对目标造成1d4+1点力场伤害。所有飞镖将同时袭向目标，而你还可以指定它们击中同一个目标或是分别击中几个目标。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，该法术就会多制造出一支飞镖。"},"id":"Magic_Missile","level":1,"nameEn":"Magic Missile","nameZh":"魔法飞弹","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","圣武士","魔契师","法师"],"components":{"material":true,"materials":"一瓶25GP+的圣水，作为此法术的耗材","raw":"V、S、M（一瓶25GP+的圣水，作为此法术的耗材）","somatic":true,"verbal":true},"concentration":true,"description":"法术结束前，你使触碰的一名自愿生物获得针对下述生物类型的防护：异怪、天族、元素、妖精、邪魔、亡灵。\n此防护提供下述几种增益。上述生物类型的生物对目标的攻击检定具有劣势。目标不能被其附身，也不会因其陷入魅惑或恐慌状态。如果目标已经被具有上述生物类型的生物附身，或其魅惑或恐慌状态影响，目标后续进行的相关效应的豁免检定也将具有优势。","duration":"专注，至多10分钟","higherLevels":null,"id":"Protection_from_Evil_and_Good","level":1,"nameEn":"Protection from Evil and Good","nameZh":"防护善恶","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","德鲁伊","圣武士","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"以施法距离内一点为中心，你移除半径5尺球状 区域内非魔法食物与饮品中的毒素和腐败。","duration":"立即","higherLevels":null,"id":"Purify_Food_and_Drink","level":1,"nameEn":"Purify Food and Drink","nameZh":"净化饮食","range":"10尺","ritual":true,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你朝施法距离内一名生物射出一道绿色射线。对目标进行一次远程法术攻击。若命中，则目标受到2d8点毒素伤害且陷入中毒状态，持续至你的下一回合结束。\n升环施法。 使用的法术位每比一环高一环，此法术的伤害就增加1d8点。","duration":"立即","higherLevels":null,"id":"Ray_of_Sickness","level":1,"nameEn":"Ray of Sickness","nameZh":"致病射线","range":"60尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["牧师","奇械师"],"components":{"material":true,"materials":"一块镜子碎片","raw":"V、S、M（一块镜子碎片）","somatic":true,"verbal":true},"concentration":false,"description":"你为施法距离内的一名生物施加守护。在法术终止前，当任何生物将受守护的生物定为其攻击检定或伤害性法术的目标时，该生物都必须成功通过一次感知豁免，否则该生物必须改为选定另一名生物作为新的目标或者失去本次的攻击或法术。不过此法术无法令受术者免受区域效应的影响。\n若受保护生物发动一次攻击，施展一道法术，或是造成任何伤害，则该法术随之终止。","duration":"1 分钟","higherLevels":null,"id":"Sanctuary","level":1,"nameEn":"Sanctuary","nameZh":"庇护术","range":"30 尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个目标后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到1d6火焰伤害。直至法术终止前，目标会在其每个回合开始时受到1d6点火焰伤害，并进行一次体质豁免。豁免失败则法术继续生效，成功则法术终止。","duration":"1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术造成的所有伤害都会增加1d6点。"},"id":"Searing_Smite","level":1,"nameEn":"Searing Smite","nameZh":"炽焰斩","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"反应，当你被攻击命中或被作为魔法飞弹Magic Missile法术的目标时执行","classes":["术士","法师"],"components":{"verbal":true,"somatic":true,"material":false,"materials":"","raw":"V、S"},"concentration":false,"description":"一道看不见的力场制护盾浮现在你身旁，保护着你。在你的下一回合开始前，你的 AC 具有+5加值（在触发该法术的攻击之前生效），并且不会受到魔法飞弹Magic Missle的伤害。","duration":"1 轮","higherLevels":null,"id":"Shield","level":1,"nameEn":"Shield","nameZh":"护盾术","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["牧师","圣武士"],"components":{"material":true,"materials":"一张祷文卷轴","raw":"V、S、M（一张祷文卷轴）","somatic":true,"verbal":true},"concentration":true,"description":"一片闪着微光的能量场围绕着施法距离内你指定的一个生物，使目标在法术持续时间内AC获得+2 加值。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Shield_of_Faith","level":1,"nameEn":"Shield of Faith","nameZh":"虔诚护盾","range":"60 尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"少量羊毛","raw":"V、S、M（少量羊毛）","somatic":true,"verbal":true},"concentration":true,"description":"你创造一个影像，其形象来自一个大小不超过边长 15 尺立方体的物件，生物或其他的可视现象。影像出现在施法距离内的一处位置并在法术持续时间内持续存在。该影像是纯粹的视觉影像；它不会被听觉，嗅觉或其他感官感受到。\n你可以使用魔法动作将影像移动到施法距离内的另一个位置。影像改变位置时，你可以改变影像的外观使其移动得更自然。例如，如果你创造了一个生物的影像并移动它，则你可以改变影像，使它看起来就像是在走路。\n由于影像无法被碰到，任何与该影像进行的物理互动都会暴露其幻象的本质。一个生物使用研究动作调查影像时，它可以进行一次对抗法术豁免 DC 的智力（调查）检定。辨出幻象的生物可以看破该影像，在该生物看来会透过影像看到其背后的事物。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Silent_Image","level":1,"nameEn":"Silent Image","nameZh":"无声幻影","range":"60 尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一把细沙或玫瑰花瓣","raw":"V、S、M（一把细沙或玫瑰花瓣）","somatic":true,"verbal":true},"concentration":true,"description":"以施法距离内一点为源点，5尺半径球状区域内每个你选择的生物都必须成功通过一次感知豁免否则直到其下个回合结束陷入失能状态。在其下个回合结束时，它必须重复此豁免。如果目标第二次豁免失败，目标在持续时间内陷入昏迷状态。若目标受到伤害或其5尺内有人用一个动作将其摇醒，目标身上的法术结束。\n不需要睡眠的生物（例如精灵）或免疫力竭状态的生物自动成功通过对抗此法术的豁免。","duration":"专注，至多1 分钟","higherLevels":null,"id":"Sleep","level":1,"nameEn":"Sleep","nameZh":"睡眠术","range":"60 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","德鲁伊","游侠","魔契师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你在法术持续时间内获得理解野兽生物并用语言与其沟通的能力，并且你可以对它们使用交涉动作时任何技能选项都可以适用。\n大多数野兽在谈及和生存与伙伴无关的话题时能说的很少，但至少，一只野兽能够给你提供周遭的地点和怪物的情报，包括任何它们近一日内察觉到过的东西。","duration":"10 分钟","higherLevels":null,"id":"Speak_with_Animals","level":1,"nameEn":"Speak with Animals","nameZh":"动物交谈","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师","法师"],"components":{"material":true,"materials":"一块甜馅饼和一根羽毛","raw":"V、S、M（一块甜馅饼和一根羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"施法距离内你可见的一名生物进行一次感知豁免。豁免失败，目标在持续时间内陷入失能和倒地状态。在此期间，目标会不受控制地狂笑（只要它能够发笑），且无法结束自身的倒地状态。\n目标在其每回合结束或受到伤害时，可以再进行一次感知豁免。如果豁免是因受到伤害所致，则该次豁免具有优势。豁免成功时，法术终止。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，你就可以额外选择一个生物作为目标。"},"id":"Tasha's_Hideous_Laughter","level":1,"nameEn":"Tasha's Hideous Laughter","nameZh":"塔莎狂笑术","range":"30尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["法师"],"components":{"material":true,"materials":"一滴汞","raw":"V、S、M（一滴汞）","somatic":true,"verbal":true},"concentration":false,"description":"指定施法距离内一处你可见的未占空间，并在该处创造一个圆盘状的碟型水平力场。浮碟直径3尺，厚1寸，悬浮在离地3尺的空中。其可以在法术持续时间内持续存在，并至多可负载500磅重量。如果放在浮碟上的物件重量超过500磅，则该法术终止，浮碟上的所有东西也将掉落至地上。\n浮碟距你20尺内时静止不动。只要你与其距离超过20尺，浮碟就会跟随你移动，并保持在距你20尺范围内。浮碟可以自由跨越崎岖地形、上下阶梯、斜坡面、诸如此类的地面，但它不能越过高差超过10尺的地面。例如，浮碟不能越过一个10尺深的坑；如果将浮碟创造在这个坑的坑底，则它将无法离开这个坑。\n如果你距浮碟超过100尺（通常是因为它受障碍所阻无法跟上你），则法术终止。","duration":"1小时","higherLevels":null,"id":"Tenser's_Floating_Disk","level":1,"nameEn":"Tenser's Floating Disk","nameZh":"谭森浮碟术","range":"30尺","ritual":true,"school":"咒法","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个目标后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你的打击发出距你300尺内都能听见的雷鸣。被该次攻击检定命中的目标会在此次攻击中额外受到2d6点雷鸣伤害，如果目标是一名生物，则它必须成功于一次力量豁免，否则其被向着远离你的方向推离10尺并陷入倒地状态。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，伤害就提高1d6。"},"id":"Thunderous_Smite","level":1,"nameEn":"Thunderous Smite","nameZh":"雷鸣斩","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你释放出一道雷鸣能量。在以你为源点15尺立方区域内的每名生物必须进行一次体质豁免。豁免失败者将受到2d8点雷鸣伤害，并被向远离你的方向推离10尺。豁免成功则只受一半伤害。\n此外，所有完全位于该区域内且未被固定住的物件都将被推离10尺。该法术还会发出距你300尺内都能听见的雷霆巨响。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，伤害就提高1d8。"},"id":"Thunderwave","level":1,"nameEn":"Thunderwave","nameZh":"雷鸣波","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","魔契师","法师"],"components":{"material":true,"materials":"一些线和木头","raw":"V、S、M（一些线和木头）","somatic":true,"verbal":true},"concentration":false,"description":"该法术创造出一个隐形、无心智、无定形的中型力场。你可以在法术终止前命令它进行简单的工作。该仆役被创造出来后出现在施法距离内一处未占空间的地面上。其AC为10，具有1生命值，力量为2，且不能攻击。若仆从的生命值降至 0，则法术终止。\n在每个自己回合内以一个附赠动作 ，你可以精神性的对仆役下达一道命令，使其移动至多15尺并与一个物件进行互动。仆役可以做人类能做到的简单工作，例如拿取东西、打扫卫生、修补东西、叠衣服、点火、上菜、倒饮料等。一旦你下达了命令，仆役就会尽全力去进行任务直至完成任务，并在此后等待你的下一个命令。\n如果你命令仆役做一件需要它离开你身边60尺的工作，则法术终止。","duration":"1小时","higherLevels":null,"id":"Unseen_Servant","level":1,"nameEn":"Unseen Servant","nameZh":"隐形仆役","range":"60尺","ritual":true,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":true,"materials":"一根被闪电击中的树枝","raw":"V、S、M（一根被闪电击中的树枝）","somatic":true,"verbal":true},"concentration":true,"description":"一支缠绕着碎裂魔力的蓝色能量长矛射向施法距离内的一个生物，并在你与目标之间生成一道持久的闪电弧。对目标进行一次远程法术攻击。若命中，则目标受到2d12闪电伤害。\n无论首次攻击是否命中，在你接下来的每个回合中，你都可以用附赠动作直接对目标造成1d12闪电伤害。\n此外，如果目标与你之间的距离超出了法术的施法距离，或者目标相对你而言处于全身掩护状态，法术将提前终止。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，此法术的初始伤害就提高1d12。"},"id":"Witch_Bolt","level":1,"nameEn":"Witch Bolt","nameZh":"巫术箭","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到1d6点暗蚀伤害，并且目标必须通过一次感知豁免检定，否则直到法术结束为止陷入恐慌状态。在自己的每回合结束时，被恐慌的目标可以重复此豁免，成功则结束该法术对自身的影响。","duration":"1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比一环高一环，伤害就提高1d6。"},"id":"Wrathful_Smite","level":1,"nameEn":"Wrathful Smite","nameZh":"激愤斩","range":"自身","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":true,"materials":"一小片白布","raw":"V、S、M（一小片白布）","somatic":true,"verbal":true},"concentration":false,"description":"选择法术距离内至多三个生物。每个目标的生命值上限和当前生命值 在法术持续时间内提高5。","duration":"8 小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，每个目标的生命值 就额外提高5 。"},"id":"Aid","level":2,"nameEn":"Aid","nameZh":"援助术","range":"30 尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你变换了自身形态。施法时，从以下选项中选择其一生效，其效应维持至其持续时间结束。在持续时间内，你还能够以一个魔法动作将效应切换为另一个不同的选项。\n水生适应Aquatic Adaptation。 你长出鳃和蹼。你可以在水下呼吸，并且获得等同于步行速度的游泳速度。 改变外貌Change Appearance。你改变了自己的外貌。你可以自行设定自己的外观：包括身高、体重、面部细节、声线、头发长短、肤色以及（可能具有的）独特外貌特征。你可以让自己的外观形似其他种族的一员而你的任何数据都不会变化。你无法变为一个体型不同的生物，并且你的基础身体轮廓不会变化。例如，如果你两足行动，就不能变为四足生物。你可以在持续时间内以一个魔法动作改变这些外貌细节。 天生武器Natural Weapons。 你长出爪子（挥砍）、獠牙（穿刺）、犄角（穿刺）或蹄（钝击）。当你使用徒手打击以这些新长的器官造成伤害时，它会造成1d6对应类型伤害，而非你通常的徒手打击伤害，并且你使用你的施法属性调整值来作为你该次攻击及其伤害的调整值，而非力量调整值。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Alter_Self","level":2,"nameEn":"Alter Self","nameZh":"变身术","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","德鲁伊","游侠"],"components":{"material":true,"materials":"一点食物","raw":"V、S、M（一点食物）","somatic":true,"verbal":true},"concentration":false,"description":"指定一只在施法距离内你能看见的微型野兽。该生物必须成功通过一次魅力豁免，否则它会为你传递一则消息（如果该生物的挑战等级不是0，则豁免自动成功）。你选择一个你曾造访过的地点，然后描述收信人的基本信息，如“一个穿着城镇守卫制服的男人或女人”或“一个戴着尖顶帽子的红发矮人”。你还需要说出一段不超过二十五个单词的信息。目标野兽 将会在法术持续时间内前往你选定的地点。会飞的信使24小时内可移动50里，不会飞的信使只能移动25里。\n野兽抵达目的地后，会模仿你的声音把信息传递给你描述的人。信使只会把信息传递给符合你描述的人。如果法术持续时间内信使未能抵达目的地则信息将遗失，而曾作为信使的野兽将自行寻路返回你施法的地点。","duration":"24小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比2环高一环，此法术持续时间就增加48小时。"},"id":"Animal_Messenger","level":2,"nameEn":"Animal Messenger","nameZh":"动物信使","range":"30 尺","ritual":true,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"价值25GP+的金粉，作为法术耗材","raw":"V、S、M（价值25GP+的金粉，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个关着的门、窗、容器或出入口，并使目标在法术持续时间内被魔法上锁。秘法锁无法被任何非魔法方式解锁。在你施展法术时你可以选择允许一些其他生物，你和受你允许的生物能够无视秘法锁打开/关闭该物件。你还可以设置一条密语，在该物件5尺内念出密语时，秘法锁将被解锁（持续1分钟）。","duration":"直到被解除","higherLevels":null,"id":"Arcane_Lock","level":2,"nameEn":"Arcane Lock","nameZh":"秘法锁","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你利用自己的生命力来治愈自身。投一枚或两枚你还未消耗的生命骰，然后恢复等于结果加你的施法属性调整值的总和的生命值。随后，这些生命骰会被法术消耗。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，你就能多投掷一枚未使用的生命骰。"},"id":"Arcane_Vigor","level":2,"nameEn":"Arcane Vigor","nameZh":"复苏秘法","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1 分钟或仪式","classes":["牧师","德鲁伊","法师"],"components":{"material":true,"materials":"绘有标记的短棒、骨头、卡片、或类似的预言道具，价值25+GP","raw":"V、S、M（绘有标记的短棒、骨头、卡片、或类似的预言道具，价值25+GP）","somatic":true,"verbal":true},"concentration":false,"description":"你从异界存在处获得对某道有关你在接下来的30分钟内所计划执行的一系列行动之结果的预示。DM从下列预示中选取一个：\n预兆 预兆 预示着… 吉 好的结果。 凶 坏的结果。 吉凶并存 结果既有好的方面，也有坏的方面。 无 结果并无明显的好坏分别。\n该法术将不会对任何环境因素进行解释，比如可能会对结果产生改变的一些其他法术。若你在两次长休之间使用两次或更多次的卜筮术，则法术在第一次施展之后会每次累积25%概率会不给出任何结果。","duration":"立即","higherLevels":null,"id":"Augury","level":2,"nameEn":"Augury","nameZh":"卜筮术","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"一把树皮","raw":"V、S、M（一把树皮）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个自愿生物。直到法术终止前，目标的皮肤呈现出树皮样的外貌，并且若目标AC低于17，则其AC变为17。","duration":"1小时","higherLevels":null,"id":"Barkskin","level":2,"nameEn":"Barkskin","nameZh":"树肤术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":true,"description":"你触碰一只自愿的野兽。在持续期间内，你可以借助该野兽的感官来感知周围事物，如同它们的感官是你的感官一般。以通过该野兽感官感知事物时，你同样会受益于它拥有的那些特殊感官。","duration":"专注，至多一小时","higherLevels":null,"id":"Beast_Sense","level":2,"nameEn":"Beast Sense","nameZh":"野兽感官","range":"触碰","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","术士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"处于你施法范围内的一个你可见的生物必须进行一次体质豁免，豁免失败者在法术持续期间陷入目盲或耳聋状态（由你选择）。目标可以在其每个回合结束时重复此豁免，直至豁免成功时结束自己身上的效应。","duration":"1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，你就能多指定一个生物作为法术目标。"},"id":"BlindnessDeafness","level":2,"nameEn":"Blindness/Deafness","nameZh":"目盲术/耳聋术","range":"120尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"你的身体变得模糊不定，难以捉摸。在法术持续时间内，所有生物对你发动的攻击检定具有劣势。不过若攻击者能通过盲视或真实视觉观测你，则其免疫于此法术的效应。","duration":"专注，至多1分钟","higherLevels":null,"id":"Blur","level":2,"nameEn":"Blur","nameZh":"朦胧术","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，以该点为源点半径20尺球状区域内的每个类人生物必须成功通过一次魅力豁免，否则将受下列效应之一影响（由你分别为每名生物选择生效的效应）。\n直到法术结束，该生物免疫魅惑和恐慌状态。如果该生物已经陷入魅惑或恐慌状态，则这些状态在持续时间内被压制。 该生物对你选择的之前敌对的生物态度变为冷漠。该冷漠态度持续到目标受到伤害或者看到自己的盟友受到伤害。当法术结束时，该生物恢复到原本的态度。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Calm_Emotions","level":2,"nameEn":"Calm Emotions","nameZh":"安定心神","range":"60 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一小片玻璃","raw":"V、S、M（一小片玻璃）","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，在以该点为中心的5尺立方区域内咒唤出旋转的匕首。区域内的每名生物受到4d4点挥砍伤害。每当立方区域移动到一名生物区域内时、一名生物进入立方区域或是在该区域结束其回合时，该生物同样会受到此伤害。一名生物一回合中只会受到一次该伤害。\n在你后续的回合中，你能够以一个魔法动作将立方区域传送至多30尺。\n升环施法。 使用的法术位每比二环高一环，此法术的伤害就增加2d4。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Cloud_of_Daggers","level":2,"nameEn":"Cloud of Daggers","nameZh":"匕首之云","range":"60 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","法师","奇械师"],"components":{"material":true,"materials":"价值50+GP的红宝石尘，作为法术耗材","raw":"V、S、M（价值50+GP的红宝石尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你所触碰的物件上冒出火焰。这一效应发出半径20尺的明亮光照以及额外20尺的微光光照。法术效应看上去与一般火焰无异，不过其并不会发热，也不需要燃料。你可以掩盖或隐藏火焰，但无法将其闷熄或扑灭。","duration":"直至被解除","higherLevels":null,"id":"Continual_Flame","level":2,"nameEn":"Continual Flame","nameZh":"不灭明焰","range":"触碰","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["游侠"],"components":{"material":true,"materials":"一根装饰性穗带","raw":"V、S、M（一根装饰性穗带）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰至多四根非魔法箭矢或弩矢，将其插在位于你所处空间的地面上。直到法术结束为止，这些弹药不能被物理方法拔起，且当除你之外的生物第一次进入距弹药30尺内空间或在距弹药30尺内空间结束回合时，一枚弹药便会飞起攻击此生物。那名生物必须成功于一次敏捷豁免，否则受到2d4点穿刺伤害。那枚弹药随之被摧毁。当所有弹药都没有插在地面上时，法术终止。\n施展该法术时，你可以指定任意名你选择的生物，法术效应将无视他们。","duration":"8小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，可被影响的弹药数量就增加两枚。"},"id":"Cordon_of_Arrows","level":2,"nameEn":"Cordon of Arrows","nameZh":"警戒箭阵","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一名施法距离内你可见的生物必须成功于一次感知豁免，否则于法术持续时间内陷入魅惑状态。非类人生物自动成功于此豁免。\n一顶虚体王冠出现在被魅惑目标的头顶，且目标每回合必须在移动之前使用其动作对除自身以外你精神性选择的目标发动一次近战攻击。若你并未选择任何生物，或目标触及内没有生物，则目标可在其回合正常行动。目标在其每回合结束时都可以重新豁免，豁免成功则结束其身上该法术的效应。\n在施法后，你在每个自己回合里必须用一个魔法动作维持对目标的控制，否则法术将终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Crown_of_Madness","level":2,"nameEn":"Crown of Madness","nameZh":"疯狂冠冕","range":"120尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":true,"materials":"蝙蝠毛与一块煤","raw":"V、S、M（蝙蝠毛与一块煤）","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，并在法术持续时间内使魔法性黑暗充斥以该点为中心半径15尺的球状区域。黑暗视觉也无法看穿这种黑暗，非魔法的光照也无法将其照亮。\n或者，你可以将此法术施展于一个未被着装或携带的物件上，使黑暗充斥源自该物件的15尺光环区域。将该物件用不透明的东西遮掩（比如用碗或头盔盖住）时，会将黑暗隔绝。\n如果法术区域与任何二环或更低环阶法术创造的明亮光照或微光光照区域重叠，则这些造光的法术将被解除。","duration":"专注，至多10分钟","higherLevels":null,"id":"Darkness","level":2,"nameEn":"Darkness","nameZh":"黑暗术","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":true,"materials":"一根干胡萝卜","raw":"V、S、M（一根干胡萝卜）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名自愿生物，该生物在法术持续时间内拥有150尺黑暗视觉。","duration":"8小时","higherLevels":null,"id":"Darkvision","level":2,"nameEn":"Darkvision","nameZh":"黑暗视觉","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"1铜币","raw":"V、S、M（1铜币）","somatic":true,"verbal":true},"concentration":true,"description":"你激活下述效应之一。直到法术结束为止，你可以在你随后的回合用一个魔法动作以激活下述任意效应之一。\n感知思想Sense Thoughts。 你感知距你30尺内，知晓语言或能够心灵感应的思想的存在。你并不会阅读这些思想，但你知道这里存在一名有理智的生物。此法术会被1尺厚的岩石、泥土或木头，1寸厚的金属，或薄薄一层铅阻隔。 阅读思想Read Thoughts。选择一名距你30尺内的可见生物，或一名距你30尺内被感知思想侦测到的生物。你了解到此时目标最关心的事情。如果目标不知晓任何语言也不能够进行心灵感应，则你不能得到任何信息。在你的下一回合，用一个魔法动作，你可以尝试深入目标的心灵。如果你选择这么做，目标进行一次感知豁免。豁免失败，则你了解到他的逻辑推理、情绪状态以及他头脑中的一些大事（比如忧虑、挚爱和仇恨的事物）。豁免成功，法术终止。无论豁免是否成功，目标都会知道你正在窥探其心灵，且直到你的注意力从它的心灵上移开为止，目标均可以在其回合内使用动作进行一次智力（奥秘）检定，对抗你的法术豁免DC，目标胜出对抗时，法术终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Detect_Thoughts","level":2,"nameEn":"Detect Thoughts","nameZh":"侦测思想","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一根辣椒","raw":"V、S、M（一根辣椒）","somatic":true,"verbal":true},"concentration":true,"description":"你触摸一名自愿生物，然后从强酸、寒冷、火焰、闪电或毒素中任选其一。在法术结束之前，目标可以用一个魔法动作呼出15尺锥形范围的吐息。区域内的所有生物进行一次敏捷豁免，豁免失败受到3d6点所选类型的伤害，豁免成功只受一半伤害。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就提高1d6。"},"id":"Dragon's_Breath","level":2,"nameEn":"Dragon's Breath","nameZh":"龙息术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":true,"materials":"毛发或羽毛","raw":"V、S、M（毛发或羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一名生物并在力量、敏捷、智力、感知、魅力中选择一项属性。法术持续时间内，目标在使用所选属性进行的属性检定具有优势。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，你就可以额外指定一个目标。你可以分别为每个目标选择一项属性。"},"id":"Enhance_Ability","level":2,"nameEn":"Enhance Ability","nameZh":"强化属性","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","法师","奇械师"],"components":{"material":true,"materials":"一撮铁粉","raw":"V、S、M（一撮铁粉）","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，法术使施法距离内一个你可见的生物或物件的大小发生改变（见下可选效应）。若你以物件为目标，则其不能被着装或携带。如果目标为非自愿生物，则其可以进行一次体质豁免。豁免成功则法术无效。\n如果目标是生物，则其着装物和携带物的尺寸也随之变化。随后任何从该生物身上脱离的物品都会立即恢复为正常大小。投掷武器和弹药在命中目标或失手后会恢复为正常大小。\n变巨Enlarge。目标的体型增大一级（例如从中型变为大型）。目标在力量检定和力量豁免时具有优势。目标使用变巨的武器发动攻击或进行徒手打击时，命中时将额外造成1d4伤害。缩小Reduce。目标的体型缩小一级（例如从中型变为小型）。目标在力量检定和力量豁免时具有劣势。目标使用缩小的武器发动攻击或进行徒手打击时，命中时将额外减少1d4伤害（以此法无法将该伤害降至1以下）。","duration":"专注，至多1分钟","higherLevels":null,"id":"Enlarge_Reduce","level":2,"nameEn":"Enlarge/Reduce","nameZh":"变巨术/缩小术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你编排一段使人分心的话语，指定施法距离内任何你能看见的生物。目标生物必须进行一次感知豁免。如果你或你的同伴正在和目标生物战斗，则其自动成功于该豁免。豁免失败时，目标直到法术终止之前进行的感知（察觉）检定与被动察觉值具有-10减值。","duration":"专注，至多1分钟","higherLevels":null,"id":"Enthrall","level":2,"nameEn":"Enthrall","nameZh":"注目术","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你召唤某个异界存在作为忠诚坐骑，坐骑会出现在施法范围内你选择的未占据空间中。此生物使用异界坐骑Otherworldly Steed 的数据。如果你已经有一只以此法术获得的坐骑，则其会被新坐骑替代。\n坐骑看起来像一匹大型的可骑乘动物（由你选择），比如一匹马，一头骆驼，一只恐狼或一头赤鹿。你在施展此法术时从下述三种生物类型中选择坐骑的生物类型：天族、妖精、邪魔，其数据中的特定特质由坐骑的生物类型决定。\n异界坐骑Otherworldly Steed 大型天族、妖精或邪魔（由你选择），中立 AC 10+法术环阶 HP 5+每法术环阶10（坐骑具有等于法术环阶数量的生命骰[D10]） 速度 60尺，飞行60尺（需法术为四环及以上） 调整豁免调整豁免调整豁免 力量18+4+4 敏捷12+1+1 体质14+2+2 智力6-2-2 感知12+1+1 魅力8-1-1 感官 被动察觉11 语言 心灵感应1里（仅对你生效） CR 无（XP0；PB等于你的熟练加值） 特质Traits 生命连接Life Bond。 当你从一道一环或以上的法术中恢复生命值时，若你位于坐骑5尺内，则坐骑也会恢复相同数量的生命值。 动作Actions 异界猛击Otherworldly Slam。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+法术环阶点光耀（天族）、心灵（妖精）、暗蚀（邪魔）伤害。 附赠动作Bonus Actions 堕落凝视Fell Glare（仅限邪魔，长休充能）。 感知豁免：DC等同于你的法术豁免DC，一名距坐骑60尺内的可见生物。失败：目标直到你下个回合结束为止陷入恐慌状态。 妖精跨步Fey Step（仅限妖精，长休充能）。坐骑连同其骑手传送至你选择的距其60尺内未占空间中。 治愈之触Healing Touch（仅限天族，长休充能）。一名距坐骑5尺内的生物恢复2d8+法术环阶点生命值。\n战斗Combat。坐骑是你和你盟友的盟友。战斗时，它共用你的先攻，并在你骑乘它期间视同受控坐骑（如骑乘战斗规则中所定义）。如果你具有失能状态，则坐骑会在你的回合之后立刻进行自己的回合并独立行动，集中精力保护你。坐骑的消失Disappearance of the Steed。坐骑在其降至0生命值或你死亡时会消失。当它消失时，它会将自己穿着或携带的任何物品留下。如果你再次施展此法术，你决定是重新召唤消失的那头坐骑还是召唤一头不同的。升环施法。在生物数据中使用更高的法术环阶。","duration":"立即","higherLevels":null,"id":"Find_Steed","level":2,"nameEn":"Find Steed","nameZh":"寻获坐骑","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"该法术只单纯揭示陷阱的存在而不能得知陷阱的位置。不过你可以知晓所感测到陷阱其能够构成危害的大致形式。","duration":"立即","higherLevels":null,"id":"Find_Traps","level":2,"nameEn":"Find Traps","nameZh":"寻找陷阱","range":"120尺","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊","术士"],"components":{"material":true,"materials":"一片漆树叶","raw":"V、S、M（一片漆树叶）","somatic":true,"verbal":true},"concentration":true,"description":"你在一只空手上召出一把火焰刀。该刀刃的尺寸和形状近似于一把弯刀并在法术持续时间内持续存在。当你放下刀刃时其将消失不见，但你可以用一个附赠动作重新将其唤出。\n你可以用一个魔法动作使用该火焰刀发动一次近战法术攻击。若命中，则目标受到3d6+你的施法属性调整值点火焰伤害。\n火焰刀提供半径10尺的明亮光照以及额外10尺的微光光照。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d6。"},"id":"Flame_Blade","level":2,"nameEn":"Flame Blade","nameZh":"火焰刀","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一颗蜡球","raw":"V、S、M（一颗蜡球）","somatic":true,"verbal":true},"concentration":true,"description":"一颗直径5尺的火焰球显现在施法距离内地面上的一处未占据空间，并在法术持续时间内持续存在。任何生物在火球周围5尺内结束其回合时必须进行一次敏捷豁免。豁免失败者将受到2d6点火焰伤害，豁免成功则伤害减半。\n你可以用一个附赠动作将火球沿着地面移动30尺。如果你将火球移入某名生物所占据的空间，则该生物必须进行对抗火球伤害的豁免，而火球在该回合内停止移动。\n移动火球时，你可以指引它越过不高于5尺的障碍，或者越过不宽过10尺的陷坑。被火球触碰的任何未被着装或携带的可燃物件都会开始燃烧。火球向其周围散发出半径20尺的明亮光照以及额外20尺的微光光照。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，其伤害就增加1d6。"},"id":"Flaming_Sphere","level":2,"nameEn":"Flaming Sphere","nameZh":"炽焰法球","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","圣武士","法师"],"components":{"material":true,"materials":"2枚铜币，作为此法术的耗材","raw":"V、S、M（2枚铜币，作为此法术的耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一具尸体或其他遗骸。目标在法术持续时间内不会腐烂且无法被转变为亡灵Undead。该法术同样可以有效的延长复活目标的时间限制，因为受该法术影响下度过的时间不计入法术如死者复活Raise Dead 的时间限制内。","duration":"10日","higherLevels":null,"id":"Gentle_Repose","level":2,"nameEn":"Gentle Repose","nameZh":"遗体防腐","range":"触碰","ritual":true,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","术士","法师"],"components":{"material":true,"materials":"一颗豆类种子","raw":"V、S、M（一颗豆类种子）","somatic":true,"verbal":true},"concentration":true,"description":"一股长60尺，宽10尺的线状强风以你为起点向你指定的方向吹去。每名位于线状区域内的生物必须成功于一次力量豁免，豁免失败则沿着线状的方向被推离你15尺。在线状区域内结束其回合的生物也必须进行同样的豁免。\n任何生物在线状区域内朝更靠近你的方向移动时，其每移动1尺必须花费2尺的移动力。\n强风吹散区域内的毒气或蒸汽，并吹熄蜡烛等不受保护的其他类似火焰。而有保护的火焰（比如提灯）则会剧烈摇晃并有50%的概率被吹熄。\n你可以在自己随后的回合内用一个附赠动作改变线状风道的方向。","duration":"专注，至多1分钟","higherLevels":null,"id":"Gust_of_Wind","level":2,"nameEn":"Gust of Wind","nameZh":"造风术","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","奇械师"],"components":{"material":true,"materials":"一片铁片和一团火焰","raw":"V、S、M（一片铁片和一团火焰）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内一件你能看见的人造金属物件（例如一把金属武器，或者一套金属质的重甲或中甲），并使该物件变得炽热。施展该法术时，任何与该物件有物理接触的生物均受到2d8点火焰伤害。直到法术终止前，只要这个物件依然在施法距离内，你都可以在你随后的每个回合以一个附赠动作来再次造成此伤害。\n若握持或着装该物件的生物因此受到伤害，则该生物必须通过一次体质豁免，否则如果这个生物只要能丢下该物件，该生物就必须丢下该物件。如果该物件没有被丢下，则直至你的下一回合开始为止，该生物进行攻击检定和属性检定时具有劣势。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d8。"},"id":"Heat_Metal","level":2,"nameEn":"Heat Metal","nameZh":"灼热金属","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","术士","魔契师","法师"],"components":{"material":true,"materials":"一片直的小铁片","raw":"V、S、M（一片直的小铁片）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内一个你能看见的类人生物。该目标必须进行一次感知豁免，豁免失败则其在法术持续时间内陷入麻痹状态。目标在其每回合结束时可以重新进行这次豁免，豁免成功则终止其身上该法术的效应。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用三环或更高法术位施展该法术时，你使用的法术位每比二环高一环，就可以额外指定一个类人作为目标。"},"id":"Hold_Person","level":2,"nameEn":"Hold Person","nameZh":"定身类人","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师","奇械师"],"components":{"material":true,"materials":"一根包裹在阿拉伯胶中的睫毛","raw":"V、S、M（一根包裹在阿拉伯胶中的睫毛）","somatic":true,"verbal":true},"concentration":true,"description":"你触碰的一个生物进入隐形状态并维持至法术终止。如果目标进行攻击检定、造成伤害或施展法术，则此法术提前终止。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用三环或更高法术位施展该法术时，你使用的法术位每比二环高一环，就可以额外指定一个生物作为目标。"},"id":"Invisibility","level":2,"nameEn":"Invisibility","nameZh":"隐形术","range":"触碰","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"指定施法距离内一个你能看见的物件。该物件可以是一扇门，一个盒子，一个箱子，一副镣铐，一把挂锁，或是一个其他的通过魔法或普通手段来防止被打开的物件。\n被一把普通锁锁住的目标其锁会被解开，被卡死的目标会被松开，被闩住的目标会被打开。如果目标被多把锁锁住，则只有一把锁会被打开。\n施展该法术时，受术目标会发出一声响亮的敲击声，其声响最远 300 尺内都能听见。","duration":"立即","higherLevels":null,"id":"Knock","level":2,"nameEn":"Knock","nameZh":"敲击术","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个生物，并终止正影响它的一种状态：目盲，耳聋，麻痹或中毒 。","duration":"立即","higherLevels":null,"id":"Lesser_Restoration","level":2,"nameEn":"Lesser Restoration","nameZh":"次等复原术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一个金属弹簧","raw":"V、S、M（一个金属弹簧）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内你能看见的一个生物或未固定的物件，使其垂直上升至多 20 尺，并在该处维持悬浮直至持续时间结束。该法术可悬浮一个重量至多 500 磅的目标。一个非自愿的生物可以对法术进行一次体质豁免，若成功将避免受其影响。\n目标只能通过推或拉一个固定的物件或平面（例如一面墙或者天花板）来进行移动，这种移动方式视为等同于攀爬。你可以在自己回合里将目标的悬浮高度向上或向下改变至多 20 尺：如果你自身就是该法术的目标，则你可以进行上升和下降并将其作为你移动的一部分；如果你不是该法术的目标，则你可以使用魔法动作来移动目标，但目标必须始终处于你的施法距离内。\n法术终止时，仍处于空中的目标会缓缓飘落到地面。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Levitate","level":2,"nameEn":"Levitate","nameZh":"浮空术","range":"60 尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","德鲁伊","游侠"],"components":{"material":true,"materials":"一块寻血猎犬的皮毛","raw":"V、S、M（一块寻血猎犬的皮毛）","somatic":true,"verbal":true},"concentration":false,"description":"你点名或描述一种特定的野兽生物、植物 生物或非魔法植物。如果5里内存在该类生物或植物，你将知晓其中最近的个体与你的相对方位和距离。","duration":"立即","higherLevels":null,"id":"Locate_Animals_or_Plants","level":2,"nameEn":"Locate Animals or Plants","nameZh":"动植物定位术","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","法师"],"components":{"material":true,"materials":"一根分叉的树枝","raw":"V、S、M（一根分叉的树枝）","somatic":true,"verbal":true},"concentration":true,"description":"你点名或描述一个你熟悉的物件。只要该物件与你相距不超过1000尺，你就会感测到该物件的方位。如果该物件正在移动，则你也将知晓其移动的方向。\n该法术可定位一个你认识的特定物件，不过你需要曾经在30尺内近距离看到过该物件至少一次；或者它也可定位特定的一类物件（如某种服装、珠宝、家具、工具或武器）中距你最近个体。如果有任意厚度的铅，即使只是薄薄一片铅片阻挡了你与被定位物件间的通路，则该物件也无法被该法术所定位。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Locate_Object","level":2,"nameEn":"Locate Object","nameZh":"物件定位术","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["吟游诗人","法师","奇械师"],"components":{"material":true,"materials":"价值10GP+的玉粉，作为法术耗材","raw":"V、S、M（价值10GP+的玉粉，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你将一段信息植入施法距离内的一个物件中，其信息会在满足预设事件时说出。指定一个你能看见且未被另一生物穿着或携带的物件。然后，你可以使用至多10分钟来传达这段不超过25个字的信息。最后再来设定触发法术传达信息的事件。预设的事件发生时，目标物件上出现一张魔法嘴，并用与你相同的声音和音量复述所存储的信息。如果你指定的目标本身有一张嘴或者类似嘴的结构（例如雕像的嘴），则魔法嘴将生成在该嘴结构的位置，使其看起来如同是物件的嘴在说话一样。施展该法术时，你可以让法术在传达过信息后随即终止，或者也可以让法术一直持续并在每次被预设条件触发时进行复述。你所决定的触发条件可以很概括也可以很具体，不过你只能根据目标物件30尺内的视觉或听觉状况来设定条件。例如，你可以命令魔嘴在任何生物移动至物件30尺内时说出信息，或者当其30尺内有银铃响起时说出信息。","duration":"直到被解除","higherLevels":null,"id":"Magic_Mouth","level":2,"nameEn":"Magic Mouth","nameZh":"魔嘴术","range":"30尺","ritual":true,"school":"幻术","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["圣武士","游侠","术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一件非魔法武器。直到法术结束前，它成为魔法武器且在进行攻击检定和伤害掷骰时具有+1 加值。你再次施展该法术时，先前的效应提前结束。","duration":"1小时","higherLevels":{"kind":"升环施法","text":"使用三至五环的法术位时，此法术的加值增加至+2；使用高于五环的法术位时，此法术的加值增加至+3。"},"id":"Magic_Weapon","level":2,"nameEn":"Magic Weapon","nameZh":"魔化武器","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"大黄粉","raw":"V、S、M（大黄粉）","somatic":true,"verbal":true},"concentration":false,"description":"一支闪烁的绿色箭矢朝一个施法距离内的目标疾速飞去，并炸裂成一滩强酸。对目标进行一次远程法术攻击。若命中，则目标受到4d4点强酸伤害，然后再其下一回合结束时再受到2d4点强酸伤害。若未命中，则箭矢的酸液溅射目标，造成初始伤害一半的伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术伤害（包括初始和后续）增加1d4。"},"id":"Melf's_Acid_Arrow","level":2,"nameEn":"Melf's Acid Arrow","nameZh":"马友夫强酸箭","range":"90尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":true,"description":"指定施法距离内一个可见生物，你驱动一道心灵能量的锥刺侵入目标的心智。目标必须进行一次感知豁免检定，失败则会受到3d8点心灵伤害，成功则只受一半伤害。在目标豁免失败时，你在法术结束之前能时刻得知目标所在的位置，只要你们还处于同一个存在位面上。当你拥有目标的位置信息时，目标将不能对你躲藏，并且如果它隐形了，在对抗你时它不能从这个状态中受益。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d8。"},"id":"Mind_Spike","level":2,"nameEn":"Mind Spike","nameZh":"心灵尖刺","range":"120尺","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"三个你自身的幻象分身出现在你所处的空间中。直到法术终止前，分身都会随你移动，并模仿你的动作和位置变换，使人无法追踪判断哪一个是你的真身。\n在法术持续时间内，每当一个生物攻击命中你时，为每个剩余分身投掷一个d6，只要有任一d6骰出3或以上，一个分身代你承受本次命中并随之被摧毁。分身无视所有其他的伤害和效应。三个分身都被摧毁时，法术随之结束。\n如果一名生物处于目盲状态，或拥有盲视，或拥有真实视觉，则该法术无法影响该生物。","duration":"1分钟","higherLevels":null,"id":"Mirror_Image","level":2,"nameEn":"Mirror Image","nameZh":"镜影术","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你短暂地被银白的雾气所笼罩，传送到至多30尺内一个你能看见且未占据空间。","duration":"立即","higherLevels":null,"id":"Misty_Step","level":2,"nameEn":"Misty Step","nameZh":"迷踪步","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"verbal":true,"somatic":true,"material":true,"materials":"一片月籽藤叶","raw":"V、S、M（一片月籽藤叶）"},"concentration":true,"description":"指定施法距离内一点，一束淡淡的银光照耀在以该点为中心半径5尺、高40尺的柱状区域内。直至法术终止前，柱状区域内处于微光光照。在施展该法术的后续回合内，你能够以一个魔法动作将柱状区域移动至多60尺。柱状区域出现时，每个区域内的生物进行一次体质豁免检定，豁免失败则受到2d10的光耀伤害，且若该生物已变形（例如受法术变形术Polymorph影响），其变回真实形态，且无法在离开柱状区域前变形。豁免成功则仅承受前述伤害的一半。在法术区域进入生物空间、生物进入法术区域或在其内结束回合时，目标生物也需要进行该体质豁免检定。一名生物每回合仅需进行一次该豁免检定。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d10。"},"id":"Moonbeam","level":2,"nameEn":"Moonbeam","nameZh":"月华之光","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一小片方形丝绸","raw":"V、S、M（一小片方形丝绸）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名自愿生物或者一个未被着装或携带的物件以在其上设置一道幻术。生物获得下述伪装效应，物件则获得下述虚假灵光效应。效应持续至法术结束。如果你持续30日每日均对同一个目标施展此法术，则幻术的持续时间变为直至被解除。\n伪装Mask（生物）。选择一种目标实际生物类型以外的生物类别。法术和其他魔法效应会将目标生物视为属于该生物类型来处理效果。 虚假灵光False Aura（物件）。你改变物件在能够侦测魔法灵光的侦测法术和魔法效应（例如侦测魔法Detect Magic）中呈现的样子。你可以使一个非魔法物件如同具有魔法性、让一个魔法物件如同只是非魔法的，或者改变物件的魔法灵光学派，使其呈现出由你选择的特定魔法学派的灵光。","duration":"24小时","higherLevels":null,"id":"Nystul's_Magic_Aura","level":2,"nameEn":"Nystul's Magic Aura","nameZh":"涅斯图魔法灵光","range":"触碰","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"槲寄生烧成的灰烬","raw":"V、S、M（槲寄生烧成的灰烬）","somatic":true,"verbal":true},"concentration":true,"description":"你在法术持续时间于30尺光环范围内散发出遮蔽灵光。位于灵光范围期间，你和每名你选择的生物在敏捷（隐匿）检定上获得+10加值，且不会留下任何踪迹。","duration":"专注，至多1小时","higherLevels":null,"id":"Pass_without_Trace","level":2,"nameEn":"Pass without Trace","nameZh":"行动无踪","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一点羊毛","raw":"V、S、M（一点羊毛）","somatic":true,"verbal":true},"concentration":true,"description":"你试图向施法距离内你可见的一名生物脑内植入一段幻术。目标进行一次智力豁免。豁免失败时，你创造出一个不大于10尺立方且只能被目标感知到的魅影物件，生物或其他你指定的现象。魅影将持续至法术终止。该魅影包括声音、温度和其他感官因素。目标可以用研究动作进行一次对抗你法术豁免DC的智力（调查）检定来仔细研究这个魅影。检定成功则目标意识到魅影是一道幻术，法术终止。目标受法术影响期间会认定魅影是真实的，并且会合理化任何与其互动产生的不合逻辑的结果。例如，若目标试图走过一座跨越峡谷的魅影桥时从桥上坠落并存活，它仍然会相信该桥是真实存在的，并且会觉得是其他什么东西导致了自己的坠落。若魅影代表着一名危险生物或一处灾害，则受术目标甚至还会受到幻术的直接伤害。在每个你的回合中，若目标在魅影区域内或距其5尺范围内，则上述形态的魅影可以对目标造成2d8点心灵伤害。而此时目标则会感觉该伤害类型与魅影适于造成的一种伤害类型相符。","duration":"专注，至多1分钟","higherLevels":null,"id":"Phantasmal_Force","level":2,"nameEn":"Phantasmal Force","nameZh":"魅影之力","range":"60尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"在施展法术期间一直位于施法距离内的至多五名生物获得等同于一次短休的增益，并且恢复2d8点生命值。一名生物直到完成一次长休为止不能再次被此法术影响。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的治疗量就增加1d8。"},"id":"Prayer_of_Healing","level":2,"nameEn":"Prayer of Healing","nameZh":"治疗祷言","range":"30尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名生物并结束其陷入的中毒状态。在持续时间内，目标为避免陷入或结束中毒状态所做的豁免具有优势，且具有毒素伤害的抗性。","duration":"1小时","higherLevels":null,"id":"Protection_from_Poison","level":2,"nameEn":"Protection from Poison","nameZh":"防护毒素","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你向施法距离内的一名生物射出一道让人衰弱的能量射线。目标必须进行一次体质豁免。豁免成功，则目标直到你的下个回合开始在下一次攻击掷骰上具有劣势。豁免失败，目标在持续时间内在使用力量属性的D20检定上具有劣势。同样的，在此期间，其所有的伤害掷骰获得1d8的减值。目标在每个其回合结束时可以重复豁免，豁免成功则法术终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Ray_of_Enfeeblement","level":2,"nameEn":"Ray of Enfeeblement","nameZh":"衰弱射线","range":"60尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一段绳子","raw":"V、S、M（一段绳子）","somatic":true,"verbal":true},"concentration":false,"description":"你接触一段绳子。绳的一端会向上升起，直到整条绳索都垂直于地面挂在空中或绳子触及天花板。绳子向上的末端存在一个隐形的3尺×5尺大小的传送门，其通往一个法术持续时间内一直存在的异次元空间。沿着绳子向上攀爬即可进入此空间，绳子也可被拽入空间中或从空间中丢出。空间可容纳至多八名体型不超过中型的生物。攻击，法术和其他效应均无法穿过空间而出入，但空间内的生物可以通过入口看到外面的景象。法术终止时，异次元空间内的一切东西都会掉出来。","duration":"1小时","higherLevels":null,"id":"Rope_Trick","level":2,"nameEn":"Rope Trick","nameZh":"魔绳术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你射出三道火焰的射线。你可以将其射向施法距离内的一个或多个目标。每道射线需要你分别进行一次远程法术攻击。若命中，则目标受到2d6点火焰伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，你就能多创造出一道射线。"},"id":"Scorching_Ray","level":2,"nameEn":"Scorching Ray","nameZh":"灼热射线","range":"120 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师","奇械师"],"components":{"material":true,"materials":"一撮滑石粉","raw":"V、S、M（一撮滑石粉）","somatic":true,"verbal":true},"concentration":false,"description":"在法术持续时间内，你能看见任何处于隐形状态的生物和物件，如同其处于正常可见状态一样。你还能够看见以太位面，以太位面的生物和物件在你眼中会以幽灵般的半透明形状显现。","duration":"1 小时","higherLevels":null,"id":"See_Invisibility","level":2,"nameEn":"See Invisibility","nameZh":"识破隐形","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一片云母","raw":"V、S、M（一片云母）","somatic":true,"verbal":true},"concentration":false,"description":"一阵震耳欲聋的噪音在你指定的施法距离内一点上爆发出来。以该点为中心半径10尺球状区域内的所有生物必须要进行一次体质豁免。豁免失败将受到3d8点雷鸣伤害；豁免成功受到半数伤害。构装生物进行该豁免时具有劣势。如果法术的范围内存在不被任何生物着装携带的非魔法物件，则它也要受到该伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d8。"},"id":"Shatter","level":2,"nameEn":"Shatter","nameZh":"粉碎音波","range":"60 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到2d6点光耀伤害。目标会发出半径5尺的明亮光照直至法术结束。在此期间，对其进行的攻击检定具有优势，且其无法受益于隐形状态。\n升环施法。 使用的法术位每比二环高一环，此法术的额外伤害就增加1d6。\n（注：本法术在PHB2014中原名印记斩Branding Smite）","duration":"专注，至多1分钟","higherLevels":null,"id":"Shining_Smite","level":2,"nameEn":"Shining Smite","nameZh":"闪耀斩","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","牧师","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，以该点为中心半径20尺的球状区域在法术持续时间内将无法产生任何声音，且外界的声音也无法于该区域内传播。任何完全位于该区域内的生物和物件都将免疫雷鸣伤害，而完全位于该区域内的任何生物都将陷入耳聋状态。此外，该区域内无法施展包含言语成分的法术。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Silence","level":2,"nameEn":"Silence","nameZh":"沉默术","range":"120 尺","ritual":true,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师","奇械师"],"components":{"material":true,"materials":"一滴沥青和一只蜘蛛","raw":"V、S、M（一滴沥青和一只蜘蛛）","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一个自愿的生物，并使其在法术终止前能够在垂直表面上下或横向移动，其甚至可以在天花板上倒挂着移动而不需要用到双手。另外，目标获得等同于其速度的攀爬速度。","duration":"专注，至多 1 小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比2环高一环，你便能额外指定一个生物作为法术的目标。"},"id":"Spider_Climb","level":2,"nameEn":"Spider Climb","nameZh":"蛛行术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"七根棘刺","raw":"V、S、M（七根棘刺）","somatic":true,"verbal":true},"concentration":true,"description":"以施法距离内一点为中心半径20尺的球状区域的地面扭曲变形，大片坚硬的棘刺破土而出。该区域在法术持续时间内视为困难地形。而生物进入该区域或在其中移动时，其每移动5尺就要受到2d4穿刺伤害。法术导致的地面变形经过伪装，使其看起来并无异样。如果生物在你施展此法术时看不见这片区域，则它只有在执行一次搜索动作并成功进行一次感知（察觉或求生）检定后，才能在进入之前发现该区域隐藏的危险。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Spike_Growth","level":2,"nameEn":"Spike Growth","nameZh":"荆棘丛生","range":"150尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你创造出一块形似你选择的武器的浮空灵体力场，并使其持续到法术持续时间结束。它出现在施法距离内你选择的一点，并且你可以立即对该武器周围5尺内的一个生物发动一次近战法术攻击。若命中，则目标受到 1d8+你的施法属性调整值 点力场伤害。在你之后的回合内，你可以用附赠动作让该武器移动至多20尺，并再对它周围5尺内的一个生物发动一次同样的攻击。","duration":"专注，至多1 分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比二环高一环，此法术的伤害就增加1d8。"},"id":"Spiritual_Weapon","level":2,"nameEn":"Spiritual Weapon","nameZh":"灵体武器","range":"60 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一滴蜂蜜","raw":"V、M（一滴蜂蜜）","somatic":false,"verbal":true},"concentration":true,"description":"你以魔法影响施法距离内一个你能看见的生物，并对其施以某种行动暗示（不超过25个词）。由你指定的受术目标必须能听到并理解你的话语。暗示必须听起来可行，也不涉及明显会对目标及其盟友造成伤害的内容。比如说，你可以说“把邪教的宝库钥匙找来，然后给我。”或者：“别打了，让图书馆保持安静，然后出去别回来。”\n目标必须成功通过一次感知豁免，否则在法术持续时间内陷入魅惑，若你或你的盟友对其造成伤害此法术将提前结束。被魅惑的生物会尽其所能地执行你所描述的行为。你所暗示的行为可能会在法术持续时间内始终一直进行，而如果你所暗示的活动可以用更短的时间完成，则此法术会在目标完成了你的要求后随即终止。","duration":"专注，至多 8 小时","higherLevels":null,"id":"Suggestion","level":2,"nameEn":"Suggestion","nameZh":"暗示术","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"一根羽毛、一簇毛皮和一条装在镀金橡果内的鱼尾、价值至少200GP","raw":"V, S, M（一根羽毛、一簇毛皮和一条装在镀金橡果内的鱼尾、价值至少200GP）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个野兽灵魄。其使用下文野兽灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从天空、大地和海洋中选择一个环境。该生物会显化符合为你所选的环境的形态，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n野兽灵魄Bestial Spirit 小型野兽，中立 AC 11+法术环阶 HP 20（仅天空）或30（仅大地与海洋）+每比二环高一法术环阶5 速度 30尺；攀爬30尺（仅大地）；飞行60尺（仅天空）；游泳30尺（仅海洋） 调整豁免调整豁免调整豁免 力量18+4+4 敏捷11+0+0 体质16+3+3 智力4-3-3 感知14+2+2 魅力5-3-3 感官 黑暗视觉60尺，被动察觉12 语言 理解你的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 飞掠Flyby（仅天空）。灵魄飞行离开敌人的触及范围时不会引发借机攻击。 集群战术Pack Tactics（仅大地与海洋）。若灵魄的攻击目标生物5尺内存在有至少一名灵魄未失能的盟友，则灵魄对该生物进行的攻击检定具有优势。 水下呼吸Water Breathing（仅海洋）。灵魄只能在水下呼吸。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的撕裂攻击（向下取整）。 撕裂Rend。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+4+法术环阶的挥砍伤害。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Beast","level":2,"nameEn":"Summon Beast","nameZh":"野兽召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":true,"materials":"一对铂金戒指（每个价值50GP+","raw":"V、S、M（一对铂金戒指（每个价值50GP+），你和目标在法术持续时间内需保持佩戴它们）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰另一个自愿的生物，在法术终止前在你和目标之间建立一道神秘的连接。目标位于你身边60尺内时，其AC和豁免检定具有+1加值，且对所有伤害具有抗性。此外，每当目标受到伤害时，你也会受到同样的伤害。\n如果你的生命值降至0，或你与目标距离超过60尺，则该法术终止。如果再有守护之链被施展于两个已被连接生物中的任意一方时，原有的法术将立刻终止。","duration":"1小时","higherLevels":null,"id":"Warding_Bond","level":2,"nameEn":"Warding Bond","nameZh":"守护之链","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"少量蜘蛛网","raw":"V、S、M（少量蜘蛛网）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内指定一点召唤出一大片黏黏的网状物。蛛网覆盖以该点为源点的 20 尺立方区域，并在法术持续时间内维持存在。蛛网范围内视为困难地形，并造成轻度遮蔽 。\n如果蛛网没有被固定在两个固体中间（例如墙和树）或跨在一片地板、墙壁、天花板中间，则蛛网会自动坍塌，而导致法术在你的下一回合开始时终止。摊在平面上的蛛网深度为 5 尺。\n在一个回合中首次进入蛛网，或任何在蛛网中开始其回合的生物必须进行一次敏捷豁免，否则陷入束缚状态，直至其离开蛛网或挣脱束缚。\n一名因蛛网陷入束缚状态的生物可以用一个动作进行一次对抗你的法术豁免DC的力量（运动）检定。如果成功，则其不再被束缚。\n蛛网是可燃的。任何5尺立方区域的蛛网在遇到火焰后会在一轮内燃烧殆尽，并对火焰中开始其回合的生物造成2d4点火焰伤害。","duration":"专注，至多1小时","higherLevels":null,"id":"Web","level":2,"nameEn":"Web","nameZh":"蛛网术","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你创造一个抵御谎言的魔法区域，该区域以施法距离内一点为中心，覆盖以该点为中心15尺半径的球状区域。在法术终止前，生物在一回合中首次进入该区域，或在该区域内开始其回合时，必须进行一次魅力豁免。豁免失败者在该区域内不能故意说谎。而你可以知晓每个生物进行的此豁免成功与否。\n受影响的生物可以意识到该效果的存在，因此它可以主动回避回答那些通常会以谎言答复的问题。该生物在回答问题时可以闪烁其词、避重就轻，但说的仍然需要是真话。","duration":"10分钟","higherLevels":null,"id":"Zone_of_Truth","level":2,"nameEn":"Zone of Truth","nameZh":"诚实之域","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"1 分钟","classes":["牧师","法师"],"components":{"material":true,"materials":"一滴血、一块肉、以及一点骨灰","raw":"V、S、M（一滴血、一块肉、以及一点骨灰）","somatic":true,"verbal":true},"concentration":false,"description":"在施法距离内指定一具中型或小型类人遗骨或遗体。目标将变为一名亡灵生物：遗骨变为骷髅Skeleton，遗体则变为丧尸Zombie。（这些生物的资料卡见附录B）。\n在你的每个回合内，你可以使用一个附赠动作并以精神命令操纵距离你 60 尺内，任何你用此法术制造的生物（如果你操纵多个生物，则你的命令可以同时传达给它们全部或是其中的某几个，不过每次只能为它们下达同一命令）。你决定被操纵生物下回合执行的动作和如何移动。或者，你也可以选择下达一条宽泛的命令（比如守护某个房间或走廊）。如果你没有下达命令，该生物将执行回避动作且只会为躲避危险而移动。一旦被下达命令，该生物会持续执行命令直到任务完成。\n这些受操纵生物只会在 24小时内服从你的命令，在之后，它们会停止遵守你下达的命令。若你想将对这些生物的控制时间再延长24小时，则你必须在当前24小时的时间段终止前再次对这些生物施展该法术。法术的此种用法只能延长你对至多四个你使用此法术所创造生物的控制时间，而不会创造新的生物。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，你就能多唤起两只亡灵生物，或是多延长对两只亡灵生物的控制。你无法用同一具骸骨或遗体唤起多个亡灵生物。"},"id":"Animate_Dead","level":3,"nameEn":"Animate Dead","nameZh":"活化死尸","range":"10 尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"一道灵光自你身上发出并形成30尺半径的光环 。当你创造灵光时和它持续时你的每个回合开始，你可以为区域内的一名生物恢复2d6生命值。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Aura_of_Vitality","level":3,"nameEn":"Aura of Vitality","nameZh":"活力灵光","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"在施法距离内指定任意数量的生物，并使其在法术持续时间内进行的感知豁免和死亡豁免具有优势。此外，其获得的所有治疗的生命值恢复量都取最大值。","duration":"专注，至多一分钟","higherLevels":null,"id":"Beacon_of_Hope","level":3,"nameEn":"Beacon of Hope","nameZh":"希望信标","range":"30尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一名生物。该生物必须进行一次感知豁免并成功通过，否则将在法术持续时间内被诅咒。直到该诅咒终止前，目标会遭受以下一项效应，由你选择：\n选择一项属性。目标使用该属性所进行的属性检定和豁免检定具有劣势。 目标对你发动的攻击检定具有劣势。 在战斗中，目标在其每回合开始时必须进行一次感知豁免，豁免失败则在该回合中被迫执行回避动作。 若你的攻击检定或法术对目标造成了伤害，则目标还会额外受到1d8暗蚀伤害。\n升环施法。使用四环法术位施展此法术时，你可以维持此法术的专注至多10分钟。使用五环及更高环阶的法术位施展此法术时，此法术无需专注，并且持续时间变为8小时（五或六环法术位）或24小时（七或八环法术位）。若你使用九环法术位施展此法术，则此法术会一直持续到被解除为止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Bestow_Curse","level":3,"nameEn":"Bestow Curse","nameZh":"降咒","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到3d8点光耀伤害，并且目标陷入目盲状态直至法术结束。陷入目盲的目标在其每回合结束时可以进行一次体质豁免，豁免成功则终止其身上的法术。","duration":"1分钟","higherLevels":{"kind":"升环施法","text":"你使用的法术位每比三环高一环，此法术的额外伤害提升1d8。"},"id":"Blinding_Smite","level":3,"nameEn":"Blinding Smite","nameZh":"致盲斩","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你在法术持续时间内每次自己回合结束时掷一次d6。结果为4~6时，你从你现在身处的存在位面消失，并出现在以太位面Ethereal Plane （若你本已身处以太位面，此法术会立即终止）。在你身处以太位面期间，你可以观测到你所离开位面的黑白影像，但只限于60尺之内。你只能影响其他身处以太位面的生物，或被其影响。并且处于其他位面的生物在没有能够观测到以太位面事物的特殊能力的情况下，同样无法观测到你。\n你会在你的下一回合开始时返回其他位面；如果当你法术终止时身处以太位面，你同样会返回其他位面。你返回原先位面时会出现在一个你原先位置10尺之内你可见的未占据空间之中。若在此范围内没有未占据空间，则你会出现在最近的未占据空间之中","duration":"1分钟","higherLevels":null,"id":"Blink","level":3,"nameEn":"Blink","nameZh":"闪现术","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一朵风暴云在施法距离内你上方可见的一点出现。风暴云表现为高10尺、半径60尺的柱状形状。\n当你施展这道法术时，选择风暴云下方你可见的一点。一束闪电从云端射向该点。位于该点5尺内的生物进行一次敏捷豁免。豁免失败者受到3d10闪电伤害，豁免成功则仅受半数伤害。\n直至法术结束前，你都可以执行一个魔法动作以此法再次降下闪电，并指定闪电射向同一点或另选一点。\n若施法时你身处暴风雨环境下的室外，则该法术令你得以控制空中的风暴而非创造一朵新的风暴云。在这种状况下，法术伤害增加1d10。","duration":"专注，至多 10 分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就增加 1d10。"},"id":"Call_Lightning","level":3,"nameEn":"Call Lightning","nameZh":"召雷术","range":"120 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"10 分钟","classes":["吟游诗人","牧师","术士","法师"],"components":{"material":true,"materials":"一件价值100GP+的法器：选择聆听则为一个以珠宝装饰的号角，选择观察则为一颗玻璃眼珠","raw":"V、S、M（一件价值100GP+的法器：选择聆听则为一个以珠宝装饰的号角，选择观察则为一颗玻璃眼珠）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内某处创造一个隐形的传感器，该处可以是你熟悉的地点（你曾到访过或看见过的地方），也可以是你不熟悉的显眼处（比如一扇门后，拐角位置或树林里）。这一无形体且不受伤害的传感器会在法术持续期间停留在该地。\n施展该法术时，你可以选择进行观察或是聆听。你可以通过传感器以所选的感官方式感测，如同你处在传感器所在的空间。你能够以一个附赠动作在观察和聆听之间切换。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Clairvoyance","level":3,"nameEn":"Clairvoyance","nameZh":"鹰眼术","range":"1 里","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你将显现为幽灵般虚幻的大型兽群的自然精魂咒唤在施法距离内一处你可见的未占据空间中。兽群在持续时间内一直存在，并且你可以选择动物精魂的形态——例如狼群、蛇群或是鸟群。\n在你位于兽群5尺内期间，你的力量豁免检定具有优势。当你在你的回合移动时，你可以令兽群也移动至多30尺到一处你可见的未占据空间中。\n每当兽群在移动中进入了一名你可见的生物10尺内时、一名你可见的生物进入位于兽群10尺内的空间或是在该空间结束其回合时，你都可以迫使该生物进行一次敏捷豁免检定。失败则该生物受到3d10挥砍伤害。一名生物一回合只需要进行一次该豁免。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就增加1d10。"},"id":"Conjure_Animals","level":3,"nameEn":"Conjure Animals","nameZh":"咒唤兽群","range":"60 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["游侠"],"components":{"material":true,"materials":"一把价值1+CP的近战或远程武器","raw":"V、S、M（一把价值1+CP的近战或远程武器）","somatic":true,"verbal":true},"concentration":false,"description":"你挥舞作为施法材料的武器，令无数外形相似的灵体武器（或是适合这把武器的弹药）显现，它们将向前射出并在之后消失。每名由你选择且你可见的位于60尺锥形区域内的生物进行一次敏捷豁免检定，豁免失败者将受到5d8点力场伤害，豁免成功则只受一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就增加1d8。"},"id":"Conjure_Barrage","level":3,"nameEn":"Conjure Barrage","nameZh":"箭如雨下","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"反应，当你看见60尺内一名生物施展一道具有言语、姿势或材料成分的法术时可用","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":false,"description":"你试图打断一名正在施法的生物。该生物进行一次体质豁免。豁免失败则法术消散且毫无效果，并且用于施展法术的动作、附赠动作或反应随之浪费。如果那道法术是使用法术位施展的，则法术位并不会被消耗。","duration":"立即","higherLevels":null,"id":"Counterspell","level":3,"nameEn":"Counterspell","nameZh":"法术反制","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内的地面上或容器中创造45磅食物和30加仑淡水，该法术创造的食物和水均可用于避免饥饿和脱水 的危害。食物味道寡淡却营养丰富，并且看起来像一种你选择的食物，水也是干净的。食物24小时内未被食用即会变坏。","duration":"立即","higherLevels":null,"id":"Create_Food_and_Water","level":3,"nameEn":"Create Food and Water","nameZh":"造粮术","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"你在30尺光环区域内散发出魔法灵光。位于灵光范围期间，你和你盟友以一把武器或一次徒手打击命中时将额外造成1d4光耀伤害。","duration":"专注，至多1分钟","higherLevels":null,"id":"Crusader's_Mantle","level":3,"nameEn":"Crusader's Mantle","nameZh":"十字军披风","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","圣武士","游侠","术士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"法术持续时间内，日光从施法距离内一点发散而出，充斥一个60尺半径的球状区域。日光区域视为明亮光照，且会再额外散发出60尺微光光照。\n或者，你可以将此法术施展于一个未被着装或携带的物件上，使日光充斥以该物件为中心的60尺光环区域。将该物件用不透明的东西遮掩（比如用碗或头盔盖住）时，会将日光隔绝。\n如果法术区域与任何三环或更低环阶法术创造的黑暗 区域重叠，则这些造暗的法术将被解除。","duration":"1小时","higherLevels":null,"id":"Daylight","level":3,"nameEn":"Daylight","nameZh":"昼明术","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","术士","魔契师","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"在施法距离内选择一名生物、一个物件或一处魔法效应。所有影响该目标的三环或更低环阶法术即告终止。每个影响目标的四环或更高环阶法术都需要以你的施法属性进行一次属性检定（DC 10+目标法术环阶），检定成功时目标法术终止。","duration":"立即","higherLevels":{"kind":"升环施法","text":"你自动终止影响目标的小于等于你用于施展该法术的环阶的法术。"},"id":"Dispel_Magic","level":3,"nameEn":"Dispel Magic","nameZh":"解除魔法","range":"120尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","圣武士","游侠","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你触碰的一把非魔法武器变成魔法武器。选择下述伤害类型之一：强酸、寒冷、火焰、闪电、雷鸣。法术持续时间内，用那把武器发动的攻击检定具有+1加值，且在命中时造成额外1d4点你所选伤害类型的伤害。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用五环或六环法术位时，攻击检定的加值变为+2，额外伤害变为2d4。使用七环或更高法术位时，攻击检定的加值变为+3，额外伤害变为3d4。"},"id":"Elemental_Weapon","level":3,"nameEn":"Elemental Weapon","nameZh":"元素武器","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一根白羽毛","raw":"V、S、M（一根白羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"30尺锥状区域内的所有生物必须通过一次感知豁免，豁免失败者将丢弃其所有持握物，并在法术持续时间内陷入恐慌状态。\n以此法被恐慌的生物必须在自己回合中执行疾走动作，并以此寻找最安全的路线远离你，直至其无路可走为止。如果该生物结束其回合时位于一处使其视觉线中没有你的空间，则其可以再进行一次感知豁免，豁免成功则法术对该生物的效应终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Fear","level":3,"nameEn":"Fear","nameZh":"恐惧术","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","牧师","德鲁伊","法师"],"components":{"material":true,"materials":"一撮墓土","raw":"V、S、M（一撮墓土）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名自愿生物并将其变得如死者般的僵直。\n在法术持续时间内，对目标进行的任何肉体检查和法术检测都显示目标已死亡。该状况下的目标陷入目盲以及失能状态，且其速度降至0。\n目标对除了心灵伤害外的所有伤害类型具有抗性，也免疫中毒状态。","duration":"1小时","higherLevels":null,"id":"Feign_Death","level":3,"nameEn":"Feign Death","nameZh":"假死术","range":"触碰","ritual":true,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一颗蝙蝠粪和硫磺搓成的小球","raw":"V、S、M（一颗蝙蝠粪和硫磺搓成的小球）","somatic":true,"verbal":true},"concentration":false,"description":"明亮的闪光从你的指间飞驰向施法距离内你指定的一点，并随着一声低吼迸成一片烈焰。目标点周围半径20尺球状区域内的每个生物必须进行一次敏捷豁免。豁免失败者将受到8d6点火焰伤害，豁免成功则伤害减半。\n区域内所有未被着装或携带的可燃物件会开始燃烧。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此伤害就增加1d6。"},"id":"Fireball","level":3,"nameEn":"Fireball","nameZh":"火球术","range":"150尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师","奇械师"],"components":{"material":true,"materials":"一根羽毛","raw":"V、S、M（一根羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"你触碰一个自愿生物。目标在法术持续时间内获得60尺的飞行速度且可以悬浮。法术终止时，如果目标仍在空中，否则其随即坠落，除非其有办法阻止坠落。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，你就可以额外再指定一名生物作为法术目标。"},"id":"Fly","level":3,"nameEn":"Fly","nameZh":"飞行术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":true,"materials":"一小块纱布","raw":"V、S、M（一小块纱布）","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，你将触碰到的一名自愿生物连同其穿着携带物一起转化为一团云雾。如果目标的生命值降至0或其用一个魔法动作终止其身上的法术效应，则该目标身上的法术终止。\n在该形态下，目标唯一的移动方式即是10尺的飞行速度，且可以悬浮。该目标可以进入并占据一个已有生物占据的空间。其拥有钝击、穿刺和挥砍伤害的抗性，其对倒地状态免疫，且进行的力量、敏捷、体质豁免具有优势。该目标可以穿过狭隙，但会将液态物质视为固体表面。\n云雾形态的目标不能讲话或操作物件，其随身携带或持握的物件不会掉落，也不能被使用或与之互动。另外，目标也不能攻击或施法。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，你就可以额外再指定一名生物作为法术目标。"},"id":"Gaseous_Form","level":3,"nameEn":"Gaseous Form","nameZh":"气化形体","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1小时","classes":["吟游诗人","牧师","法师","奇械师"],"components":{"material":true,"materials":"价值200GP+的钻石尘，作为法术耗材","raw":"V、S、M（价值200GP+的钻石尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"施展该法术时，你在某个表面（诸如桌面或地板）或某个能被关闭以隐藏刻纹的物件里（诸如书本或宝箱）刻画一个会释放魔法效应的刻纹。该刻纹可以覆盖直径不超过10尺的区域。如果受术的物件或表面从被施法位置被移开超过10尺，则其刻纹被破坏且法术不被触发即告终止。\n结界刻纹近乎不可察觉，其需要以你的法术豁免DC进行一次成功的感知（察觉）检定才能被发现。\n刻画刻纹时，你可以设定其触发条件，并从爆炸符文和法术刻纹两者中选择其一。\n设定触发条件Set the Trigger。你在施法时设定结界刻纹的触发条件。刻画于表面的刻纹其最典型的触发条件包括：触碰或站立在刻纹上；拿掉覆盖在刻纹上的物件；进入刻纹一定范围。刻画在物件内的刻纹其最典型的触发条件包括：打开物件；看到该刻纹。刻纹一旦被触发，则该法术终止。你可以进一步细化触发条件，比如设定只有特定生物种类（例如设定为只影响异怪Aberration）才能触发刻纹。你还可以为生物设置不触发刻纹的条件，诸如某人说出特定口令。爆炸符文Explosive Runes。符文被触发时将在半径 20尺球状区域内爆发魔法能量。区域内的每个生物必须进行一次敏捷豁免。豁免失败者将受到5d8点强酸，寒冷，火焰，闪电，或雷鸣伤害（你在制造刻纹时指定），豁免成功则伤害减半。法术刻纹Spell Glyph。作为创造符文的一部分，你可以施展一道已准备的三环或更低环阶法术，并将其储备在所创造的刻纹中。所储备法术必须以单一生物或一个区域为目标，而被储存的法术以该方式施展时并不会立即生效。符文被触发时，所储备的法术即刻生效。如果法术有一个目标，则以触发刻纹的生物为目标；如果法术影响一个区域，则该区域以此生物为中心；如果法术召唤敌对Hostile生物或创造伤害性质的物件或陷阱，则这些造物将显现在尽可能靠近触发者的地方并攻击它。如果法术需要专注，则其效应将在其最大持续时间内维持。\n升环施法。使用的法术位每比三环高一环，此法术的爆炸符文的伤害就增加1d8。如果你创造一个法术刻纹，则其储备法术的环阶至高可以与你施展守卫刻纹时使用的法术位环阶相同。","duration":"直到被解除或触发","higherLevels":null,"id":"Glyph_of_Warding","level":3,"nameEn":"Glyph of Warding","nameZh":"守卫刻纹","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一片甘草根切片","raw":"V、S、M（一片甘草根切片）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内一个你能看见的自愿生物。直至法术终止前，目标速度翻倍；其AC获得+2加值；其进行敏捷豁免时具有优势；其每个回合都可作出一个额外的动作，但该动作只能用于执行攻击动作（仅一次攻击），或者疾走、撤离、躲藏和操作动作。\n法术终止时，目标将泛起一阵倦意使其失能并且速度为0，持续至其下一回合结束。","duration":"专注，至多1分钟","higherLevels":null,"id":"Haste","level":3,"nameEn":"Haste","nameZh":"加速术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师"],"components":{"material":true,"materials":"一条酸洗过的触须","raw":"V、S、M（一条酸洗过的触须）","somatic":true,"verbal":true},"concentration":true,"description":"你打开了通往遥远国度的大门，展现其中难以名状的恐怖。以施法距离内一点为中心，一个半径 20 尺的黑暗球状区域显现并持续至该法术终止。这个球状区域是困难地形，并同时发散着能在30尺内听到的不谐耳语和啜嚼噪音。任何光照，无论是魔法光照还是其他光照都无法照亮这个区域，而完全进入该区域内的生物将陷入目盲状态。\n任何在区域内开始其回合的生物将受到 2d6 点寒冷伤害。任何在区域内结束其回合的生物必须进行一次敏捷豁免，豁免失败者将因异界软体触手的触碰而受到2d6点强酸伤害。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术造成的寒冷或者强酸伤害（由你选择）就增加1d6。"},"id":"Hunger_of_Hadar","level":3,"nameEn":"Hunger of Hadar","nameZh":"哈达之欲","range":"150尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一撮五彩纸屑","raw":"S、M（一撮五彩纸屑）","somatic":true,"verbal":false},"concentration":true,"description":"你在施法距离内一处边长 30 尺的立方区域内创造出一个在空中舞动旋转的彩色图纹。图纹在出现片刻后消失，然后迫使区域内每个看到它的生物进行一次感知豁免，豁免失败者将在法术持续时间内陷入魅惑状态。在被该法术魅惑期间，被该法术魅惑的生物陷入失能状态，且速度降为0。\n如果受术生物受到任何伤害，或有其他生物用一个动作将其从恍惚中摇醒，则其身上的此效应将提前终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Hypnotic_Pattern","level":3,"nameEn":"Hypnotic Pattern","nameZh":"催眠图纹","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一个小水晶珠子","raw":"V、S、M（一个小水晶珠子）","somatic":true,"verbal":true},"concentration":false,"description":"你释放出半径10尺的光环，光环会在法术持续时间内保持存在并固定在原地。施展此法术时，若光环的大小不足以完全覆盖其区域内的所有生物，法术的施展会失败。\n在施展此法术时即处于光环内的生物和物件可以自由进出光环。而所有其他生物和物件都将被阻挡而无法进出。三环或更低级别的法术既无法直接穿过光环施展，也无法使法术效果延伸至穿过光环。\n光环内的空气干爽舒适，而无论外侧气候如何。你可以在法术终止前使光环内的光照变为微光光照或黑暗（无需任何动作）。光环从外侧看是不透明的，并且呈现出由你选定的颜色，但从内侧看它则是透明的。\n当你离开该区域，或试图再次施展该法术时，法术将提前终止。","duration":"8 小时","higherLevels":null,"id":"Leomund's_Tiny_Hut","level":3,"nameEn":"Leomund's Tiny Hut","nameZh":"李欧蒙小屋","range":"自身","ritual":true,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作，在你使用武器发动远程攻击命中一个目标或失手时紧接可用","classes":["游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"当你的攻击命中一个目标或失手时，该武器的弹药或该武器本身变为一束闪电。作为目标从这次攻击中受到的任何伤害或其他效果的替代，若该攻击命中，则目标受到4d8点闪电伤害，若该攻击未命中，则受到一半伤害。无论你的攻击是否命中，目标周围10尺范围内的每个生物都必须进行一次敏捷豁免，豁免失败则受到2d8点闪电伤害，豁免成功则受到半数伤害。\n在此之后，该弹药或武器变回其正常形态。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，上述两种效应的伤害都各增加1d8。"},"id":"Lightning_Arrows","level":3,"nameEn":"Lightning Arrows","nameZh":"闪电箭矢","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一些毛皮和一把水晶权杖","raw":"V、S、M（一些毛皮和一把水晶权杖）","somatic":true,"verbal":true},"concentration":false,"description":"一束100 尺长，5尺宽的线状闪电从你的位置向你指定的方向爆发迸出。在线状区域内的每个生物必须进行一次敏捷豁免，豁免失败者将受到8d6点闪电伤害，豁免成功则受到一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就增加1d6。"},"id":"Lightning_Bolt","level":3,"nameEn":"Lightning Bolt","nameZh":"闪电束","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["牧师","圣武士","魔契师","法师"],"components":{"material":true,"materials":"总价值100GP+的盐和银粉，作为法术耗材","raw":"V、S、M（总价值100GP+的盐和银粉，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"指定施法距离内地面上你能看见的一点，并以该处为中心创造一个 10 尺半径、20 尺高的柱状魔法能量。承载能量柱的地面或其他平面上会显现出闪光的符文。\n指定以下生物类型中的一种或多种：天族、元素、妖精、邪魔、亡灵。法阵将会对被指定类型的生物产生以下效应：\n该类生物不能以非魔法手段主动进入柱状区域内。如果该类生物试图使用传送或位面旅行进入此区域，则它必须先进行一次魅力豁免以判定其是否成功。 该类生物对柱状区域内的生物进行攻击检定时具有劣势。 柱状区域内的目标不受该类生物所魅惑、恐慌、或附身 。\n施展该法术时，你可以选择让魔法作用于相反的方向来阻止特定种类的生物离开柱状区域内，以保护区域外的目标。升环施法。使用的法术位每比三环高一环，法术持续时间就增加 1 小时。","duration":"1小时","higherLevels":null,"id":"Magic_Circle","level":3,"nameEn":"Magic Circle","nameZh":"防护法阵","range":"10尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一撮羊毛","raw":"V、S、M（一撮羊毛）","somatic":true,"verbal":true},"concentration":true,"description":"你创造一个影像，其形象来自一个大小不超过边长20尺立方体的物件或生物，或是其他的可视现象。影像出现在施法距离内你能看见的一处位置并在法术持续时间内维持存在。它看起来完全是真实的，并且还具有相应的声音、气味和温度。但它无法造成伤害或让人陷入任何状态。\n在该幻象施法距离内时，你可以用一个魔法动作将影像移动到施法距离内的另一个位置。影像改变位置时，你可以改变影像的外表来使它移动得更自然。例如，如果你创造了一个生物的影像并移动它，则你可以改变影像，使它看起来就像是在走路。或者你也可以让影像在不同的时间发出不同的声音，甚至可以让它参与一场对话。\n由于影像可以被穿过，任何与该影像进行的物理互动都会暴露其幻象的本质。一个生物用研究动作调查影像时，它可以进行一次对抗你的法术豁免 DC 的智力（调查）检定，以判定是否看穿幻象。辨出幻象的生物可以看破该影像，而影像的其他感官效应在该生物看来会变得微弱而模糊。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用高于三环的法术位时，法术时间持续至被解除且无需专注。"},"id":"Major_Image","level":3,"nameEn":"Major Image","nameZh":"高级幻影","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["吟游诗人","牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"指定施法距离内至多六个你能看见的生物，使它们恢复 2d4+你的施法属性调整值 点生命值。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的治疗量就增加1d4。"},"id":"Mass_Healing_Word","level":3,"nameEn":"Mass Healing Word","nameZh":"群体治愈真言","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你进入一个足以完全容纳你身体的石料物件或石料表面内，使你自己和你携带的所有装备在法术持续时间内与石料融为一体。你必须触碰该石料来做到这件事。此后，任何非魔法的感官都无法看到或侦测到你的存在。\n与石料融合后，你看不到外界发生了什么，并且你为了聆听外界声音而进行的任何感知（察觉）检定都具有劣势。与石头融合时，你仍能感觉到时间的流逝，也可以对自己施展法术。你无法移动，但可以消耗5尺移动力从进入石头的地方离开石内，法术随之终止。\n石头所受的轻微损伤不会对你造成伤害，不过石头部分损毁或者形状改变时（改变到不再适合容纳你的程度），会将你从石中排挤出并对你造成6d6点力场伤害。石头完全损毁（或材质改变）时，也会将你从石中排挤出并对你造成50点力场伤害。被排挤出石头时，你移动至距离第一次进入石头处最近的一处未占据空间位置，并陷入倒地状态。","duration":"8小时","higherLevels":null,"id":"Meld_Into_Stone","level":3,"nameEn":"Meld Into Stone","nameZh":"融身入石","range":"触碰","ritual":true,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","游侠","法师"],"components":{"material":true,"materials":"一撮价值25+GP的钻石尘，作为法术耗材","raw":"V、S、M（一撮价值25+GP的钻石尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"法术持续时间内，你使你触碰的目标不会被预言法术发现。目标可以是一名自愿生物，或者是在任何方向上都不超过10尺的一处地点或一个物件。目标不能被任何预言法术选为目标，也不能被魔法探知传感器感测到。","duration":"8小时","higherLevels":null,"id":"Nondetection","level":3,"nameEn":"Nondetection","nameZh":"回避侦测","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一匹拟真的大型马形生物出现在施法距离内你选择的一处地面上的未占据空间中。你决定该生物的样貌，且它装备着鞍座、嚼子和缰绳。这些随法术创造的装备一旦离开坐骑10尺即化作一阵烟消失不见。\n在法术持续时间内，你或者一名你指定的生物可以骑乘此坐骑。坐骑使用乘用马Riding Horse的数据（见附录B），不过其具有100尺速度，每小时可行进13里。法术终止时，坐骑会慢慢消失，骑手有1分钟的时间下马。坐骑受到伤害时，法术将提前终止。","duration":"1小时","higherLevels":null,"id":"Phantom_Steed","level":3,"nameEn":"Phantom Steed","nameZh":"魅影驹","range":"30尺","ritual":true,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作（繁茂）或8小时（丰产）","classes":["吟游诗人","德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"该法术将活力引导给特定区域中的植物。本法术的施法时间取决于你选择下述效应之一：繁茂或丰产。\n繁茂Overgrowth。 你指定施法距离内一点，以该点为中心100尺半径的球状范围内的普通植物将变的粗壮繁茂。一名穿过该区域的生物每移动1尺必须花费4尺移动力。你可以在该法术范围内空出一块或多块任意大小的区域，将其排除在法术效应影响之外。丰产Enrichment。 你指定施法距离内一点，距该点半里内的植物的产量将在365日内被强化。这些植物收获时将产出两倍于正常产量的作物。这些植物每年仅能从一道植物滋长中获益。","duration":"立即","higherLevels":null,"id":"Plant_Growth","level":3,"nameEn":"Plant Growth","nameZh":"植物滋长","range":"150尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"法术持续时间内，你触碰的一名自愿生物具有你选择的一种伤害类型的抗性：强酸、寒冷、火焰、闪电、雷鸣。","duration":"专注，至多1小时","higherLevels":null,"id":"Protection_from_Energy","level":3,"nameEn":"Protection from Energy","nameZh":"防护能量","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名生物或一个物件，使影响其的所有诅咒终止。如果该物件是一件诅咒魔法物品，则其上的诅咒将维持，不过该法术可以打破诅咒物品与其所有者之间的同调，使其所有者可以将其卸下或丢弃。","duration":"立即","higherLevels":null,"id":"Remove_Curse","level":3,"nameEn":"Remove Curse","nameZh":"移除诅咒","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":true,"materials":"一颗价值300+GP的钻石，作为法术耗材","raw":"V、S、M（一颗价值300+GP的钻石，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你接触在前一分钟内刚刚死亡的一名生物。该生物以1点生命值回生。该法术不能复活老死的生物，也不能恢复失去的身体部位。","duration":"立即","higherLevels":null,"id":"Revivify","level":3,"nameEn":"Revivify","nameZh":"回生术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","法师"],"components":{"material":true,"materials":"一段铜线","raw":"V、S、M（一段铜线）","somatic":true,"verbal":true},"concentration":false,"description":"你向你所遇到过的或某人遇到过且向你描述的一个生物发送一小段二十五个词以内的信息。该生物将在心中听到你的信息，它可以认出你是发讯人（如果他认识你），还可以用同样的方式立即回复一条讯息。法术会让目标能够理解你短讯的信息。\n你的传讯可以跨越任意长的距离，甚至能跨越位面。但如果目标和你不在同一个存在位面，则短讯术有5%的概率无法到达。如果讯息没能传达，你将得知这一结果。\n在收到你的信息后，一个生物能够屏蔽你以这个法术再次对他发信的能力，持续8小时。如果你在这段时间内试图送出另一条信息，你会得知你的短讯被屏蔽，并且法术失败。","duration":"立即","higherLevels":null,"id":"Sending","level":3,"nameEn":"Sending","nameZh":"短讯术","range":"无限","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一把迷你雨伞","raw":"V、S、M（一把迷你雨伞）","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，并使以该点为中心，高40尺、半径20尺的柱状区域内降下冷冻刺骨的冻雨和冰雹直至法术终止。该区域将造成重度遮蔽，且该区域内的一切外露的暴露在外的明火都将被浇熄。\n该区域的地面变成困难地形。生物在一个回合内首次进入该区域或在区域内开始其回合时，它必须成功通过一次敏捷豁免，否则将陷入倒地状态并失去专注。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Sleet_Storm","level":3,"nameEn":"Sleet Storm","nameZh":"雪雨暴","range":"150 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一滴糖浆","raw":"V、S、M（一滴糖浆）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内一处 40 尺立方区域内指定至多六个生物并扭曲其周围的时间流。每个目标都要进行一次感知豁免，豁免失败则受到该法术影响直至法术终止。\n被影响的生物的速度减半，而其 AC 和敏捷豁免都获得-2减值，且不能执行反应。该生物在其回合中仅可以执行一个动作或一个附赠动作，但不能同时执行二者。且当它执行攻击动作时，它只能发动一次攻击。\n如果该生物尝试施展一个具有姿势成分的法术，则其法术有25%的概率会因为生物的动作太慢而施展失败。\n受术生物在其每个回合结束时可以再进行一次该感知豁免，豁免成功则终止其身上的该法术效应。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Slow","level":3,"nameEn":"Slow","nameZh":"缓慢术","range":"120 尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","法师"],"components":{"material":true,"materials":"燃烧的香","raw":"V、S、M（燃烧的香）","somatic":true,"verbal":true},"concentration":false,"description":"你给施法距离内一具你所选择的尸体施以复生的表象，让其可回答你的问题。这具尸体必须还有一张嘴，且如果该生物死亡时是亡灵生物，则施法失败。若目标尸体在最近十日内曾被作为该法术的目标，则本次施法失败。\n在法术终止前，你可以向尸体提出最多五个问题。尸体的知识和它讲述的语言仅限于其生前所知。回答通常是简短，含糊或重复的语句，而且如果你对尸体抱有敌意或者尸体认为你是其敌人，它也不是一定要给你正确的答复。该法术并不能让该生物的灵魂返回其身体中，只是活化了其精神。因此，该尸体不能认知新的信息，不能理解它死后发生的任何事情，也不能对未来的事件作出猜测。","duration":"10 分钟","higherLevels":null,"id":"Speak_with_Dead","level":3,"nameEn":"Speak with Dead","nameZh":"死者交谈","range":"10 尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你给周围30尺固定灵光范围内的植物赋予有限的知觉与活力，使其能够与你沟通和按你的简单命令行事。你可以向植物询问最近一日该法术区域内所发生的事，由此了解有关于曾路过这里的生物、天气和其他状况的信息。\n你可以让区域内因植物生长形成的困难地形（如灌木丛）在法术持续时间内变为普通地形。你也可以在法术持续时间内将有植物生长的普通地形变成困难地形。\n虽然该法术并不能让植物拔根而起或移动位置，但它们可以依你的意愿而活动自己的树枝、藤蔓和茎秆。\n如果法术区域内有一个植物生物，你可以如同有共同语言一般与其交流。","duration":"10 分钟","higherLevels":null,"id":"Speak_with_Plants","level":3,"nameEn":"Speak with Plants","nameZh":"植物交谈","range":"自身（半径 30 尺）","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":true,"materials":"一卷祷文","raw":"V、S、M（一卷祷文）","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，保护性的灵体环绕在你的周围15尺光环区域内飞舞。如果你属于善良或中立阵营，则它们飘渺的身形看起来像是天使或妖精（由你选择）。如果你属于邪恶阵营，则它们将形如邪魔。\n施展此法术时，你可以指定特定生物让其不受该法术影响。除此之外的生物在光环区域内将受法术影响致速度被减半。当光环进入一个生物的空间、一个生物进入光环或在光环内结束回合时，其必须进行一次感知豁免。豁免失败将受到3d8光耀伤害（如果你属于善良或中立）或3d8暗蚀伤害（如果你属于邪恶），豁免成功则只受到一半伤害。一名生物一回合仅需进行一次该豁免。","duration":"专注，至多 10 分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就增加 1d8。"},"id":"Spirit_Guardians","level":3,"nameEn":"Spirit Guardians","nameZh":"灵体卫士","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一个臭鸡蛋","raw":"V、S、M（一个臭鸡蛋）","somatic":true,"verbal":true},"concentration":true,"description":"如果一个生物在其回合开始时位于云团内，则它必须成功通过一次体质豁免。否则将陷入中毒状态直到其当前回合结束。因此而陷入中毒状态期间，该生物无法执行动作或附赠动作。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Stinking_Cloud","level":3,"nameEn":"Stinking Cloud","nameZh":"臭云术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","魔契师","法师"],"components":{"material":true,"materials":"一朵价值300+GP的镀金花","raw":"V, S, M（一朵价值300+GP的镀金花）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个妖精灵魄。其使用下文妖精灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从愤怒、欢欣、诡诈中选择一种情绪，该生物会显现为一个受你所选情绪所影响的妖精生物，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n妖精灵魄Fey Spirit 小型妖精，中立 AC 12+法术环阶 HP 30+每比三环高一法术环阶10 速度 30尺，飞行30尺 调整豁免调整豁免调整豁免 力量13+1+1 敏捷16+3+3 体质14+2+2 智力14+2+2 感知11+0+0 魅力16+3+3 免疫 魅惑 感官 黑暗视觉60尺，被动察觉10 语言 木族语，理解你的语言 CR 无（XP0；PB等于你的熟练加值） 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的妖精之剑攻击（向下取整）。 妖精之剑Fey Blade。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：2d6+3+法术环阶的力场伤害。 附赠动作Bonus Actions 妖精步伐Fey Step。灵魄魔法地传送至多30尺至一处它可见的未占据空间。随后根据所选情绪，灵魄触发以下效果之一： 愤怒Fuming。妖精在此回合结束前的下一次攻击检定具有优势。 欢欣Mirthful。感知豁免：DC等于你的法术豁免DC，单一灵魄10尺内它可见的生物。失败：目标受你和灵魄魅惑1分钟或在目标受到任意伤害时提前结束。 诡诈Tricksy。灵魄令魔法黑暗充斥于它5尺内的一处10尺立方区域，持续至灵魄的下个回合结束。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Fey","level":3,"nameEn":"Summon Fey","nameZh":"妖精召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":true,"materials":"一个价值300+GP的镀金头骨","raw":"V, S, M（一个价值300+GP的镀金头骨）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个亡灵灵魄。其使用下文亡灵灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从幽体、腐尸、骸骨中选择一类，该生物会显现为你所选的那类形态的亡灵生物，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n亡灵灵魄Undead Spirit 中型亡灵，中立 AC 11+法术环阶 HP 30（仅幽体和腐尸）或20（仅骸骨）+每比三环高一法术环阶10 速度 30尺；飞行40尺（悬浮；仅幽体） 调整豁免调整豁免调整豁免 力量12+1+1 敏捷16+3+3 体质15+2+2 智力4-3-3 感知10+0+0 魅力9-1-1 免疫 暗蚀，毒素；力竭，恐慌，麻痹，中毒 感官 黑暗视觉60尺，被动察觉10 语言 理解你说的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 腐灭灵光Festering Aura（仅腐尸）。体质豁免：DC等于你的法术豁免DC，源自灵魄的5尺光环区域内开始其回合的每名生物（除你以外）。失败：该生物陷入中毒状态，直至其下个回合开始。 虚体通行Incorporeal Passage（仅幽体）。灵魄可以移动穿过其他生物或物件，如同穿过困难地形一般。在其回合结束时，若灵魄还处于物件内，则其被挪到距离最近的未占据空间，且每因此移动5尺便受到1d10力场伤害。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的攻击（向下取整）。 致死之触Deathly Touch（仅幽体）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+3+法术环阶的暗蚀伤害，且目标陷入恐慌状态直至其下个回合结束。暗澹箭Grave Bolt（仅骸骨）。远程攻击检定：加值等于你的法术攻击加值，射程150尺。命中：2d4+3+法术环阶的暗蚀伤害。 腐灭爪击Rotting Claw（仅腐尸）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d6+3+法术环阶的挥砍伤害。若目标已陷入中毒状态，则其还会陷入麻痹状态，直至其下个回合结束。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Undead","level":3,"nameEn":"Summon Undead","nameZh":"亡灵召唤术","range":"90 尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","术士","魔契师","法师"],"components":{"material":true,"materials":"一座微缩庙塔","raw":"V、M（一座微缩庙塔）","somatic":false,"verbal":true},"concentration":false,"description":"此法术赋予你触碰的一名生物理解任何其能看见或听见的口语或手语的能力。此外，当目标生物以口语或手语进行交流时，任何能听见其话语或看见其手语，且知道至少一门语言的生物都能理解它。","duration":"1小时","higherLevels":null,"id":"Tongues","level":3,"nameEn":"Tongues","nameZh":"巧言术","range":"触碰","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你的阴影环绕着的手可以吸取他人的生命力来为自己疗伤。对你触及范围内的一名生物进行一次近战法术攻击。若命中，则目标受到3d6点暗蚀伤害，而你则恢复数值等同于所造成暗蚀伤害一半的生命值。\n该法术终止前，你可以在你的每个回合内用魔法动作对相同或不同的生物进行一次这样的攻击。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比三环高一环，此法术的伤害就提高1d6。"},"id":"Vampiric_Touch","level":3,"nameEn":"Vampiric Touch","nameZh":"汲血之触","range":"自身","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":true,"materials":"一根短芦苇","raw":"V、S、M（一根短芦苇）","somatic":true,"verbal":true},"concentration":false,"description":"在法术终止前，该法术让施法距离内你所选择的至多十个自愿生物获得在水下呼吸的能力。此外，受术者依然保有正常的呼吸能力。","duration":"24小时","higherLevels":null,"id":"Water_Breathing","level":3,"nameEn":"Water Breathing","nameZh":"水下呼吸","range":"30尺","ritual":true,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","德鲁伊","游侠","术士","奇械师"],"components":{"material":true,"materials":"一个软木塞","raw":"V、S、M（一个软木塞）","somatic":true,"verbal":true},"concentration":false,"description":"此法术赋予你选择的位于施法距离内的至多十名生物在持续时间内将任何液体表面（比如水、酸、泥、雪、流沙、岩浆等）视作无害的固体地面穿越的能力（穿越熔岩的生物仍然会因炽热受到伤害）。\n一名受影响的目标必须用一个附赠动作才能穿过液体表面进入其内部，反之亦然。然而若目标将因坠落而进入液体中，则其会直接穿过液体表面，如常进入其内部。","duration":"1小时","higherLevels":null,"id":"Water_Walk","level":3,"nameEn":"Water Walk","nameZh":"水上行走","range":"30尺","ritual":true,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":true,"materials":"一把扇子和一根羽毛","raw":"V、S、M（一把扇子和一根羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内地面上一点并从中升起了一道强风形成的墙壁。你可以造出长度至多 50 尺、高度至多15尺、厚度至多1尺的风墙。你可以自由塑造该墙的形状，不过它必须沿着地面形成一条连续的轨道。风墙持续存在至法术终止。\n风墙出现时，所有位于风墙所占据区域内的生物必须进行一次力量豁免。豁免失败，受到4d8点钝击伤害。豁免成功，则只受一半伤害。\n强风可以阻隔浓雾、烟尘和其他气体。体型为小型或更小的飞行生物或物件无法穿过风墙。重量轻的物质带进风墙中时将被向上吹飞。对墙后目标射出的箭、矢和其他普通飞行物会被朝上吹走而直接判为打失。巨人或攻城器械投出的巨石和类似的飞行物不受影响。处于气化形态的生物无法穿过风墙。","duration":"专注，至多1分钟","higherLevels":null,"id":"Wind_Wall","level":3,"nameEn":"Wind Wall","nameZh":"风墙术","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一点蝙蝠毛皮","raw":"V、S、M（一点蝙蝠毛皮）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内创造出一个漂浮在空中，不受伤害的隐形魔法眼。你通过精神连接接收秘法眼传来的视觉信息。秘法眼拥有30尺黑暗视觉且可以观察任何方向。\n以一个附赠动作，你可以让秘法眼向任意方向移动30尺。固体障碍物会阻挡秘法眼的移动，但它可以穿过任何直径大于1寸的缝隙。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Arcane_Eye","level":4,"nameEn":"Arcane Eye","nameZh":"秘法眼","range":"30 尺","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"一道灵光自你身上发出并形成 30 尺半径的光环。在灵光范围内时，你和你的盟友获得对暗蚀伤害的抗性，生命值上限也无法被降低。另外，生命值为0的盟友在灵光范围内开始其回合时，恢复1点生命值。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Aura_of_Life","level":4,"nameEn":"Aura of Life","nameZh":"生命灵光","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"一道灵光自你身上发出并形成 30 尺半径的光环。在灵光范围内时，你和你的盟友获得毒素伤害的抗性，并且在为抵抗和结束下列状态所做的豁免时具有优势：目盲、魅惑、耳聋、恐慌、麻痹、中毒、震慑 。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Aura_of_Purity","level":4,"nameEn":"Aura of Purity","nameZh":"净化灵光","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士","术士","魔契师","法师"],"components":{"material":true,"materials":"一颗五芒星","raw":"V、S、M（一颗五芒星）","somatic":true,"verbal":true},"concentration":true,"description":"一个在你施法距离内你可见的生物必须进行一次魅力豁免，豁免失败者会在法术持续期间被转移到一个无害的半位面，身处半位面期间，目标会陷入失能状态。当法术终止时，目标将重新出现在其被放逐前的位置。如果该位置被占据，则目标将出现在距离该位置最近的一个未占据空间。\n若该目标的生物类型为异怪、天族、元素、妖精或邪魔，则在法术持续一分钟后，目标不会返回。该目标会被改为转移到与其生物类型相关的一个位面（由DM决定）中的随机地点。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，你就能多指定一个生物作为此法术的目标。"},"id":"Banishment","level":4,"nameEn":"Banishment","nameZh":"放逐术","range":"30尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一个在你施法距离内你可见的生物必须进行一次体质豁免，豁免失败者受到8d8暗蚀伤害，成功则只受到一半伤害。生物类型为植物的生物在此豁免中自动失败。\n作为此法术的另一种用法，你可以指定一个并非生物的非魔法植物为目标（如树木或灌木），该植物不进行豁免，直接凋谢死亡。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的伤害就提升1d8。"},"id":"Blight","level":4,"nameEn":"Blight","nameZh":"枯萎术","range":"30尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一名你可见的施法距离内的生物进行一次感知豁免，如果你或者你的盟友正在与它战斗，它在这次豁免上具有优势。豁免失败，则目标陷入魅惑状态直至法术结束，或在你或你的盟友对它造成伤害时提前结束。魅惑生物将对你友好。当法术结束时，目标会知道它曾被你魅惑。","duration":"1 小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，你就可以额外指定一名生物作为此法术的目标。"},"id":"Charm_Monster","level":4,"nameEn":"Charm Monster","nameZh":"魅惑怪物","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"每名你所选择的，施法距离内你可见的生物必须成功通过一次感知豁免，否则陷入魅惑状态直至法术结束。\n法术持续期间，你能够以一个附赠动作指向你的某个水平方向。随后，每个魅惑目标在其下一回合里必须使用其所有的移动力，采取最安全的路线，尽可能的向该方向移动。在以此法移动后，目标可以重新豁免，豁免成功则结束其身上该法术的效应。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Compulsion","level":4,"nameEn":"Compulsion","nameZh":"强迫术","range":"30 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","法师"],"components":{"material":true,"materials":"三颗坚果壳","raw":"V、S、M（三颗坚果壳）","somatic":true,"verbal":true},"concentration":true,"description":"你选择施法距离内一点为中心，半径10尺球状区域内的每名生物必须成功通过一次感知豁免，否则目标不能执行反应和附赠动作，并且必须在其每个回合开始时掷1d10，根据下表内容来决定当前回合的行为。\n1d10 当前回合行为 1 目标不执行任何动作，并使用所有移动力来进行移动。投掷1d4决定其方向：1，北；2，东；3，南；4 ，西。 2-6 目标不进行移动也不执行任何动作。 7-8 该生物不进行移动，执行攻击动作来对其触及内一名随机生物发动一次近战攻击。如果没有生物在其触及内，则目标本回合不执行任何动作。 9-10 该生物自行决定当前回合行为。\n受影响的目标在其每个回合结束时，重新进行该豁免，成功则其身上该法术的效应提前结束。升环施法。 使用的法术位每比四环高一环，此法术的球状区域半径就增加5尺。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Confusion","level":4,"nameEn":"Confusion","nameZh":"困惑术","range":"90 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你在持续时间内将来自元素位面的精魂咒唤在你身周15尺光环区域内，让它们环绕着你飞舞。直到法术结束为止，你进行的任何攻击检定命中光环区域内的生物时，都会额外造成2d8点伤害。额外伤害的类型为强酸、寒冷、火焰或闪电的一种（在你发动攻击时选择）。\n此外，光环区域内的地面对你的敌人而言是困难地形。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的伤害就增加1d8。"},"id":"Conjure_Minor_Elementals","level":4,"nameEn":"Conjure Minor Elementals","nameZh":"咒唤微元素群","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你在持续时间内将许多自然精魂咒唤在你身周10尺光环区域内。每当光环区域进入一名你可见生物所在的空间时、一名你可见的生物进入光环区域或是在该区域结束其回合时，你都可以迫使该生物进行一次感知豁免检定。失败则该生物受到5d8力场伤害，成功则只受一半伤害。一名生物一回合只需要进行一次该豁免。\n此外，在持续时间内，你能够以附赠动作执行撤离动作。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的伤害就增加1d8。"},"id":"Conjure_Woodland_Beings","level":4,"nameEn":"Conjure Woodland Beings","nameZh":"咒唤林地卫士","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","法师"],"components":{"material":true,"materials":"水尘混合物","raw":"V、S、M（水尘混合物）","somatic":true,"verbal":true},"concentration":true,"description":"你控制你指定的一处边长至多100尺的立方区域中的任意水体直至法术结束，从以下效应中选择其一生效。在后续的你的回合中，你能够以一个魔法动作重复同一效应，或是选择另一效应。\n上涨Flood。你使控制区域内的水位上涨20尺。如果你指定的区域是一片大水体中的一部分，则你改为制造一片20尺高的波浪，并在从区域的一边扑向另一边后崩溃。波浪中任何巨型或更小的载具都会被波浪带到区域的另一边。且所有巨型或更小的载具都有25%的几率倾覆。直至法术结束或你选择另一个效应，水位将维持上涨。如果该效应用以产生波浪，则你维持上涨期间，波浪在你的回合开始时重新出现。分水Part Water。你使区域内的水体分开并形成一条水体的沟壑。沟壑从法术区域的一头延伸到另一头，而被分开的水体则在两边形成两道水墙。沟壑持续存在，直至法术结束或你选择另一个效应。该效应终止时，水流会在下一轮中逐渐将沟壑填满，直至其恢复成通常的水位。转向Redirect Flow。你使区域内的流水向一个你自选的方向流动，即使水流需要绕过障碍、沿着墙壁向上流、或是流向一些不太可能的方向，区域内的水体都将遵照你指使的方向流动，但一旦其流出法术区域，则会重新基于其所在地形改变流向。水体持续向你所选方向流动，直至法术结束或你选择另一个效应。漩涡Whirlpool。该效应需要水体至少为50尺的方形区域并且至少有25尺深。你在区域中央形成一个漩涡。漩涡持续存在，直至法术结束或你选择另一个效应。漩涡的形态为底部宽5尺，顶部至多宽50尺，高25尺。水中任何位于漩涡25尺内的生物或物件均被漩涡向自身拉动10尺。当一名生物在一个回合内第一次进入漩涡或在漩涡内结束其回合时，进行一次力量豁免。豁免失败受到2d8点钝击伤害。豁免成功则只受一半伤害。一名生物若想以游泳方式离开漩涡，则必须先执行一个动作来远离漩涡并成功通过一次对抗你法术豁免DC的力量（运动）检定。","duration":"专注，至多10分钟","higherLevels":null,"id":"Control_Water","level":4,"nameEn":"Control Water","nameZh":"操控水体","range":"300尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你触摸一名生物，并给予其对死亡的防护。在法术结束前，当目标的生命值首次降至0时，该目标的生命值改为降至1，随后法术终止。\n目标受到直接致死而不造成伤害的效应影响时，若该法术仍在生效，则改为目标受到的致死效应失效，随后法术终止。","duration":"8小时","higherLevels":null,"id":"Death_Ward","level":4,"nameEn":"Death Ward","nameZh":"防死结界","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你将传送至施法距离内的一处地点。你会准确到达该目的地。法术的目的地可以是你能看见的、可想象的地点，也可以是通过距离和方向说明的地点，比如“径直向下200尺”，“西北偏上45度300尺”。\n你还可以带上一名自愿生物一同传送。该生物在你传送时必须距你5尺内，且其传送终点也位于你所选目的地的5尺内。\n如果你、你携带的生物、或两者均将被传送至一处已被一名生物占据、或被一个或更多物件填满的空间中，则你和任何与你一起传送的生物都将受到4d6点力场伤害，且传送失败。","duration":"立即","higherLevels":null,"id":"Dimension_Door","level":4,"nameEn":"Dimension Door","nameZh":"任意门","range":"500尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["牧师","德鲁伊","法师"],"components":{"material":true,"materials":"价值25+GP的熏香，作为法术耗材","raw":"V、S、M（价值25+GP的熏香，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"此法术让你得以与一名神祇或其仆人取得联络。你可以就某个未来7日内将要发生的特定目标、事件或活动提出一个问题。DM将给予你真实的答复，这个答复可能是一段短语或一节神秘的短诗。此法术的回答并不会顾及所有可能影响结果的情况。例如其他法术的影响。\n若你在完成一次长休前施展多于一次该法术，则法术有概率不给出任何结果。此概率从第二次施展起每次累计25％。","duration":"立即","higherLevels":null,"id":"Divination","level":4,"nameEn":"Divination","nameZh":"预言术","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","术士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一名施法距离内你可见的野兽必须成功于一次感知豁免，否则在持续时间内陷入魅惑状态。若你或你的盟友正在与其战斗，则目标进行的此次豁免具有优势。目标受到伤害时，可以重复进行豁免，豁免成功则其身上的此法术终止。\n该野兽被魅惑期间，只要你与其处于同一位面就可以与之保持心灵感应。在你的回合，你可以通过心灵感应命令该生物（无需动作），比如“攻击那个生物”“跑到那个位置”或是“去拿那个物品”。该生物会在其回合内尽其所能以遵守你的指令。生物完成一项指令却未收到你的进一步指示时，将会凭自身喜好行动，尽可能的保护自己。\n你可以用自己的反应去要求目标执行一项反应。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用更高环阶法术位施展时，你的专注能持续更长时间，五环至多10分钟，六环至多1小时，七环及以上至多8小时。"},"id":"Dominate_Beast","level":4,"nameEn":"Dominate Beast","nameZh":"支配野兽","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一根触手","raw":"V、S、M（一根触手）","somatic":true,"verbal":true},"concentration":true,"description":"蠕动的乌黑触须填满了一处施法距离内你可见的20尺方状地面。在法术持续时间内，这些触手会将此区域地面变为困难地形。\n每名区域内的生物进行一次力量豁免。豁免失败受到3d6点钝击伤害，并且直到法术结束为止陷入束缚状态。一名进入此区域或在区域内结束回合的生物也要进行此豁免。一名生物一回合只进行一次此豁免。\n一名被束缚的生物可以用一个动作进行一次力量（运动）检定对抗你的法术豁免DC，若检定成功则结束其身上的束缚状态。","duration":"专注，至多1分钟","higherLevels":null,"id":"Evard's_Black_Tentacles","level":4,"nameEn":"Evard's Black Tentacles","nameZh":"艾伐黑触手","range":"90尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你将一种原材料转化成该材料制作的成品。例如，你可以将一丛树木转化为一座木桥，一把麻草化为绳子，或是将亚麻和羊毛化作衣物。\n指定施法距离内你能看见的原材料。只要有足够的材料，你就可以将他们转化为一件体型不超过大型的物件（至多占据10尺立方区域或八个相邻的5尺立方区域）。如果你的目标材料是金属、石料或者其他矿石材料，那么被制造的物件不能大于中型（至多占据 5 尺立方区域），制成品的质量和原材料质量相同。\n该法术不能创造生物或魔法物品。你只有对制作某物品的工匠工具拥有熟练时，才能使用此法术去制作相应需要高工艺水平制作的物品，如武器、护甲等。","duration":"立即","higherLevels":null,"id":"Fabricate","level":4,"nameEn":"Fabricate","nameZh":"鬼斧神工","range":"120尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一小块磷或一只萤火虫","raw":"V、S、M（一小块磷或一只萤火虫）","somatic":true,"verbal":true},"concentration":false,"description":"轻薄缥缈的火焰在法术持续期间环绕着你的身体，散发出10尺半径的明亮光照和额外10尺的微光光照。\n这层火焰可以为你提供一面温暖护盾或冻寒护盾，由你选择。温暖护盾将赋予你对寒冷伤害的抗性，而冻寒护盾则会赋予你对火焰伤害的抗性。\n此外，每当一名距你5尺内的生物以一次近战攻击命中你时，这个护盾将迸发出火焰。温暖护盾将对攻击者造成2d8点火焰伤害，冻寒护盾将对攻击者造成2d8点寒冷伤害。","duration":"10分钟","higherLevels":null,"id":"Fire_Shield","level":4,"nameEn":"Fire Shield","nameZh":"火焰护盾","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一道冷冽光芒在法术持续时间内缭绕你身，散发出20尺半径的明亮光照和额外20尺的微光光照。\n直到法术结束，你具有光耀伤害的抗性，并且你的近战攻击在命中时额外造成2d6点光耀伤害。\n此外，在你受到距你60尺内一名你可见的生物的伤害后，你可以立即用一个反应，强迫其进行一次体质豁免。豁免失败者直到你的下个回合结束为止陷入目盲状态。","duration":"专注，至多10分钟","higherLevels":null,"id":"Fount_of_Moonlight","level":4,"nameEn":"Fount of Moonlight","nameZh":"月光涌泉","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","游侠","奇械师"],"components":{"material":true,"materials":"一条皮带","raw":"V、S、M（一条皮带）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个自愿生物，并使目标在法术持续时间内移动时不受困难地形限制，并且任何法术或其他魔法效应都不能降低目标的速度，或者使目标陷入麻痹或束缚状态。目标还会获得等同于其速度的游泳速度。\n此外，该目标还可以花费5尺移动力直接从非魔法的束缚物中挣脱（诸如镣铐或其他生物对其施加的受擒状态）。","duration":"1小时","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，你就可以额外再指定一名生物作为此法术的目标。"},"id":"Freedom_of_Movement","level":4,"nameEn":"Freedom of Movement","nameZh":"行动自如","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你召唤一只巨化的蜈蚣、蜘蛛或黄蜂（你施法时选择）。其使用下文巨虫Giant Insect的数据，并会在施法距离内一处你可见的未占据空间中显现。你选择的形态决定了其数据中的部分细节。该生物会在生命值降为0或是法术结束时消失。\n该生物是你和你盟友的盟友。它在战斗中使用你的先攻，并在你回合结束后立即执行其回合。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并使用其移动力以远离危险。\n巨虫Giant Insect 大型野兽，无阵营 AC 11+法术环阶 HP 30+每比四环高一法术环阶10 速度 40尺，攀爬40尺，飞行40尺（仅黄蜂） 调整豁免调整豁免调整豁免 力量17+3+3 敏捷13+1+1 体质15+2+2 智力4-3-3 感知14+2+2 魅力3-4-4 感官 黑暗视觉60尺，被动察觉12 语言 理解你所知晓的语言 CR 无（XP0；PB等同于你的熟练加值） 特质Traits 蛛行Spider Climb。 巨虫可以在难以攀爬的表面上攀爬，包括沿着天花板移动，且无需为此进行属性检定。 动作Actions 多重攻击Multiattack。巨虫发动等于法术环阶一半次数的攻击（向下取整）。 猛毒刺Poison Jab。近战攻击检定：加值等于你的法术攻击加值，触及10尺。命中：1d6+3+法术环阶的穿刺伤害+1d4点毒素伤害。 蛛网箭Web Bolt（仅蜘蛛）。远程攻击检定：加值等于你的法术攻击加值，射程60尺。命中：1d10+3+法术环阶的钝击伤害，且目标的速度降为0，直至巨虫的下个回合开始。 附赠动作Bonus Actions 剧毒喷涌Venomous Spew（仅蜈蚣）。体质豁免：DC等于你的法术豁免DC，单一10尺内巨虫可见的生物。失败：目标陷入中毒状态，直至巨虫的下个回合开始。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"在生物数据中使用更高的法术环阶。"},"id":"Giant_Insect","level":4,"nameEn":"Giant Insect","nameZh":"巨虫术","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一个你能够看见的未占据空间，并召唤一条藤蔓使其从该空间的地面上破土而出。藤蔓直到法术结束为止会一直存在。\n对一名距藤蔓30尺内的生物进行一次近战法术攻击。命中时，目标受到4d8点钝击伤害并被往藤蔓所在方向拉近30尺。如果目标体型不超过巨型，则目标同时陷入受擒状态（逃脱DC等同于你的法术豁免DC）。藤蔓在同一时间只能擒抱一名生物，但你随时可以让藤蔓放开一名受擒的生物（无需动作）。\n直至该法术终止前，你可以在你随后的回合里用一个附赠动作再次对一名距其30尺内的生物进行这样的攻击。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，藤蔓便可额外擒抱一名生物。"},"id":"Grasping_Vine","level":4,"nameEn":"Grasping Vine","nameZh":"擒抱藤","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"触碰一名生物，该生物直到法术结束之前具有隐形状态。","duration":"专注，至多1分钟","higherLevels":null,"id":"Greater_Invisibility","level":4,"nameEn":"Greater Invisibility","nameZh":"高等隐形术","range":"触碰","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"一名大型灵体守护者出现在施法距离内一处由你指定的，你可见且未占据空间，并在法术持续时间内在该处悬浮。占据该空间的守护者是无敌的，并且会以适合你神祇或神系的形态出现。\n任何敌人在一回合内首次进入距守护者10尺内或于其10尺内开始其回合时，必须进行一次敏捷豁免。豁免失败受到20点光耀伤害，豁免成功则伤害减半。守护者在造成总计60点伤害后随即消失。","duration":"8小时","higherLevels":null,"id":"Guardian_of_Faith","level":4,"nameEn":"Guardian of Faith","nameZh":"信仰守卫","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["吟游诗人","德鲁伊","魔契师","法师"],"components":{"material":true,"materials":"一颗蘑菇","raw":"V、S、M（一颗蘑菇）","somatic":true,"verbal":true},"concentration":false,"description":"你使施法距离内一处150尺立方区域内的自然地形在视觉、听觉、嗅觉上都像是另一种自然地形。因此，开阔的平原或者道路可能会变得像是一片沼泽，或是丘陵、裂谷以及其他难以通过，甚至是无法通过的地形。一个池塘可能变得看起来像一片草地，一个悬崖像是一个缓坡，或者使一条乱石沟像是一条宽阔平坦的道路。区域内经过加工的建筑、装备或生物的外表不会改变。\n地形的触觉特征不会改变，所以进入这片区域的生物可能会看穿幻象。如果触觉区别不明显，一个仔细调查幻象的生物可以采取研究动作，尝试进行一次对抗法术豁免 DC 的智力（调查）检定以识破之。对于一个识破了幻象本体的生物，幻象看起来就像是一层模糊的图像叠加在真实地形上。","duration":"24小时","higherLevels":null,"id":"Hallucinatory_Terrain","level":4,"nameEn":"Hallucinatory Terrain","nameZh":"幻景","range":"300尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一只连指手套","raw":"V、S、M（一只连指手套）","somatic":true,"verbal":true},"concentration":false,"description":"以施法距离内一点为中心的一处半径20尺，高40尺的柱状区域内，岩石般坚硬的冰雹重重地砸向地面。每个处在范围内的生物都必须进行一次敏捷豁免，豁免失败者将受到2d10点钝击伤害和 4d6 点寒冷伤害，豁免成功则受到一半伤害。\n冰雹使柱状区域内的地面变为困难地形，直至你的下一回合结束。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的钝击伤害就增加1d10。"},"id":"Ice_Storm","level":4,"nameEn":"Ice Storm","nameZh":"冰风暴","range":"300尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一个3尺×2尺×2尺、由稀有材料制成的、价值5000GP+的箱子；以及由同样材料制成的一个箱子的微缩模型（价值50GP+","raw":"V、S、M（一个3尺×2尺×2尺、由稀有材料制成的、价值5000GP+的箱子；以及由同样材料制成的一个箱子的微缩模型（价值50GP+））","somatic":true,"verbal":true},"concentration":false,"description":"你将一个箱子及其内容物藏在以太位面。你必须同时接触箱子和作为法术材料成分的微缩模型。箱子最多可容纳12立方尺的非活体物质（3×2×2 尺）。\n箱子处于以太位面时，你可以用一个魔法动作并触碰箱子的模型来召回箱子。箱子出现在你 5 尺内一个未占据空间的地面。随后，你可以使用一个魔法动作并同时触碰箱子与微缩模型来把箱子送回以太位面。\n60日之后，法术的效应会每日累计5%的概率自动结束。如果你再次施展该法术或箱子的模型被摧毁，该法术的效应也将随之终止。如果法术终止时箱子处于以太界，则其留在那里等待被你或者其他人找到。","duration":"直至解除","higherLevels":null,"id":"Leomund's_Secret_Chest","level":4,"nameEn":"Leomund's Secret Chest","nameZh":"李欧蒙秘藏箱","range":"触碰","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","法师"],"components":{"material":true,"materials":"一块寻血猎犬的皮毛","raw":"V、S、M（一块寻血猎犬的皮毛）","somatic":true,"verbal":true},"concentration":true,"description":"你点名或描述一个你熟悉的生物。只要该生物与你相距不超过1000尺，你就会感测到该生物的方位。如果该生物正在移动，则你也将知晓其移动的方向。\n如果有任意厚度的铅，即使只是薄薄一片铅片阻挡了你与被定位物件间的通路，则该生物也无法被该法术所定位。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Locate_Creature","level":4,"nameEn":"Locate Creature","nameZh":"生物定位术","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一支银哨","raw":"V、S、M（一支银哨）","somatic":true,"verbal":true},"concentration":false,"description":"指定施法距离内一处你能看见且未占据空间，你在该处创造出一只幻影守护犬。守护犬持续存在至法术结束或你们之间的距离超过300 尺。\n只有你能看见守护犬，它无法被触及且不会受伤。当一个体型不小于小型的生物进入守护犬 30 尺内时，如果该生物无法说出你在施法时设定的口令，守护犬则会开始大声吠叫。守护犬拥有30尺真实视觉。\n在你的每回合开始时，守护犬会尝试啮咬其5尺范围内的一个敌人。该生物进行一次敏捷豁免，失败则受到4d8点力场伤害。\n在你施展法术的后续回合里，你能够以一个魔法动作令守护犬移动至多30尺。","duration":"8小时","higherLevels":null,"id":"Mordenkainen's_Faithful_Hound","level":4,"nameEn":"Mordenkainen's Faithful Hound","nameZh":"魔邓肯忠犬","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["法师","奇械师"],"components":{"material":true,"materials":"一片薄铅","raw":"V、S、M（一片薄铅）","somatic":true,"verbal":true},"concentration":false,"description":"你对施法距离内一片区域施以魔法防护。该区域为一立方区域，其边长至小5尺，大至 100 尺。该法术持续至持续时间结束。\n施展该法术时，其提供的防护效应由你决定。从下列词条中选择一种或多种生效：\n声音不能穿透被保护区域边缘的障壁 被保护区域的障壁变得黑暗而模糊，无法通过视觉（包括黑暗视觉）看穿。 预言法术创造的传感器无法出现在被保护区域内，也无法穿过区域边界处的障壁。 区域内的生物不能成为预言法术的目标。 任何事物无法通过传送进出被保护区域。 在被保护区域内，位面旅行被封锁。\n当你每日在同一个位置施展此法术，持续365日后，法术将成为永久效应（直到被解除）。升环施法。使用的法术位每比四环高一环，此法术立方区域的边长就可以增加100尺。","duration":"24小时","higherLevels":null,"id":"Mordenkainen's_Private_Sanctum","level":4,"nameEn":"Mordenkainen's Private Sanctum","nameZh":"魔邓肯私人密室","range":"120尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一颗玻璃球","raw":"V、S、M（一颗玻璃球）","somatic":true,"verbal":true},"concentration":true,"description":"一颗微微发光的法球将施法距离内一个大型或更小的生物或物件封在其中。非自愿的生物必须成功通过一次敏捷豁免，否则在法术持续时间内被封在球体中。\n任何事物，包括实体物件、能量或其他法术效应，都不能穿透障壁进出其内，不过生物在球内仍可以正常呼吸。球体免疫一切伤害，且球内的生物或物件不能被来自球外的攻击或效应所伤害，球内的生物也不能对球外的任何事物造成伤害。\n该球体没有重量，而其尺寸恰好可以容纳球内的生物或物件。被封住的生物可以使用一个动作推动球壁并以至多该生物速度一半的速度滚动球体。另外，球体也可以被其他生物拿起或移动。","duration":"专注，至多1分钟","higherLevels":null,"id":"Otiluke's_Resilient_Sphere","level":4,"nameEn":"Otiluke's Resilient Sphere","nameZh":"欧提路克弹力法球","range":"30尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一名你可见的生物，窥探其噩梦，依此创造一道只有目标能看见的幻象。目标生物进行一次感知豁免。豁免失败时，目标受到4d10点心灵伤害，且在法术持续时间内进行的所有属性检定与攻击检定都具有劣势。豁免成功，则目标只受一半伤害，法术终止。\n法术持续时间内，目标在其每回合结束时进行一次感知豁免，豁免失败将再次受到心灵伤害。豁免成功则法术终止。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的伤害就增加1d10。"},"id":"Phantasmal_Killer","level":4,"nameEn":"Phantasmal Killer","nameZh":"魅影杀手","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","术士","法师"],"components":{"material":true,"materials":"一枚毛毛虫茧","raw":"V、S、M（一枚毛毛虫茧）","somatic":true,"verbal":true},"concentration":true,"description":"你尝试将施法距离内你可见的一名生物转变为一只野兽。目标必须成功于一次感知豁免，否则在持续时间内被变形为野兽形态。这种野兽形态可以是你所选的挑战等级不大于目标（若目标没有挑战等级，则使用目标的等级）的任意野兽。目标的游戏数据被替换为所选野兽的数据，但目标保留其阵营、性格、生物类型、生命值、生命值骰。\n目标获得等于其野兽形态生命值的临时生命值。法术结束时目标失去所有因此法术获得的临时生命值。此法术会在目标不具有剩余的临时生命值时提前结束。\n该生物只可做出其新形态的生理结构所允许的动作。它不能说话也不能施法。\n目标的装备融入新形态中。目标不能使用装备或者通过其他方式从装备中获得增益。","duration":"专注，至多1小时","higherLevels":null,"id":"Polymorph","level":4,"nameEn":"Polymorph","nameZh":"变形术","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到4d6点心灵伤害。该目标必须进行一次感知豁免，豁免失败则目标陷入震慑状态直到你的下个回合结束。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用高于四环的法术位施展本法术时，你使用的法术位每比四环高一环，额外伤害就增加1d6。"},"id":"Staggering_Smite","level":4,"nameEn":"Staggering Smite","nameZh":"惊惧斩","range":"自身","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","法师","奇械师"],"components":{"material":true,"materials":"软粘土","raw":"V、S、M（软粘土）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个体积为中型或更小的石质物件或某块岩石在任何方向都不超过 5 尺的一部分，并将其塑造成你想要的任意形状。例如你可以将一块大石头塑造成一件武器、一尊塑像、或一个保险箱，也可以在石墙上开出一条小通道，前提是墙的厚度不能超过 5 尺。你也可以使一扇石门或石质门框变形来将门封死。你创造的物件最多可以有两条铰链和一道闩，除此之外不能以该法术塑造出更复杂的机械结构。","duration":"立即","higherLevels":null,"id":"Stone_Shape","level":4,"nameEn":"Stone Shape","nameZh":"塑石术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","术士","法师","奇械师"],"components":{"material":true,"materials":"价值100GP+的钻石粉末，作为法术耗材","raw":"V、S、M（价值100GP+的钻石粉末，作为法术耗材）","somatic":true,"verbal":true},"concentration":true,"description":"在法术结束前，你触碰的一个自愿生物获得对钝击、穿刺、挥砍伤害的抗性。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Stoneskin","level":4,"nameEn":"Stoneskin","nameZh":"石肤术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":true,"materials":"一条腌制触手和一颗装在白金瓶中的眼球、价值400GP+","raw":"V, S, M（一条腌制触手和一颗装在白金瓶中的眼球、价值400GP+）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个异怪灵魄。其使用下文异怪灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从类眼魔，夺心魔和史拉蟾中选择一个类别。该生物会显化为你所选的那一类异怪，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并远离危险。\n异怪灵魄Aberrant Spirit 中型异怪，中立 AC 11+法术环阶 HP 40+每比四环高一法术环阶10 速度 30 尺；飞行30尺（悬浮；仅类眼魔） 调整豁免调整豁免调整豁免 力量16+3+3 敏捷10+0+0 体质15+2+2 智力16+3+3 感知10+0+0 魅力6-2-2 免疫 心灵 感官 黑暗视觉60尺，被动察觉10 语言 深潜语，理解你的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 再生Regeneration（仅史拉蟾）。若灵魄至少拥有1生命值，则其在自己回合开始时回复5生命值。 低语灵光Whispering Aura（仅夺心魔）。只要灵魄未陷入失能状态，其就会在自己的回合开始时释放灵能能量。感知豁免检定：DC等于你的法术豁免DC，灵魄5尺内的每名生物（除你以外）。失败：2d6心灵伤害 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的攻击（向下取整）。 爪击Claw（仅史拉蟾）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d10+3+法术环阶的挥砍伤害，目标无法恢复生命值直至灵魄的下个回合开始。 眼波射线Eye Ray（仅类眼魔）。远程攻击检定：加值等于你的法术攻击加值，射程150尺。命中：1d8+3+法术环阶的心灵伤害。 灵能猛击Psychic Slam（仅夺心魔）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+3+法术环阶的心灵伤害。","duration":"专注，至多 1 小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Aberration","level":4,"nameEn":"Summon Aberration","nameZh":"异怪召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师","奇械师"],"components":{"material":true,"materials":"一个金属密码箱、价值400GP+","raw":"V, S, M（一个金属密码箱、价值400GP+）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个构装灵魄。其使用下文构装灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从粘土、金属、岩石中选择一种材料，该生物会显现为以该种材料制成的活化雕像（由你决定其外观），其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并远离危险。\n构装灵魄Construct Spirit 中型构装，中立 AC 13+法术环阶 HP 40+每比四环高一法术环阶15 速度 30尺 调整豁免调整豁免调整豁免 力量18+4+4 敏捷10+0+0 体质18+4+4 智力14+2+2 感知11+0+0 魅力5-3-3 抗性 毒素 免疫 魅惑，力竭，恐慌，麻痹，中毒 感官 黑暗视觉60尺，被动察觉10 语言 理解你的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 灼热之躯Heated Body（仅金属）。当一名生物对灵魄发动近战攻击并命中，或是在擒抱灵魄或被灵魄擒抱期间开始其回合时，该生物受到1d10火焰伤害。 石迷昏眠Stony Lethargy（仅岩石）。当一名灵魄可见的生物在其10 尺内开始其回合时，灵魄可以将其指定为魔法能量的目标。感知豁免检定： DC等于你的法术豁免DC，目标。失败：目标无法发动借机攻击且速度减半，持续至其下个回合开始。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的猛击攻击（向下取整）。 猛击Slam。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+4+法术环阶的钝击伤害。 反应Reactions 狂怒乱击Berserk Lashing（仅粘土）。触发：生物对灵魄造成伤害。响应：灵魄对该生物发动一次猛击攻击（若可用），或灵魄向那名生物移动至多等于其速度一半的距离且不会引发借机攻击。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Construct","level":4,"nameEn":"Summon Construct","nameZh":"构装召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠","法师"],"components":{"material":true,"materials":"一个价值400GP+的、装有空气、一块鹅卵石、灰烬与水的镶金瓶","raw":"V, S, M（一个价值400GP+的、装有空气、一块鹅卵石、灰烬与水的镶金瓶）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个元素灵魄。其使用下文元素灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从气、土、火、水中选择一种元素，该生物会显现为由你所选元素组成的二足模糊人影，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n元素灵魄Elemental Spirit 中型元素，中立 AC 11+法术环阶 HP 50+每比四环高一法术环阶10 速度 40尺；掘穴40尺（仅土）；飞行40尺（悬浮；仅气）；游泳40尺（仅水） 调整豁免调整豁免调整豁免 力量18+4+4 敏捷15+2+2 体质17+3+3 智力4-3-3 感知10+0+0 魅力16+3+3 抗性 强酸（仅水），闪电和雷鸣（仅气），穿刺和挥砍（仅地） 免疫 火焰（仅火），毒素；力竭，麻痹，石化，中毒 感官 黑暗视觉60尺，被动察觉10 语言 原初语，理解你的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 不定形态Amorphous Form（仅气、火、水）。灵魄可以移动穿过最窄1寸宽的空间而不会将其视为困难地形。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的猛击攻击（向下取整）。 猛击Slam。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d10+4+法术环阶的钝击（仅土）、寒冷（仅水）、闪电（仅气）、火焰（仅火）伤害。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Elemental","level":4,"nameEn":"Summon Elemental","nameZh":"元素召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一滴胆汁","raw":"V、S、M（一滴胆汁）","somatic":true,"verbal":true},"concentration":false,"description":"你指向施法距离内一点，一颗发光的直径1尺的酸液球飞向那个位置，随后爆炸，波及20尺半径球状区域。在该区域中的每名生物进行一次敏捷豁免。豁免失败的生物不仅将受到10d4点强酸伤害，其下个回合结束时还将再受到5d4点强酸伤害。若豁免成功，该生物只受到初始伤害的一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术的初始伤害便增加2d4。"},"id":"Vitriolic_Sphere","level":4,"nameEn":"Vitriolic Sphere","nameZh":"浓酸球","range":"150尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一块木炭","raw":"V、S、M（一块木炭）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内一块固体表面上创造出一面火墙。你可以选择创造长不过 60 尺、高不过 20 尺、厚不过 1 尺的直线型火墙；或是直径不过 20 尺、高不过 20 尺、厚不过 1 尺的环形火墙。火墙不透明，且将持续存在至法术终止。\n火墙出现时，所有位于火墙所占据的区域内的生物必须进行一次敏捷豁免。豁免失败，受到 5d8 火焰伤害。豁免成功，则只受一半伤害。\n施展该法术时，你选择火墙的哪一侧会造成伤害。生物在火墙造成伤害一侧10尺内或火墙所占据的区域内结束其回合时将受到5d8火焰伤害。在一个回合内首次进入火墙或在火墙所占据的区域内结束自己的回合时也会受到同样的伤害。火墙的另一侧不会造成伤害。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比四环高一环，此法术造成的伤害就提高1d8。"},"id":"Wall_of_Fire","level":4,"nameEn":"Wall of Fire","nameZh":"火墙术","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"物件在你的命令下“活”了过来。在施法距离内指定一定数量的未被携带或着装、也未被固定在一处表面的非超巨型非魔法物件作为法术目标。可活化物件的最大数量等于你的施法属性调整值，中型或更小的目标计为一个物件，大型目标计为两个物件，巨型目标计为三个物件。\n被指定的目标会活化并长出腿来，变成一名构装，并使用活化物件的数据。该生物受到你的控制，直到法术结束或其生命值降低为0。你以该法术活化的每名生物都是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你的回合结束后立即进行其回合。\n直至法术结束前，你都可以使用一个附赠动作并以精神命令操纵距离你500尺内任何你用此法术唤起的生物（如果你操纵多个生物，则你的命令可以同时传达给它们全部或是其中的某几个，不过只能使用同一种命令）。如果你不发令，它将执行回避动作且只会为躲避危险而移动。当活化物件的生命值降低为0时，它将会变回其物件形态，并且该物件将承受由活化物件形态延续而来的所有剩余伤害。\n活化物件Animated Object 巨型（或更小）的构装，无阵营 AC 15 HP 10（中型及更小）、20（大型）、40（巨型） 速度 30尺 调整豁免调整豁免调整豁免 力量16+3+3 敏捷10+0+0 体质10+0+0 智力3-4-4 感知3-4-4 魅力1-5-5 免疫 毒素、心灵；魅惑、力竭、恐慌、麻痹、中毒 感官 盲视30尺，被动察觉6 语言 理解你会的语言 CR 无（XP0；PB等于你的熟练加值） 动作Actions 猛击Slam。近战攻击检定：加值等于你的法术攻击调整值，触及5尺。命中：1d4+3（中型）、2d6+3+你的施法调整值（大型）或2d12+3+你的施法调整值（巨型）的力场伤害。","duration":"专注，至多 1 分钟","higherLevels":{"kind":"升环施法","text":"使用五环或更高法术位施展该法术时，你使用的法术位每比五环高一环，活化物件生物的猛击Slam造成的伤害提升1d4（中型或更小）、1d6（大型）、1d12（巨型）。"},"id":"Animate_Objects","level":5,"nameEn":"Animate Objects","nameZh":"活化物件","range":"120 尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一道灵光从你身上延伸而出并在持续时间内形成10尺光环。这道灵光会阻绝外面除亡灵生物和构装生物之外所有类型的生物，使它们无法穿过或触及内部。一名受影响的生物施展的法术、使用远程武器或触及武器发动的攻击可以穿过屏障。\n若你移动迫使受影响生物进入护罩内，则法术随之终止。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Antilife_Shell","level":5,"nameEn":"Antilife Shell","nameZh":"防活物护罩","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"8 小时","classes":["吟游诗人","德鲁伊"],"components":{"material":true,"materials":"一块价值1000GP+的玛瑙，作为法术耗材","raw":"V、S、M（一块价值1000GP+的玛瑙，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你利用施法的时间引导一块昂贵宝石中的魔法回路，然后触碰目标。该目标必须是一个野兽或植物，且必须是一个智力小于等于3的生物或是一个并非生物的自然植物。\n目标的智力会变为 10，且学会说一门你所掌握的语言。如果目标是一株自然植物，则它变为一个植物生物，并且获得使用枝、根、藤、蔓或类似部位移动的能力，和类似于人类的感官。DM 为启蒙植物决定属性数据，例子可参考《怪物图鉴》中的启蒙灌木Awakened Shrub与启蒙树木Awakened Tree 。\n被启蒙的目标在 30 日内处于魅惑 状态，或是直到你或你的盟友做出任何伤害它的举动。魅惑终止后，启蒙生物自行决定对你的态度。","duration":"立即","higherLevels":null,"id":"Awaken","level":5,"nameEn":"Awaken","nameZh":"启蒙术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"附赠动作，当你使用近战武器或徒手打击命中一个生物后立即执行","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"被该次攻击检定命中的目标会在此次攻击中额外受到5d10力场伤害。如果此次攻击将目标的生命值削减到50点或更低，则目标必须进行一次魅力豁免，豁免失败则会在法术持续期间被转移到一个无害的半位面。身处半位面期间，目标会陷入失能状态。当法术终止时，目标将重新出现在其被放逐前的位置。如果该位置被占据，则目标将出现在距离该位置最近的一个未占据空间。","duration":"专注，至多1分钟","higherLevels":null,"id":"Banishing_Smite","level":5,"nameEn":"Banishing Smite","nameZh":"放逐斩","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一个蛋壳和一只分指手套","raw":"V、S、M（一个蛋壳和一只分指手套）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内一处你可见的未占据空间创造出一只闪烁着魔法性微光的大型手掌。这只手会在持续时间内维持存在，并听从你的命令进行移动，模仿你自己手掌的动作。\n这只手是一个具有AC20，生命值等于你的生命值上限的物件。若这只手的生命值降至0，则该法术终止。这只手不会占据其所在的空间。\n施展此法术时或在你随后的回合中以一个附赠动作，你可以令巨手移动至多60尺并造成下列效应之一：\n金刚拳Clenched Fist。这只手打击其5尺内的一名目标。发动一次近战法术攻击。命中则该目标受到5d8力场伤害。 飞击掌Forceful Hand。这只手尝试推撞其5尺内的一名体型不超过巨型的生物。目标必须成功通过一次力量豁免，否则这只手会将目标推动至多等于5+你施法属性调整值的五倍的尺数。这只手随目标一起移动，保持自己位于目标5尺内。 擒拿掌Grasping Hand。这只手尝试擒抱其5尺内的一名体型不超过巨型的生物。目标必须成功通过一次敏捷豁免，否则目标陷入受擒状态，逃脱DC等于你的法术豁免DC。在这只手擒抱目标期间，你能以附赠动作命令这只手挤压目标，对目标造成等于4d6+你的施法属性调整值的钝击伤害。 护身掌Interposing Hand。 这只手令你在对抗源自手所在空间或穿过手所在空间的攻击及其他效应时获得半身掩护。此外，这只手所在的空间对你的敌人视作困难地形。\n升环施法。使用的法术位每比五环高一环，金刚拳的伤害提高2d8，擒拿掌的伤害提高2d6。","duration":"专注，至多1分钟","higherLevels":null,"id":"Bigby's_Hand","level":5,"nameEn":"Bigby's Hand","nameZh":"毕格比之手","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士","法师","奇械师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"你在30尺光环区域内散发灵光。位于灵光范围期间，你和你的盟友为对抗法术和其他魔法效应而进行的豁免检定具有优势。当受该法术效应影响的生物对抗豁免成功受半数伤害的法术或魔法效应时，若其豁免成功则不受伤害。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Circle_of_Power","level":5,"nameEn":"Circle of Power","nameZh":"原力法阵","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"每名位于球状区域内的生物都进行一次体质豁免，豁免失败者受到5d8点毒素伤害，豁免成功则受到一半伤害。每当球状区域移动到一名生物区域内时、一名生物进入球状区域时或是在该区域结束其回合时，该生物同样需要进行一次豁免。一名生物一回合只需要进行一次该豁免。\n在你的每个回合开始时，球状区域会往远离你的方向移动10尺。","duration":"专注，至多 10 分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，此法术的伤害就增加1d8。"},"id":"Cloudkill","level":5,"nameEn":"Cloudkill","nameZh":"死云术","range":"120 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1 分钟或仪式","classes":["牧师"],"components":{"material":true,"materials":"焚香","raw":"V、S、M（焚香）","somatic":true,"verbal":true},"concentration":false,"description":"你与一名神明或一名神明的代理人进行联系，并询问至多三个能以“是”或“否”回答的问题。你必须在法术结束前完成提问。你会收到每个问题的正确答案。\n这些神能存在也并非全知全能，因此当问题涉及的信息超过神的认知范围时，你可能会得到一句“不清除”作为回答。另外当一个单词的回答可能引致误导或者与神的兴致相违背时，DM 可能会提供一句短语作为答案。\n若你在完成一次长休前施展两次或更多次的该法术，则法术有一定的几率不给任何答复。此概率从第二次施展起每次累计25％。","duration":"1 分钟","higherLevels":null,"id":"Commune","level":5,"nameEn":"Commune","nameZh":"通神术","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"1 分钟或仪式","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你与自然的灵魂沟通并以此获得周围环境的信息。在户外时，该法术可以让你了解3里内大地的状况。在洞穴和其他天然地下场所中，其范围缩小为300尺半径区域内。自然环境中被建筑覆盖的区域里（比如城堡或城镇中）法术无法生效。\n你立即获得的自然资讯至多与该地域三个方面的主题相关，在以下项目中进行选择：\n聚居地位置 通往其他位面的传送门位置 一个挑战等级10+的类型为天族、妖精、邪魔、元素或亡灵的生物（由DM选择）的位置 区域内最广泛分布的植物、矿物或动物（你选择得知其中一项） 水体的位置\n例如，你可以侦测到某个强大怪物在区域中的位置、水体位置以及附近城镇的方位。","duration":"立即","higherLevels":null,"id":"Commune_with_Nature","level":5,"nameEn":"Commune with Nature","nameZh":"问道自然","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一个小水晶或玻璃锥体","raw":"V、S、M（一个小水晶或玻璃锥体）","somatic":true,"verbal":true},"concentration":false,"description":"你释放出一团寒冷的空气。以你为源点的 60 尺锥状区域内的每名生物进行一次体质豁免。豁免失败受到 8d8 寒冷伤害，豁免成功则受到一半伤害。被该法术杀死的生物将成为一尊冰冻塑像直至其被解冻。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，法术伤害就增加1d8。"},"id":"Cone_of_Cold","level":5,"nameEn":"Cone of Cold","nameZh":"寒冰锥","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你将来自元素位面Elemental Planes的大型虚幻精魂咒唤在施法距离内一处未占据空间中。选择精魄的元素类别，这将决定它造成的伤害类型：气元素（闪电）、土元素（雷鸣）、火元素（火焰）或水元素（寒冷）。精魂在持续时间内一直存在。\n每当一名你可见的生物进入精魂所在的空间或是在精魂5尺内开始其回合时，若没有生物被精魂束缚，你可以迫使其进行一次敏捷豁免检定。失败则目标受到8d8对应精魂类型的伤害并且直到法术结束为止，目标陷入束缚状态。陷入束缚状态的目标回合开始时，其重新豁免，失败则目标受到4d8对应精魂类型的伤害，豁免成功则目标不再被精魂束缚。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，法术的伤害就增加1d8。"},"id":"Conjure_Elemental","level":5,"nameEn":"Conjure Elemental","nameZh":"咒唤元素","range":"60 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["游侠"],"components":{"material":true,"materials":"一把价值1+CP的近战或远程武器","raw":"V、S、M（一把价值1+CP的近战或远程武器）","somatic":true,"verbal":true},"concentration":false,"description":"你挥舞作为施法材料的武器并选择施法距离内一点。数以百计相似的幽灵武器（或是适合这把武器的弹药）齐射而出，并在之后消失。以那一点为中心，半径40尺、高20尺的柱状区域内的每名由你选择且你可见的生物进行一次敏捷豁免检定，豁免失败者将受到8d8力场伤害，豁免成功则只受一半伤害。","duration":"立即","higherLevels":null,"id":"Conjure_Volley","level":5,"nameEn":"Conjure Volley","nameZh":"万箭齐发","range":"150 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1 分钟或仪式","classes":["魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你与一名半神、一名古老贤者的亡魂或是其他位面的博学实体建立了精神的连接。与超越人智存在的连接可能会破坏你的心智。当你施展该法术时，进行一次 DC15 的智力豁免。豁免成功时，你可以询问该实体最多五个问题。你必须在法术结束前提出你的问题。DM 将以一个单词回答你的每个问题，例如“是Yes”、“不是No”、“可能Maybe”、“不可能Never”、“无关Irrelevant”或“不清楚Unclear”（意味着该实体不知道该问题的答案）。如果一个单词的答案会造成误解，DM可能会用一句短语作为答案。","duration":"1 分钟","higherLevels":null,"id":"Contact_Other_Plane","level":5,"nameEn":"Contact Other Plane","nameZh":"异界探知","range":"自身","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你的触碰会传染一道魔法疫病。目标必须成功通过一次体质豁免，否则受到11d8暗蚀伤害并陷入中毒状态。此外，当你施展法术时选择一项属性，目标在中毒期间进行所选属性的豁免检定时具有劣势。\n目标在其每回合结束时必须重新豁免，直至其累计三次成功或失败。若目标累计三次成功，则结束其身上该法术的效应。若目标累计三次失败，其身上该法术的效应持续7日。\n每当中毒目标受到能够结束其中毒状态的效应作用时，目标必须成功通过一次体质豁免，否则其陷入的中毒 状态不会结束。","duration":"7日","higherLevels":null,"id":"Contagion","level":5,"nameEn":"Contagion","nameZh":"疫病术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["术士","法师","奇械师"],"components":{"material":true,"materials":"一支画笔","raw":"V、S、M（一支画笔）","somatic":true,"verbal":true},"concentration":false,"description":"你从堕影冥界Shadowfell取来一些暗影物质，在施法距离内创造一个物件。你可以创造一个植物质（类似纺织品、绳索、木质等）物件，也可以创造一个矿物质（类似石质、水晶、金属等）物件。创造出来的物件大小必须不超过5尺立方区域，且其必须是一种你见过的形态与材质。\n法术的持续时间由所创造物件的材质决定，如材质表中所示。如果所创造物件由多种材质组合而成，则其持续时间取其中最短者。施展其他法术时，如果以这些创造物作为其材料成分将会使那道法术失败。\n材质Materials 材质 持续时间 植物 24小时 岩石或水晶 12小时 贵金属 1小时 宝石 10分钟 精金或秘银 1分钟\n升环施法。使用的法术位每比五环高一环，此法术的立方区域边长就增加5尺。","duration":"特殊","higherLevels":null,"id":"Creation","level":5,"nameEn":"Creation","nameZh":"造物术","range":"30尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["圣武士"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"毁灭能量从你身上扩散而出，覆盖了30尺光环范围。光环范围内你选择的每个生物进行一次体质豁免。豁免失败者受到5d6点雷鸣伤害和5d6点光耀或暗蚀伤害（由你选择）并且陷入倒地状态。豁免成功只受一半伤害。","duration":"立即","higherLevels":null,"id":"Destructive_Wave","level":5,"nameEn":"Destructive Wave","nameZh":"湮灭波","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":true,"materials":"银粉和铁粉","raw":"V、S、M（银粉和铁粉）","somatic":true,"verbal":true},"concentration":true,"description":"法术持续时间内，天族、元素、妖精、邪魔和亡灵对你的攻击检定具有劣势。你可以使用下述特殊功能之一以提前结束法术。\n破咒Break Enchantment。以一个魔法动作，你触碰一名因上述生物类型的任意生物而被其附身、陷入魅惑或恐慌状态的生物。目标不再被上述生物附身，魅惑或恐慌。驱离Dismissal。以一个魔法动作，你选择距你5尺内的一名你可见的生物，其生物类型必须是上述生物类型之一。目标必须成功于一次魅力豁免，否则，若其并未处于家园位面，则被遣送回其家园位面。对于亡灵和妖精，若它们并未处于家园位面，则亡灵会被遣送回堕影冥界Shadowfell，妖精则被遣送回妖精荒野Feywild。","duration":"专注，至多1分钟","higherLevels":null,"id":"Dispel_Evil_and_Good","level":5,"nameEn":"Dispel Evil and Good","nameZh":"驱逐善恶","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一名施法距离内你可见的类人生物必须成功于一次感知豁免，否则在持续时间内陷入魅惑状态。若你或你的盟友正在与其战斗，则目标在此豁免上具有优势。目标受到伤害时，可以重复进行该豁免，豁免成功则其身上的此法术终止。\n该目标被魅惑期间，只要你与其处于同一位面就可以与之保持心灵感应。在你的回合，你可以通过心灵感应命令该生物（无需动作），比如“攻击那个生物”“跑到那个位置”或是“去拿那个物品”。该生物会在其回合内尽其所能以遵守你的指令。目标完成一项指令却未收到你的进一步指示时，将会凭自身喜好行动，尽可能的保护自己。\n你可以用自己的反应去要求目标执行一项反应。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用更高环阶法术位施展时，你的专注能持续更长时间：六环至多10分钟，七环至多1小时，八环及以上至多8小时。"},"id":"Dominate_Person","level":5,"nameEn":"Dominate Person","nameZh":"支配类人","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","魔契师","法师"],"components":{"material":true,"materials":"一把沙子","raw":"V、S、M（一把沙子）","somatic":true,"verbal":true},"concentration":false,"description":"你指定一名你知道且与你同处一个存在位面的生物。你（或你触碰的一名自愿生物）将作为信使进入出神。出神下，信使陷入失能状态且速度降为0。\n如果目标正睡着，则信使可以在法术持续时间内出现在其梦中并在其沉睡期间与之交流。信使能够塑造梦中的环境，创造景观，物件和其他影像。信使可以随时结束出神状态，以此终止法术。目标在醒来后能清楚地记得其梦境的内容。\n如果你施法时目标醒着，则信使可以了解到这点。此时信使可以终止出神并结束法术，或是等待目标入睡再进入其梦境。\n你可以让信使以可怕的形象出现。但此时信使只能提供不超过十个单词的信息，随后目标必须成功通过一次感知豁免。豁免失败时，目标便无法从休息中获益，并在其醒来时受到3d6点心灵伤害。","duration":"8小时","higherLevels":null,"id":"Dream","level":5,"nameEn":"Dream","nameZh":"托梦术","range":"特殊","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":true,"materials":"一撮硫磺","raw":"V、S、M（一撮硫磺）","somatic":true,"verbal":true},"concentration":false,"description":"一支辉煌火焰的立柱从上方呼啸着降落。位于以施法范围内一点为中心，半径10尺、高40尺柱状区域内的每个生物必须进行一次敏捷豁免。豁免失败者将受到5d6点火焰伤害和5d6点光耀伤害，豁免成功则只受到一半伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，其火焰伤害和光耀伤害就均增加1d6。"},"id":"Flame_Strike","level":5,"nameEn":"Flame Strike","nameZh":"焰击术","range":"60尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","牧师","德鲁伊","圣武士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你对施法距离内你能看见的一个生物下达一条魔法口头命令，并强迫其执行相应的某种服务或克制某种行为，或者遵照你的要求行动。目标必须成功通过一次感知豁免，否则将在法术持续时间内陷入魅惑状态。目标不能理解你的命令，则其在豁免中自动成功。\n被魅惑生物每次做出与你的命令相悖的行为时，即受到5d10点心灵伤害。该伤害一日至多生效一次。\n除了涉及导致必死结果的行为外，你向目标下达的任何命令都会生效。如果你发布自杀指令则法术即时终止。","duration":"30日","higherLevels":{"kind":"升环施法","text":"使用七环或八环法术位施展该法术时，持续时间变为365日。使用九环法术位施展该法术时，法术将一直持续至被上文提及的法术所终止。"},"id":"Geas","level":5,"nameEn":"Geas","nameZh":"指使术","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊","圣武士","游侠","奇械师"],"components":{"material":true,"materials":"价值100GP+的钻石尘，作为法术耗材","raw":"V、S、M（价值100GP+的钻石尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名生物并魔法性地移除目标身上的下列效应之一：\n1级力竭 魅惑或石化状态 一道诅咒，包括目标因与一件被诅咒魔法物品的同调所陷入的诅咒。 目标某项属性值的减损 目标生命值上限的降低","duration":"立即","higherLevels":null,"id":"Greater_Restoration","level":5,"nameEn":"Greater Restoration","nameZh":"高等复原术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"24小时","classes":["牧师"],"components":{"material":true,"materials":"价值1000GP+的熏香，作为法术耗材","raw":"V、S、M（价值1000GP+的熏香，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一点并将神圣（或邪秽）的力量注入该点周围区域。区域半径至多 60 尺，若此区域内包含了已被另一个圣居影响的区域，则此次施法失败。受法术影响的区域具有以下效应。\n神圣防护 Hallowed Ward。选择以下任意生物类型：异怪、天族、元素、妖精、邪魔或亡灵。所选类型的生物不能自主进入该区域，任何被这些生物魅惑、恐慌或附身的生物只要在该区域内将不再被他们魅惑、恐慌或附身。\n额外效果Extra Effect。 你可以为该区域绑定下列其中一种额外效应，：\n无畏 Courage。你选择的任何类型的生物在该区域内时不会陷入恐慌状态。 黑暗 Darkness。区域内处于黑暗环境，普通光源以及比本法术更低环法术所创造的魔法光源均无法照亮该区域。 昼明Daylight。区域内处于明亮光照，比本法术更低环法术所创造的魔法黑暗无法掩盖亮光。 平静长眠 Peaceful Rest。区域内埋葬的尸体不能被转化成亡灵。 次元干涉Extradimensional Interference。你选择的任何类型的生物均不能通过传送或者位面旅行的方式进入或离开该区域。 恐惧Fear。你所选择的任何类型的生物在该区域内时陷入恐慌状态。 抗性Resistance。你所选择的任何类型的生物在该区域内时，对你所选择的一种伤害类型具有抗性。 沉默Silence。声音无法从区域内发出，区域外的声音也不能传到区域内。 巧言Tongues。你所选择的任何类型生物与区域内的任何其他生物即使语言不通也可以随意交流。 易伤Vulnerability。区域内你所选择的任何类型生物具有你所选择的一种伤害类型的易伤。","duration":"直至解除","higherLevels":null,"id":"Hallow","level":5,"nameEn":"Hallow","nameZh":"圣居","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"一片直的小铁片","raw":"V、S、M（一片直的小铁片）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内一个你能看见的生物。该目标必须进行一次感知豁免，豁免失败则其在法术持续时间内陷入麻痹状态。目标在其每回合结束时可以重新进行这次豁免，豁免成功则终止其身上该法术的效应。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，你就可以额外指定一个生物作为此法术的目标。"},"id":"Hold_Monster","level":5,"nameEn":"Hold Monster","nameZh":"定身怪物","range":"90尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士"],"components":{"material":true,"materials":"一只蝗虫","raw":"V、S、M（一只蝗虫）","somatic":true,"verbal":true},"concentration":true,"description":"你指定施法距离内一点，并以该点为中心使半径 20 尺球状区域内堆满成群的噬人蝗虫。虫群使整个区域成为困难地形并处于轻度遮蔽，在法术终止前都会持续存在。\n当虫群显现时，区域内的每个生物都必须进行一次体质豁免，豁免失败则受到4d10穿刺伤害，成功则受到半数伤害。生物在一个回合内第一次进入该区域内，或者在区域内结束其回合时，也必须进行该豁免。一名生物每回合仅需进行一次该豁免。\n升环施法。 使用六环或更高法术位施展该法术时，你使用的法术位每比五环高一环，伤害就增加1d10。","duration":"专注，至多10分钟","higherLevels":null,"id":"Insect_Plague","level":5,"nameEn":"Insect Plague","nameZh":"疫病虫群","range":"300尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":true,"materials":"一撮磷粉","raw":"V、S、M（一撮磷粉）","somatic":true,"verbal":true},"concentration":true,"description":"你以施法距离内你能看到的一点为中心，创造出一场闪光和雷鸣交织的风暴，席卷10尺半径、40尺高度的柱状区域。在这片区域内，生物会陷入目盲和耳聋状态，并且不能施展任何含有声音成分的法术。\n当风暴出现时，任何处于其中的生物都必须进行一次体质豁免，豁免失败则受到2d10点光耀伤害与2d10点雷鸣伤害，豁免成功受到半数伤害。生物在一个回合内首次进入该区域内，或者在区域内结束其回合时，也必须进行该豁免。一名生物每回合仅需进行一次该豁免。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，此法术的光耀和雷鸣伤害都会增加1d10。"},"id":"Jallarzi's_Storm_of_Radiance","level":5,"nameEn":"Jallarzi's Storm of Radiance","nameZh":"贾拉兹光辉风暴","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["吟游诗人","牧师","法师"],"components":{"material":true,"materials":"价值 250+GP 的熏香，作为法术耗材。以及每块价值 50+GP 的四块象牙板","raw":"V、S、M（价值 250+GP 的熏香，作为法术耗材。以及每块价值 50+GP 的四块象牙板）","somatic":true,"verbal":true},"concentration":false,"description":"点名或描述一个著名的人物，地点，或物件。该法术在你脑海中形成一段由DM描述的关于该事物重要传闻的简单概述。\n这些传闻可能包括了重要的细节，有趣的揭秘，也可能是不曾被广泛知晓的秘闻。你掌握目标越多的信息，所得到的信息就越精确细致。你由此得到的信息必定是准确的，但仍可能会以比喻或诗歌来表达，具体将由DM决定。\n如果你选的事物其实并不著名，你会听到仿佛由长号演奏而出的悲伤的音符，随后法术失败。","duration":"立即","higherLevels":null,"id":"Legend_Lore","level":5,"nameEn":"Legend Lore","nameZh":"通晓传奇","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一道治愈能量从施法距离内你指定的一点涤荡而出。你在该点周边30尺半径的球状区域内指定至多六个生物，并使每个目标生物恢复 5d8+你的施法属性调整值 点生命值。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比五环高一环，法术的治疗量就增加1d8。"},"id":"Mass_Cure_Wounds","level":5,"nameEn":"Mass Cure Wounds","nameZh":"群体疗伤术","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师","法师"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":true,"description":"你获得隐形状态，同时在你站的地方出现一个和你一样的幻象分身。分身会持续存在至法术持续时间结束；但如果你发动攻击、造成伤害或施展法术，则隐形随之结束。\n以一个魔法动作，你可以令分身以至多两倍于你的速度移动并可以令其打手势、说话，以及以任何你指定的方式行事。分身无法被触及且无法受伤。\n你可以通过分身的眼睛视物，用分身的耳朵聆听，如同你处于它的位置一样。","duration":"专注，至多1小时","higherLevels":null,"id":"Mislead","level":5,"nameEn":"Mislead","nameZh":"假象术","range":"自身","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你尝试重塑另一个生物的记忆。指定施法距离内一个你能看见的生物进行一次感知豁免。如果你正与该生物战斗，则它进行该豁免时具有优势。豁免失败时，该生物会在法术持续时间内陷入魅惑状态。被魅惑的目标陷入失能状态且无法感知周边的事物，但它仍然能听到你的声音。如果它受到任何伤害或者成为另一个法术的目标，则该法术终止且目标的记忆不会被修改。\n该魅惑持续时，你可以改变目标关于过去 24 小时内经历的一个持续时间不超过十分钟的事件记忆。你可以永久地消除所有关于该事件的记忆，也可以让目标完美清晰地回忆起该事件的所有细节，还可以改变目标关于该事件记忆细节，或是创造一段关于其他事情的记忆。\n你必须通过对目标说话来描述如何改变其记忆，并且目标必须能够听懂你的语言以便你植入被改变后的记忆。目标的意识会将你描述中所有缺失的细节填补完全。如果法术在你描述完被修改的记忆前就结束，则目标的记忆不会被改变。反之修改过的记忆会在法术终止时根植于目标心中。\n修改过的记忆不一定会影响生物的行为，特别是当修改后的记忆违背了目标的天性，阵营或信仰时。如果植入一段不合逻辑的记忆（例如给目标灌输它有多么享受在强酸中泡澡的记忆），则目标会将其视为一场噩梦而加以忽视。DM 也可以判定某段修改过的记忆太过荒谬，故而无法影响生物。\n升环施法。使用五环以上的法术位时，你可以改变目标关于过去 7 日内（六环）、30 日内（七环）、1 年内（八环）或者在过去任意时刻（九环）所发生事件的记忆。","duration":"专注，至多1分钟","higherLevels":null,"id":"Modify_Memory","level":5,"nameEn":"Modify Memory","nameZh":"篡改记忆","range":"30尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一撮芝麻","raw":"V、S、M（一撮芝麻）","somatic":true,"verbal":true},"concentration":false,"description":"一处通道在施法距离内木质、泥灰、或岩石表面（如墙壁、天花板、地板）上你可见的一点出现，且持续至法术结束。由你选择开口的大小，其至多宽5尺，高8尺，深20尺。通道不会使其周围的结构变得不稳定。\n开口消失时，任何仍旧位于通道中的生物或物件会被安全地弹射到距你施展此法术时选择的表面最近的一处未占据空间中。","duration":"1小时","higherLevels":null,"id":"Passwall","level":5,"nameEn":"Passwall","nameZh":"穿墙术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1小时","classes":["吟游诗人","牧师","德鲁伊","魔契师","法师"],"components":{"material":true,"materials":"一颗价值1000+GP的宝石，作为法术耗材","raw":"V、S、M（一颗价值1000+GP的宝石，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"一名被誓缚的生物必须尽其最大的努力遵循你的命令。你可能命令该生物在你冒险时陪伴你，或守卫一个地点，又或者传递一个信息。如果此生物与你敌对，则它会努力曲解你的字面意思来达到它自己的目标。如果生物在法术终止前完全执行了你的指示而你们仍处于同一位面，则它会当面向你汇报。如果你们处于不同位面，则它会回到与其建立誓约之地，并停留该处直至法术终止。","duration":"24小时","higherLevels":{"kind":"升环施法","text":"使用更高环法术位施展该法术时，法术持续时间增加：六环10日，七环30日，八环180日，九环366日。"},"id":"Planar_Binding","level":5,"nameEn":"Planar Binding","nameZh":"异界誓缚","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1小时","classes":["吟游诗人","牧师","圣武士"],"components":{"material":true,"materials":"一颗价值500+GP的钻石，作为法术耗材","raw":"V、S、M（一颗价值500+GP的钻石，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名已死，但死亡时间不超过10日，且死亡时并非亡灵Undead的生物，使其回生。\n生物以1点生命值重生。该法术同样会中和在该生物死亡时仍在生效的毒素。\n该法术能治愈所有致命伤，但无法恢复失去的身体部位。如果该生物缺失了它生存所必要的身体部位或器官（比如头），则该法术自动失败。\n死而复生是一个痛苦的体验。目标进行D20检定时具有-4减值。目标每完成一次长休，其减值就减少1，直至减值变为0。","duration":"立即","higherLevels":null,"id":"Raise_Dead","level":5,"nameEn":"Raise Dead","nameZh":"死者复活","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作或仪式","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"两颗蛋","raw":"V、S、M（两颗蛋）","somatic":true,"verbal":true},"concentration":false,"description":"你使得施法距离内你选择的至多八名自愿生物在法术持续时间内建立心灵连线。不能以任何语言进行沟通的生物不受该法术影响。\n直到法术终止，所有受术生物都可以通过心灵连线与其他受术生物进行心灵感应，不论他们是否语言相通。该交流方式可以跨越任意距离，但不能跨过存在位面。","duration":"1小时","higherLevels":null,"id":"Rary's_Telepathic_Bond","level":5,"nameEn":"Rary's Telepathic Bond","nameZh":"拉瑞心灵联结","range":"30尺","ritual":true,"school":"预言","source":"玩家手册2024"},{"castingTime":"1小时","classes":["德鲁伊"],"components":{"material":true,"materials":"价值1000GP+的珍稀油，作为法术耗材","raw":"V、S、M（价值1000GP+的珍稀油，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名类人生物的遗体或遗体的一部分。若该生物死亡时间不超过10日，则法术会创造出一具新的成年身体，并呼唤该生物的灵魂进入此新身躯。骰1d10，然后参照下表来决定新躯体的种族，或者DM也可以选择其他可选种族。\n1d10 种族 1d10 种族 1 阿斯莫 6 歌利亚 2 龙裔 7 半身人 3 矮人 8 人类 4 精灵 9 兽人 5 侏儒 10 提夫林\n若种族描述中提供了可选选项，则由被转生的生物做出选择，且其保留其前生记忆。目标保留原形的一切能力，不过其种族特质将以新种族的相应特质做更替。","duration":"立即","higherLevels":null,"id":"Reincarnate","level":5,"nameEn":"Reincarnate","nameZh":"转生术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"10 分钟","classes":["吟游诗人","牧师","德鲁伊","魔契师","法师"],"components":{"material":true,"materials":"一个价值1000GP+的聚焦镜，例如水晶球、银镜、装满水的圣水池之类的","raw":"V、S、M（一个价值1000GP+的聚焦镜，例如水晶球、银镜、装满水的圣水池之类的）","somatic":true,"verbal":true},"concentration":true,"description":"你能看见和听见一个和你处于同一存在位面上的生物。目标生物必须进行一次感知豁免；该豁免的调整值与你对目标的了解程度有关（见下文），也与你和目标之间的物理联系程度有关。目标不知道它进行此豁免在对抗什么，只是会感觉不自在。\n你对目标的了解有… 豁免调整值 你持有目标的… 豁免调整值 二手信息（你曾经听说过目标） +5 肖像或其他图像 -2 直接信息（你曾经见过目标） +0 衣物或其他物品 -4 熟悉（你对目标很了解） -5 身体部位如头发或指甲 -10\n如果对方豁免成功，则目标不受该法术影响，并且在 24 小时内你无法再次对其施展该法术。如果对方豁免失败，则你在目标身边 10 尺内创造出一个隐形且不具备实体的传感器。通过传感器，你可以身临其境地看见和听见周围的环境。传感器会跟随目标移动，并在法术持续时间内始终保持在目标 10 尺之内。在能够看到传感器的生物眼中，你的传感器是一个与你的拳头一般大小的光球。除生物之外，你也可以选择一个你以前见过的地点作为该法术的目标。这种情况下，传感器会出现在目标地点且不会移动。","duration":"专注，最多10分钟","higherLevels":null,"id":"Scrying","level":5,"nameEn":"Scrying","nameZh":"探知术","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你选择施法距离内你能看见的任意数量生物，为他们提供一个虚假外观。不愿意受该法术影响的目标可以进行一次魅力豁免，豁免成功则不受该法术影响。\n你可以为不同目标提供同样或不同的外观。法术能改变生物的身体和装备外观。你可以让目标看起来身高有 1 尺的增减，看上去更轻或更重。目标的新形貌的肢体结构必须与目标原形相符，但你可以随意改变其他的外观特征。法术会持续至时间结束。\n此法术产生的变化无法应对物理检查。比如，你用此法术为一个生物添了一顶帽子，那么现实物件会穿过帽子。\n一个使用研究动作来检查目标的生物可以进行一次智力（调查）检定来对抗你的法术豁免DC。如果它成功了，它会意识到目标进行了伪装。","duration":"8 小时","higherLevels":null,"id":"Seeming","level":5,"nameEn":"Seeming","nameZh":"伪装术","range":"30 尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["游侠","法师"],"components":{"material":true,"materials":"一把价值1SP+的近战武器","raw":"S、M（一把价值1SP+的近战武器）","somatic":true,"verbal":false},"concentration":false,"description":"你舞动用于施法的武器，随后忽然消失并如疾风般发起一轮突击。选择施法距离内最多5个你可见的生物。向每个生物分别进行一次近战法术攻击。若命中，目标将受到6d10点力场伤害。\n在这之后，你可以传送到法术目标之一周围5尺内一处你可以看见且未占据空间中。","duration":"立即","higherLevels":null,"id":"Steel_Wind_Strike","level":5,"nameEn":"Steel Wind Strike","nameZh":"钢风斩","range":"30尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","圣武士"],"components":{"material":true,"materials":"一个的金制圣物匣，价值500GP+","raw":"V, S, M（一个的金制圣物匣，价值500GP+）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个天界灵魄。其使用下文天界灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从复仇圣灵或守护圣灵选择一个，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n天界灵魄Celestial Spirit 大型天族，中立 AC 11+法术环阶+2（仅守护圣灵） HP 40+每比五环高一法术环阶10 速度 30尺，飞行40尺 调整豁免调整豁免调整豁免 力量16+3+3 敏捷14+2+2 体质16+3+3 智力10+0+0 感知14+2+2 魅力16+3+3 抗性 光耀 免疫 魅惑，恐慌 感官 黑暗视觉60尺，被动察觉12 语言 天界语，理解你的语言 CR 无（XP0；PB等于你的熟练加值） 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的攻击（向下取整）。 光耀之弓Radiant Bow（仅复仇圣灵）。远程攻击检定：加值等于你的法术攻击加值，射程600尺。命中：2d6+2+法术环阶的光耀伤害。 光耀之锤Radiant Mace（仅守护圣灵）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d10+3+法术环阶的光耀伤害，且灵魄可选择自己或其10尺内可见的另一生物，令其获得1d10临时生命值。 治愈之触Healing Touch（1/日）。灵魄触碰另一生物。目标魔法性地恢复2d8+法术环阶点生命值。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Celestial","level":5,"nameEn":"Summon Celestial","nameZh":"天界召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一件刻有巨龙图案的物品，价值500GP+","raw":"V, S, M（一件刻有巨龙图案的物品，价值500GP+）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个龙类灵魄。其使用下文巨龙灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n巨龙灵魄Draconic Spirit 大型龙类，中立 AC 14+法术环阶 HP 50+每比五环高一法术环阶10 速度 30尺，飞行60尺，游泳30尺 调整豁免调整豁免调整豁免 力量19+4+4 敏捷14+2+2 体质17+3+3 智力10+0+0 感知14+2+2 魅力14+2+2 抗性 强酸，寒冷，火焰，闪电，毒素 免疫 魅惑，恐慌，中毒 感官 盲视30尺，黑暗视觉60尺，被动察觉12 语言 龙语，理解你的语言 CR 无（XP0；PB等于你的熟练加值） 特质Traits 分享抗性Shared Resistances。当你召唤此灵魄时，选择一项其具有的伤害抗性。直至法术结束前，你也会获得所选伤害的抗性。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的撕裂攻击（向下取整），并使用其吐息武器。 撕裂Rend。近战攻击检定：加值等于你的法术攻击加值，触及10尺。命中：1d6+4+法术环阶的穿刺伤害。 吐息武器Breath Weapon。敏捷豁免：DC等于你的法术豁免DC，30尺锥状内的每个生物。失败：2d6点伤害（伤害类型由你在施法时从灵魄的伤害抗性中选择）。成功：半伤。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Dragon","level":5,"nameEn":"Summon Dragon","nameZh":"龙类召唤术","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["游侠"],"components":{"material":true,"materials":"一个价值1+GP的箭袋","raw":"V、S、M（一个价值1+GP的箭袋）","somatic":true,"verbal":true},"concentration":true,"description":"你施展该法术时，可以用一个射出箭矢或弩矢的武器（例如长弓和轻弩）进行两次攻击。随后，在法术结束前你能用附赠动作再次用这种武器发动两次攻击。法术会魔法性地为每次攻击生成所需的弹药。以此法生成的每发箭矢或弩矢如同类非魔法弹药一般造成伤害，且不论是否命中都会在攻击后立即瓦解。","duration":"专注，至多1分钟","higherLevels":null,"id":"Swift_Quiver","level":5,"nameEn":"Swift Quiver","nameZh":"迅捷箭袋","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"选择施法距离内的一点，你引爆其间的心灵能量。以那一点为中心，半径20尺球状区域内的每个生物进行一次智力豁免检定。豁免失败的生物受到8d6心灵伤害，成功则只受到一半伤害。\n豁免失败的目标还会在接下来的1分钟内思想混乱。在此期间，目标每次进行攻击检定、属性检定和为维持专注而进行体质豁免检定时都获得一枚d6的减值。在目标的每个回合结束时它都可以重新进行智力豁免检定，若成功将结束这个效应对自己的影响。","duration":"立即","higherLevels":null,"id":"Synaptic_Static","level":5,"nameEn":"Synaptic Static","nameZh":"突触静止","range":"120尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你获得以思想移动或操纵生物或物件的能力。当你施展该法术时或于该法术终止前，你在法术施展之后的回合中都可以用一个魔法动作，将你的意志强加于施法距离内你可见的一名生物或一个物件之上，并造成下述对应的效应。你可以一轮接一轮地影响同一个目标，也可以在任何时候选择一个新的目标。如果你改变了目标，则之前的目标将不再受该法术影响。\n生物Creature。你可以尝试移动一名巨型或更小的生物。目标必须成功于一次力量豁免，否则你可以在施法范围内将其往任意方向移动至多30尺。在你的下个回合结束前，该生物陷入束缚状态，而被你举到空中的生物会在半空中悬停。除非你再次对该被举到空中的生物使用此选项且其失败于豁免，否则其会在你的下个回合结束时坠落。物件Object。你可以尝试移动一个巨型或更小的物件。如果该物品没有被着装或携带，则你可以自动使它在施法范围内朝任何方向移动至多30尺。如果该物件已被一名生物着装或携带，则该生物必须成功于一次力量豁免，否则你可以把目标物件从该生物身上驱离，并且使该物体在施法范围内朝任意方向移动至多30尺。你可以使用心灵遥控对物件进行精密操作，例如操纵一件简单的工具，打开一扇门或一个容器，把东西放进或拿出一个打开的容器中，或是把一个小瓶子里的东西倒出来。","duration":"专注，至多10分钟","higherLevels":null,"id":"Telekinesis","level":5,"nameEn":"Telekinesis","nameZh":"心灵遥控","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":true,"materials":"价值50+GP的珍稀墨水，作为法术耗材","raw":"V、M（价值50+GP的珍稀墨水，作为法术耗材）","somatic":false,"verbal":true},"concentration":false,"description":"施展该法术时，你在地上画出一个半径5尺的圆圈，并在其周围画出印记。这个圆形法阵将你所处的位置与一个你所选择的，与你处在同个位面上的永久传送法阵相连（你必须知道该法阵的印记序列）。圆圈中将打开一个发光的传送门，并持续开启到你的下一回合结束。任何进入传送门的生物将立即出现在目标法阵附近5尺内，如果该空间已被占据，则出现在最靠近目标法阵的未占据空间中。\n许多大神殿、公会大厅和其他重要的场所都设有永久的传送法阵。这种法阵各有自己独一无二的印记序列，即按特定顺序排列的一串魔法符文。\n你第一次获得施展该法术的能力时，你会习得物质位面上两个永久法阵的印记序列（由DM决定），随后你还可以在旅途中习得更多的印记序列。你只要花一分钟仔细研究一个新的印记序列就能够将其记录下来。\n当你每日对同一地点连续施展该法术持续365天之后，将创造出一个永久的传送法阵。","duration":"1轮","higherLevels":null,"id":"Teleportation_Circle","level":5,"nameEn":"Teleportation Circle","nameZh":"传送法阵","range":"10尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","游侠"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你能够进入树木中，并从树木内部移动到距其500尺内的一棵同类树木内。两棵树必须都是活的，且其体型至少要和你一样。你进入一棵树时必须消耗5尺移动力。你将在进入树木后立即知道附近500尺内所有同类树木的位置，且作为进入树木所用移动的一部分，你可以移动到这些同类树木的其中一棵，或走出你所在的树木。你将出现在距作为目的地的树木5尺内你所选择的一点，并因此再消耗5尺移动力。如果你的移动力已经耗尽，则你将出现在距你进入的树木周围5尺内某处。\n在你的每个回合内，你仅能使用这样的转移能力一次。而且你必须在树外结束你的回合。","duration":"专注，至多1分钟","higherLevels":null,"id":"Tree_Stride","level":5,"nameEn":"Tree Stride","nameZh":"树跃术","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一块玻璃碎片","raw":"V、S、M（一块玻璃碎片）","somatic":true,"verbal":true},"concentration":true,"description":"由力场构成的隐形力场墙出现在施法距离内你指定的一点上。这面力场墙的朝向由你决定：你可以使力场墙成为水平或垂直的结界，亦可以使它形成一定倾角。它可以浮在空中，也可以立于某个坚固表面其上。你可以将它塑成半球状或球状（半径最长 10 尺），也可以塑成一个由十个 10 尺×10 尺的方板块构成的平面，而每块板块都必须要和至少一块其他板块相连。不管形状如何，力场墙的厚度总是 1/4 寸。力场墙将持续存在至法术终止。如果力场墙形成时穿过了某个生物所占据的空间，则该生物会被推到力场墙的一侧（由你来决定是哪一侧）。","duration":"专注，至多10分钟","higherLevels":null,"id":"Wall_of_Force","level":5,"nameEn":"Wall of Force","nameZh":"力场墙","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师","奇械师"],"components":{"material":true,"materials":"一块方形花岗岩","raw":"V、S、M（一块方形花岗岩）","somatic":true,"verbal":true},"concentration":true,"description":"一面坚硬的非魔法石墙出现在施法距离内你指定的一点。该石墙厚达6寸，由十个10×10尺的方板块组成。每块板块都必须要和至少一块其他板块相连。另外你也可以选择以十个 10×20 尺的板块组成石墙，但厚度只有3寸。\n如果石墙形成时穿过了某生物所占据的空间，则该生物会被推到石墙的一侧（由你决定推到哪一侧）。如果该生物即将被石墙完全包围住（或被石墙和另一个坚硬的平面包围），则它可以进行一次敏捷豁免。若豁免成功，则该生物可以执行一个反应来移动至多等于其速度的距离，从而避免被墙围住。\n你可以将石墙塑成你想要的任何形状，但它不能与其他生物或物件同占一处空间。该墙不必垂直于地面，也不需要地基；但它必须从稳固的既有石块中延伸出来。因此，你可以使用该法术创造一条跨越峡谷的桥或是造一个斜坡。\n如果你创造的跨度超过了20尺，你必须把每一块的大小减半来创造支撑。你可以对石墙进行粗略塑形，造出城垛等类似的东西。\n这个墙是一个可以因受到伤害而被打破的石制物件。每块板块的AC为15，且该板块每有1寸厚度就有30点生命值。其具有对毒素、心灵伤害的免疫。当一块板块的生命值降至0时则该板块被摧毁，而且与它相连的板块也可能会崩塌，具体由DM判断。\n如果你在整个法术持续时间内一直保持住该法术的专注，则石墙将永久存在且不能被解除。如果你没能这么做，则石墙在法术终止时随即消失。","duration":"专注，至多10分钟","higherLevels":null,"id":"Wall_of_Stone","level":5,"nameEn":"Wall of Stone","nameZh":"石墙术","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一顶微型皇冠","raw":"V、S、M（一顶微型皇冠）","somatic":true,"verbal":true},"concentration":true,"description":"你在自身周围散发出覆盖10尺光环区域的可怖威严，无论何时，当光环进入一名你可见的生物的占据空间，或是一名你可见的生物进入光环或是在光环之中结束自己的回合时，你都可以迫使这名生物进行一次感知豁免。豁免失败的生物将受到4d6点心灵伤害并陷入倒地状态，且你可以将其推离10尺。豁免成功的生物只受一半伤害。一名生物一回合只进行一次此豁免。","duration":"专注，至多1分钟","higherLevels":null,"id":"Yolande's_Regal_Presence","level":5,"nameEn":"Yolande's Regal Presence","nameZh":"悠兰德王者威仪","range":"自身","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你创造两个相连的传送门。指定地面上你能看见的两处未被占据的大型空间，其中一点在法术距离内，另一点则在你身边 10 尺内。随后将会开启一个通往两处的圆形传送门，并持续到法术结束。\n传送门边缘为闪烁的二维环形，其内布满遮挡视野的迷雾，且整个垂直地悬浮在离地几寸处。传送门单面开启（由你选择），那一面即是传送门生效的一面。\n任何进入其中一个传送门的东西将从另一个传送门里出现，如同两个传送门邻接一样。以一个附赠动作，你可以改变其开门的朝向。","duration":"专注，至多 10 分钟","higherLevels":null,"id":"Arcane_Gate","level":6,"nameEn":"Arcane Gate","nameZh":"秘法门","range":"500 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你创造出一面由旋转着的魔法能量剑刃组成的墙壁。墙壁在持续时间内在你的施法距离之内持续存在。你可以选择创造长不过100尺、高不过20尺、厚不过5尺的直墙；或是直径不过60尺、高不过20尺、厚不过5尺的环形墙。墙提供四分之三掩护，而墙体所占据的空间则视为困难地形。\n所有处于墙所占据空间的生物必须进行一次敏捷豁免，豁免失败者受到6d10力场伤害，成功则受到一半伤害。生物在进入墙所占据的空间或者在其中结束回合时也需要进行此豁免。一个生物每回合只会进行一次此豁免。","duration":"专注，至多10分钟","higherLevels":null,"id":"Blade_Barrier","level":6,"nameEn":"Blade Barrier","nameZh":"剑刃护壁","range":"90尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"三根银质别针","raw":"V、S、M（三根银质别针）","somatic":true,"verbal":true},"concentration":false,"description":"你放出一道闪电，射向施法距离内某个你能看见的指定目标。经过首个目标后，闪电分成三束跳向该目标30尺内至多3个其他目标。闪电的目标可以是生物或物件，但每束闪电必须指定不同的目标。\n每个目标必须进行一次敏捷豁免。豁免失败者将受到10d8点闪电伤害，豁免成功受到半数伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用高于六环的法术位施展该法术时，你使用的法术位每比六环高一环，跳跃后闪电就多分出一束射向一个不同的目标。"},"id":"Chain_Lightning","level":6,"nameEn":"Chain Lightning","nameZh":"连锁闪电","range":"150 尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":true,"materials":"价值500GP+的研磨黑珍珠粉末","raw":"V、S、M（价值500GP+的研磨黑珍珠粉末）","somatic":true,"verbal":true},"concentration":false,"description":"一阵负能量波从施法距离内你选择的一点放出，覆盖以该点为中心半径60尺球状区域。每个位于区域内的生物都进行一次体质豁免。豁免失败者受到8d8点暗蚀伤害，豁免成功则受到半数伤害。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，法术的伤害就增加2d8。"},"id":"Circle_of_Death","level":6,"nameEn":"Circle of Death","nameZh":"死亡法阵","range":"150尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你将来自妖精荒野的中型精魂咒唤在施法距离内一处你可见的未占据空间中。精魂在持续时间内一直存在，其外貌看起来像是一名你选择的妖精生物。当精魂显现时，你可以对位于精魂5尺内的一名生物进行一次近战法术攻击。命中则目标受到等于3d12加你施法属性调整值总和的心灵伤害，并且直到你的下个回合开始为止，目标处于恐慌状态，你和精魂均是目标的恐惧源。\n在后续的你的回合中，以一个附赠动作，你可以将精魂传送至一处位于其原位置30尺内的你可见的未占据空间，并对位于精魂5尺内的一名生物进行上述攻击。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，法术造成的伤害就增加1d12。"},"id":"Conjure_Fey","level":6,"nameEn":"Conjure Fey","nameZh":"咒唤妖精","range":"60 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["法师"],"components":{"material":true,"materials":"一尊价值1500+GP的饰宝石自塑像","raw":"V、S、M（一尊价值1500+GP的饰宝石自塑像）","somatic":true,"verbal":true},"concentration":false,"description":"凭依法术的效应在相应状况第一次出现时立即生效，而无论你是否想要这么做，在那之后触发术随即终止。\n凭依法术的效应只能作用于你，哪怕它通常可以指定其他目标也无法再作指定。你同一时间只能使用一道触发术。如果你再次施展该法术，则你身上前一道触发术的效应立即终止。另外，当触发术的材料成分不在你身上时，你身上的触发术效应也将立即终止。","duration":"10日","higherLevels":null,"id":"Contingency","level":6,"nameEn":"Contingency","nameZh":"触发术","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["牧师","魔契师","法师"],"components":{"material":true,"materials":"每具尸体一颗价值150+GP的缟玛瑙","raw":"V、S、M（每具尸体一颗价值150+GP的缟玛瑙）","somatic":true,"verbal":true},"concentration":false,"description":"你只能在夜晚施展这道法术。选择施法距离内至多三具中型或小型类人生物尸体。每具尸体都会变为一只你控制下的食尸鬼Ghoul（数据见《怪物手册》）。\n在每个你的回合用一个附赠动作，你能精神性地命令任何距你120尺内以此法术活化的生物（如果你操纵多个生物，则你的命令可以同时传达给它们中的任意成员，不过只能使用同一种命令）。你决定生物下回合使用何种动作并决定它们移动至何处，抑或你可以下达宽泛的命令，例如守护某个房间或某条走廊。没有接受到你命令的生物则只会采取回避 动作并只会为了避免受伤而移动。一旦被下达命令，该生物会持续执行命令直到任务完成。\n你只能操纵生物24小时，在那之后它会拒绝执行你曾下达的任何命令。若你在当前的24小时时间段终止前再次施展此法术，则你对该生物的操纵时间再延长24小时。法术的此种用法只能延长你对至多三个你使用此法术所创造生物的控制时间，不会造出新的生物。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用七环法术位施展该法术时，你可以唤起并维持四只食尸鬼。使用八环法术位施展该法术时，你可以唤起并维持五只食尸鬼，也可以改为唤起并维持两只妖鬼Ghast，或两只尸妖Wight。当你使用九环法术位施展该法术时，你可以唤起并维持六只食尸鬼，也可以改为唤起并维持三只妖鬼，或三只尸妖，或两只木乃伊Mummy。生物的数据均见《怪物手册》。"},"id":"Create_Undead","level":6,"nameEn":"Create Undead","nameZh":"唤起亡灵","range":"10尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一块天然磁石和灰尘","raw":"V、S、M（一块天然磁石和灰尘）","somatic":true,"verbal":true},"concentration":false,"description":"此法术会直接解离大型或更小的非魔法物件或魔法力场造物。如果目标是巨型或更大的物件或魔法力场造物，则此法术会解离其10尺立方大小的部分。\n升环施法。使用的法术位每比六环高一环，伤害就提高3d6。","duration":"立即","higherLevels":null,"id":"Disintegrate","level":6,"nameEn":"Disintegrate","nameZh":"解离术","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1分钟或仪式","classes":["法师"],"components":{"material":true,"materials":"一颗价值1000GP+的蓝宝石","raw":"V、S、M（一颗价值1000GP+的蓝宝石）","somatic":true,"verbal":true},"concentration":false,"description":"你触摸施展法术时使用的蓝宝石与一件最重不超过10磅，最长不超过6尺的物件。法术在物件上留下一个隐形的标记，也在蓝宝石上留下隐形的物件名称。你每次施展该法术时都必须使用不同的蓝宝石作为其材料成分。\n在那之后，你可以用一个魔法动作唤出该物件的名称并粉碎这颗蓝宝石，该物件将无视任何距离和位面的限制立即出现在你的手上，法术随即终止。\n如果另一个生物正持握或携带着该物件，则粉碎蓝宝石无法将该物品送过来。不过你会知晓是谁占有了该物品，以及其此刻身处何处。","duration":"直至被解除","higherLevels":null,"id":"Drawmij's_Instant_Summons","level":6,"nameEn":"Drawmij's Instant Summons","nameZh":"卓姆吉瞬间召唤","range":"触碰","ritual":true,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，你的眼睛变成漆黑虚空。一名你选择的，距离你60尺内且你可见的生物必须成功于进行一次感知豁免，否则将承受由你选择的下列效应之一直到法术结束。\n在法术终止前你的每个回合内，你都可以使用一个魔法动作来指定另一个目标。不过你不能指定那些已经通过本次施展的该法术豁免的生物。\n沉睡Asleep。目标陷入昏迷状态。其在受到任何伤害，或另一个生物使用一个动作摇晃它时，即可再次醒来。 惊慌Panicked。目标陷入恐慌状态，它必须在其每个自己的回合内执行疾走动作并移动，且以最短、最安全的路径尽可能的逃离你，直至其无路可逃为止。如果目标移至一处距你至少60尺远且看不见你的空间，则此效应终止。 患病Sickened。目标陷入中毒状态。","duration":"专注，至多1分钟","higherLevels":null,"id":"Eyebite","level":6,"nameEn":"Eyebite","nameZh":"摄心目光","range":"自身","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","牧师","德鲁伊"],"components":{"material":true,"materials":"一套价值100GP+的预言道具、如纸牌或符文","raw":"V、S、M（一套价值100GP+的预言道具、如纸牌或符文）","somatic":true,"verbal":true},"concentration":true,"description":"你魔法性地感知到通往你所陈述地点的最直接的物理路径。你必须熟悉你所描述的地点，如果你寻找的目的地在另一存在位面，或者其会不断移动（例如一座移动堡垒），或者描述不够具体（例如“一条绿龙的巢穴”），则该法术失效。\n你在法术持续时间内，只要和目的地在同一位面，就能够知晓目的地的远近和所在方向。向目的地移动并遇到岔路时，你会得知哪一条路能够最直接地通往目的地。","duration":"专注，至多1日","higherLevels":null,"id":"Find_the_Path","level":6,"nameEn":"Find the Path","nameZh":"寻路术","range":"自身","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一根鸡蛇兽羽毛","raw":"V、S、M（一根鸡蛇兽羽毛）","somatic":true,"verbal":true},"concentration":true,"description":"你尝试将施法距离内一名你可见的生物变为石头。目标必须进行一次体质豁免。若豁免失败，则目标在法术持续时间内陷入束缚状态。若豁免成功，则目标的速度直至你的下个回合开始前变为0。构装生物进行此豁免时自动成功。\n因该法术陷入束缚的生物必须在其每回合结束时再进行一次体质豁免。在累计三次豁免成功后，该法术终止。在累计三次豁免失败后，该生物被转化为石头并在法术持续时间内陷入石化状态。成功或失败的检定不需要连续；只要记录各情况的次数直至其中一方累计三次为止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Flesh_to_Stone","level":6,"nameEn":"Flesh to Stone","nameZh":"石化术","range":"60尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"10分钟或仪式","classes":["牧师"],"components":{"material":true,"materials":"价值1000GP+的红宝石尘","raw":"V、S、M（价值1000GP+的红宝石尘）","somatic":true,"verbal":true},"concentration":false,"description":"此外，该法术可以对你在施法时所选定类别的生物造成伤害。从下列选项中选择一项或多项：异怪、天族、元素、妖精、邪魔、亡灵。所选定生物在一个回合内首次进入法术区域或者在其内结束回合时，将受到5d10点光耀伤害或暗蚀伤害（由你在施法时选择其一）。\n施展该法术时，你可以设定一段密语。说出密语的生物即使进入区域也不会受到该法术的伤害。\n该法术的效应区域不能与另一道禁制术的区域相重叠。如果你对同一区域连续30日每日施展禁制术，则其效应会持续至被解除，并在最后一次施法时将该法术的材料成分消耗殆尽。","duration":"1日","higherLevels":null,"id":"Forbiddance","level":6,"nameEn":"Forbiddance","nameZh":"禁制术","range":"触碰","ritual":true,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一颗玻璃珠","raw":"V、S、M（一颗玻璃珠）","somatic":true,"verbal":true},"concentration":true,"description":"一道固定的微光屏障出现在你10尺光环区域的边缘上，并在法术持续时间内维持存在。\n任何在屏障外施展的五环或更低环阶的法术无法影响其内的任何东西。此类法术能够以屏障内的生物或物件为目标，但无法对其生效。同样的，屏障内区域也将被排除在此类法术所创造的效应区域之外。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，屏障能阻挡的法术就高一环。"},"id":"Globe_of_Invulnerability","level":6,"nameEn":"Globe of Invulnerability","nameZh":"法术无效结界","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1小时","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一根10+GP的银权杖","raw":"V、S、M（一根10+GP的银权杖）","somatic":true,"verbal":true},"concentration":false,"description":"你制造一个覆盖至多2500平方尺地面面积的受保护区域。保护区域至高可达20尺，并随你的意愿塑形为一个50尺的方形区域，或一百个相接的5尺方形区域，或二十五个相接的10尺方形区域。\n施展该法术时，你可以指明特定个体以让其不受法术效应的影响。你还可以指明一句口令，当在保护区域5尺内并大声说出口令时，即可让说出口令的人对这些效应免疫。\n过道Corridors。浓雾充斥受保护的过道使其处于重度遮蔽。此外，除你以外的生物在过道上遇到需要选择方向的岔路或交叉路口时，有50%概率误认错的方向为正确的前进方向。门Door。所有受保护区域内的门都被魔法性地锁住，如同被秘法锁Arcane Lock封上一般。此外，你还可以用一道幻象掩盖至多十扇门使其看起来有如普通墙面的一部分。楼梯Stairs。受保护区域内的楼梯从上到下布满了蛛网，如同受到蛛网术Web的效应一般。铜墙铁壁法术持续期间，这些蛛网即使被摧毁也可以在10分钟后再次生成。其他法术效应Other Spell Effect。你可以在要塞的保护区域内布置你指定的下列魔法效应之一： 在四条过道中布置舞光术Dancing Lights。你可以为光点其指定一个简单的程序，使其在铜墙铁壁持续期间重复此程序。 在两个地点布置魔嘴术Magic Mouth。 在两个地点布置臭云术Stinking Cloud（在铜墙铁壁法术持续期间，臭气即使被驱散也会在10分钟后重新聚集） 在一条过道或一个房间中布置一道造风术Gust of Wind（法术持续期间，风会一直吹） 在一个至多5尺的方形区域布置一道暗示术Suggestion。任何进入该区域的生物将通过精神受到法术的暗示。","duration":"24小时","higherLevels":null,"id":"Guards_and_Wards","level":6,"nameEn":"Guards and Wards","nameZh":"铜墙铁壁","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你对施法距离内一个你可见的生物降下恶毒致命的魔法。目标必须通过一次体质豁免，豁免失败将受到14d6点暗蚀伤害，并且它的生命值上限会降低等同它所受暗蚀伤害数值点。豁免成功则仅受到一半伤害。此法术不能将目标的生命值上限降至1以下。","duration":"立即","higherLevels":null,"id":"Harm","level":6,"nameEn":"Harm","nameZh":"重伤术","range":"60尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"1动作","classes":["牧师","德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"指定施法距离内一个你能看见的生物。汹涌澎湃的正能量将充盈该生物，使其恢复 70 点生命值。该法术也会终止正在影响目标的目盲、耳聋以及中毒状态。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，此法术的治疗量就增加10点。"},"id":"Heal","level":6,"nameEn":"Heal","nameZh":"医疗术","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["吟游诗人","牧师","德鲁伊"],"components":{"material":true,"materials":"一个价值1000GP+的镶饰宝石的碗，作为法术耗材","raw":"V、S、M（一个价值1000GP+的镶饰宝石的碗，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你咒唤一场盛宴出现在你周围地面上未被占据的10尺立方空间。盛宴需要1小时来享用，并会在这段时间结束后消失不见，而且下述增益效应在这1小时结束前不会生效。你可以让至多十二个生物一同分享盛宴。\n所有享用了大餐的生物都会获得几种增益。这些生物获得毒素伤害的抗性、中毒状态免疫与恐慌状态免疫，他们的生命值上限也将提高2d10点（并获得等量的生命值）。这些增益将持续 24 小时。","duration":"立即","higherLevels":null,"id":"Heroes'_Feast","level":6,"nameEn":"Heroes' Feast","nameZh":"英雄宴","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["法师"],"components":{"material":true,"materials":"一块宝石或水晶、或者一个圣物匣、其价值不能低于500GP","raw":"V、S、M（一块宝石或水晶、或者一个圣物匣、其价值不能低于500GP）","somatic":true,"verbal":true},"concentration":false,"description":"你的灵魂离开身体进入作为法术材料成分的容器中，而你的身体则陷入失神的状况。灵魂处于容器中时，你可以如同身处容器所在位置一样察觉周边。你不能移动，也不能使用反应，而此时你唯一能做的动作就是将你的灵魂投射出容器至多100 尺的距离，回到你仍活着的身体中去（并终止该法术），或者尝试占据另一个类人生物的身体。\n附身成功后，目标生物的身体将由你控制。你的生命值、生命骰、力量、敏捷、体质、速度和感官替换为目标生物的数据，此外将保留你的游戏数据。\n附身期间，被附身生物的灵魂可以用它自己的感官从容器内部观察外部，但它不能移动且陷入失能状态。\n附身于一具躯体时，如果容器处在你身边 100 尺内，则你可以用一个魔法动作从宿主的身体回到容器中，并让宿主的灵魂回到它自己的身体里。在你处于宿主的身体中时，如果宿主的身体死亡，则宿主生物死亡，且你必须进行一次对抗该法术豁免 DC 的魅力豁免。豁免成功且容器距你不超过 100 尺时，你回归容器内。否则你也随之死亡。\n如果容器被毁或者法术终止，则你的灵魂会立即回到你自己身体里。如果你在尝试回到自己身体时，身体距你超过 100 尺或者你的身体已死，则你也随之死亡。如果容器被毁时另一生物的灵魂在容器内，且该生物的身体仍然活着并距它不超过 100 尺，则其灵魂会回到身体里。否则该生物死亡。\n该法术终止时，其容器将随之被摧毁。","duration":"直到被解除","higherLevels":null,"id":"Magic_Jar","level":6,"nameEn":"Magic Jar","nameZh":"魔魂壶","range":"自身","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":true,"materials":"一条蛇的舌头","raw":"V、M（一条蛇的舌头）","somatic":false,"verbal":true},"concentration":false,"description":"你以魔法影响施法距离内至多十二个你能看见的生物，并对其施以某种行动暗示（至多以25个字的形式）。你指定的受术目标必须能听到并理解你的话语。你的暗示言辞必须是听起来可实现的，且不涉及任何伤害目标或其盟友的内容。例如，你可以说”沿那条路走到村子，并帮那儿的村民收庄稼直到日落。”或者你可以说“现在不是打架的时候。放下你们的武器，跳舞吧！跳上一个小时。”\n每个目标必须进行一次感知豁免，豁免失败者将陷入魅惑状态，直到法术持续时间结束为止，如果你或你的盟友对其造成伤害时此状态将提前结束。每个受魅惑的目标将尽其所能地从事你所暗示的行为。暗示的行为可能会在整个法术持续时间内持续进行；而如果你所暗示的活动可以用更短的时间完成，则在完成了活动的目标身上该法术提前终止。\n你也可以描述一种在持续时间内发生的特定状况，作为触发特殊行为的条件。例如，你可以暗示一队士兵将所有的钱交给他们遇到的第一个乞丐。如果在法术终止前条件始终没有满足，则指定的行为不会被执行。\n如果你或你同伴中的任何人伤害了一个被该法术影响的生物，则该法术对该生物产生的效应随之终止。","duration":"24小时","higherLevels":{"kind":"升环施法","text":"使用的法术位高于六环时，法术的持续时间增加，七环为10日，八环为30日，九环为366日。"},"id":"Mass_Suggestion","level":6,"nameEn":"Mass Suggestion","nameZh":"群体暗示术","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一个微缩模型的铲子","raw":"V、S、M（一个微缩模型的铲子）","somatic":true,"verbal":true},"concentration":true,"description":"指定施法距离内一处在任何方向上都不超过40 尺的地形区域，在法术持续时间内，你可以随意重塑区域内的泥土，沙土或黏土。你可以升高或降低区域内的地面高度，制造或填平一道沟渠，竖起或夷平一道屏障，或是形成一根立柱。上述任何改造的地形范围不得超过整个区域最大边长的一半。例如，如果你影响了 40 尺立方区域，则你可以创造一根至多20尺高的立柱，将地面升高或降低至多 20 尺，挖一条至多 20 尺深的壕沟，等等。这些改变一共需要花10分钟的时间来完成。由于地形的变化发生得很缓慢，区域内的生物通常不会被地面的移动困住或者受伤。\n每为法术维持10分钟专注，你都可以选择一片新的地形区域再施以影响。\n该法术无法改变天然的岩石或石制建筑。但石头和建筑仍会因适应地形的变化而被改变。如果你改变地形的方式会使得建筑不稳定，则它有可能倒塌。\n类似地，该法术也无法直接影响植物生长。而被移走的泥土会带走任何生长在其上的植物。","duration":"专注，至多2小时","higherLevels":null,"id":"Move_Earth","level":6,"nameEn":"Move Earth","nameZh":"地动术","range":"120尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一颗微缩水晶球","raw":"V、S、M（一颗微缩水晶球）","somatic":true,"verbal":true},"concentration":false,"description":"一颗冰球从你的指尖射向施法距离内你指定的一点，并在该处迸裂为一个半径60尺的球状区域。区域内的每个生物必须进行一次体质豁免。豁免失败者受到10d6点寒冷伤害，豁免成功则只受一半伤害。\n如果冰球击中某处水体，水面将在边长30尺的方形区域内凝结出6寸厚的坚冰。任何在其表面上游泳的生物将被冰面所困，陷入束缚状态。受困的生物可以用一个动作进行一次对抗你的法术豁免DC的力量（运动）检定以破冰挣脱。\n你可以在施法完毕后不发射冰球。此时你手上将出现一枚投石索子弹大小的触感冰冷的小冰球。你可以选择将冰球交给任意一名生物。持有冰球的生物可以将冰球投出去（射程至多为40尺）或者用投石索将其弹射出去（射程至多为投石索的常规射程）。冰球将在撞击时破碎，产生与正常施法时相同的效应。你还可以将冰球放下而不直接打破它。冰球若在1分钟后仍未被打破，它将自动爆炸。","duration":"立即","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，其伤害就增加1d6。"},"id":"Otiluke's_Freezing_Sphere","level":6,"nameEn":"Otiluke's Freezing Sphere","nameZh":"欧提路克冰封法球","range":"300尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":true,"description":"一名施法距离内你可见的生物必须进行一次感知豁免，豁免成功则目标直到其下个回合结束为止会跳起滑稽的舞蹈，在此期间其必须消耗所有的移动力在原地跳舞。\n若豁免失败，目标将在法术持续时间内陷入魅惑状态。处于魅惑状态期间，目标会跳起滑稽的舞蹈，必须使用所有的移动力在原地跳舞，并且进行的敏捷豁免与攻击检定具有劣势，且其他生物以该生物为目标发动的攻击检定具有优势。在目标的每个自己的回合，它可以用一个动作尝试使自己镇定下来并重复豁免，豁免成功则其身上的法术终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Otto's_Irresistible_Dance","level":6,"nameEn":"Otto's Irresistible Dance","nameZh":"奥图迷舞","range":"30尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你祈求一名异界实体的援助。你必须对该存在有所了解，它可以是一位神祇，一名恶魔主君，或是其他拥有宇宙级伟力的存在。该实体将派遣一名效忠它的天族生物，元素生物或邪魔生物来援助你，并使该生物显现在施法距离内一处未占空间。如果你知道某个特定生物的名字，则你可以在施展法术时说出其名字来请求指派该生物来援，但是你仍然有可能得到一名不同的生物（由DM选择）。\n该生物出现时，它并未被强迫做任何事。你可以用报酬为交换，请求其提供服务，但它并没有为你实现请求的义务。请求的任务可以简单（帮我们飞越峡谷，或协助我们进行一场战斗），也可以复杂（暗中监视我们的敌人，或在我们扫荡地城时保护我们）。你必须能与该生物交流从而为其服务讨价还价。\n报酬的形式各式各样。一名天族可能会要求为一座同盟的神殿捐献一份相当可观的金币或魔法物品，而一只邪魔可能会索要一次活祭或一份财宝作为礼物。一些生物可能会要求你进行一个任务来换取它们的服务。\n一个可以按分钟计算的任务需要每分钟100GP的报酬。一个可以按小时计算的任务需要每小时1000GP的报酬。一个可以按日计算的任务（至多10日）需要每日10000GP 的报酬。DM可以按你施展该法术时的具体情况调整报酬。如果任务与生物的行为准则一致，则其可能只会索取一半报酬甚至不收取报酬。没有风险的任务一般只需要建议报酬的一半，而特别危险的任务可能会需要更大的赠礼。生物极少接受看上去像自杀的任务。\n生物完成任务后，或当提前商定的服务时间结束后，生物会在情况允许时回来向你报告，然后再返回自己的家乡位面。如果你不能就生物的服务价格与之达成共识，该生物将立即返回其家乡位面。","duration":"立即","higherLevels":null,"id":"Planar_Ally","level":6,"nameEn":"Planar Ally","nameZh":"异界誓盟","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"价值25GP+的玉粉","raw":"V、S、M（价值25GP+的玉粉）","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内创造一个物件，一名生物，或是其他可视现象的幻象，此幻象在满足特定触发条件时会被激活。该幻象在被激活前无法被察觉。幻象必须不大于30尺立方，且由你决定幻术如何行动和发声。这种按脚本执行的表演可以持续至多5分钟。\n当你指定的触发条件发生时，幻象会迅速成型，并以你设定的方式运作。幻术终止运作之后，它消失并休眠10分钟，在休眠结束之后幻象便可再次被激活。\n触发条件可以宽泛也可以按你喜好进行细化，但必须是发生在距幻象区域30尺内的能看到或听到的现象。例如，你可以制造一个自己的幻象，在其他人试图打开一扇卡住的门时出现并发出警告。\n由于东西可以穿过幻象，任何与该幻象进行的物理互动都会暴露其幻觉本质。一名生物可以用一个研究动作进行一次对抗你法术豁免DC的成功智力（调查）检定以看穿幻象。辨出幻象的生物可以看穿该影像，其产生的声响对该生物而言显得虚假。","duration":"直至被解除","higherLevels":null,"id":"Programmed_Illusion","level":6,"nameEn":"Programmed Illusion","nameZh":"预置幻象","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":true,"materials":"一小瓶价值600GP+的血","raw":"V, S, M（一小瓶价值600GP+的血）","somatic":true,"verbal":true},"concentration":true,"description":"你唤来一个邪魔灵魄。其使用下文邪魔灵魄的数据，并会在施法距离内一处你可见的未占据空间中显现。当你施展法术时，从魔鬼，恶魔，尤格罗斯魔中选择一类，该生物会显现为你所选的那类邪魔中的一员，其数据中的部分特性也受此影响。该生物会在生命值降为0或是法术结束时消失。\n该生物是你的盟友（对你的其他盟友亦是如此）。它在战斗中使用你的先攻，并在你回合结束后立即行动。它遵从于你的口头指令（无需任何动作）。如果你不发令，它将执行回避动作并用移动力远离危险。\n邪魔灵魄Fiendish Spirit 大型邪魔，中立 AC 12+法术环阶 HP 50（仅恶魔）或40（仅魔鬼）或60（仅尤格罗斯魔）+每比六环高一法术环阶15 速度 40尺；攀爬40尺（仅恶魔）；飞行60尺（仅魔鬼） 调整豁免调整豁免调整豁免 力量13+1+1 敏捷16+3+3 体质15+2+2 智力10+0+0 感知10+0+0 魅力16+3+3 抗性 火焰 免疫 毒素；中毒 感官 黑暗视觉60尺，被动察觉10 语言 深渊语，炼狱语，心灵感应60尺 CR 无（XP0；PB等于你的熟练加值） 特质Traits 焚身爆Death Throes（仅恶魔）。当灵魄生命值降至0或法术结束时，灵魄爆炸。敏捷豁免：DC等于你的法术豁免DC，源自灵魄的10尺光环区域内的每名生物。失败：2d10+法术环阶的火焰伤害。成功：半伤。 魔鬼视界Devil‘s Sight（仅魔鬼）。魔法黑暗不会阻碍灵魄的黑暗视觉。 魔法抗性Magical Resistance。灵魄对抗法术和其他魔法效应时进行的豁免检定具有优势。 动作Actions 多重攻击Multiattack。灵魄发动等于法术环阶一半次数的攻击（向下取整）。 啃咬Bite（仅恶魔）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d12+3+法术环阶的暗蚀伤害。 爪击Claws（仅尤格罗斯魔）。近战攻击检定：加值等于你的法术攻击加值，触及5尺。命中：1d8+3+法术环阶的挥砍伤害。无论是否命中，攻击后灵魄可以立即传送至多30尺至一处其可见的未占据空间。 狂焰袭Fiery Strike（仅魔鬼）。近战或远程攻击：加值等于你的法术攻击加值，触及5尺或射程150尺。命中：2d6+3+法术环阶的火焰伤害。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"该生物的数据使用新的法术环阶。"},"id":"Summon_Fiend","level":6,"nameEn":"Summon Fiend","nameZh":"邪魔召唤术","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士","法师"],"components":{"material":true,"materials":"一面放大镜","raw":"V、S、M（一面放大镜）","somatic":true,"verbal":true},"concentration":true,"description":"一道阳炎射线从你手中射出并形成一条5尺宽、60尺长的线状区域。所有区域内的生物必须进行一次体质豁免。豁免失败者将受到6d8点光耀伤害，并且在你的下一回合前陷入目盲状态。豁免成功则伤害减半，且不会陷入目盲。\n你可以在法术终止前的任一回合内以一个魔法动作重新创造一道线状光芒。\n在法术持续时间内，你的手中一点散发出耀眼的光芒。其光耀为周围提供 30 尺的明亮光照，以及该范围外 30 尺的微光光照。这些光芒均视为等同于阳光。","duration":"专注，至多1分钟","higherLevels":null,"id":"Sunbeam","level":6,"nameEn":"Sunbeam","nameZh":"阳炎射线","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":true,"materials":"一支价值500GP+的镀金长柄勺","raw":"V、S、M（一支价值500GP+的镀金长柄勺）","somatic":true,"verbal":true},"concentration":false,"description":"你咒唤一口充满冒泡液体的爪足大锅。大锅出现在距你5尺内地面上的一处未占空间内且持续存在至法术终止。大锅不能被移动，且在法术结束时与其内的冒泡液体一同消失。\n从大锅中取出的药水若在你再次施展此法术时未被消耗，则药水会消失。","duration":"10分钟","higherLevels":null,"id":"Tasha's_Bubbling_Cauldron","level":6,"nameEn":"Tasha's Bubbling Cauldron","nameZh":"塔莎泡泡坩埚","range":"5尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"该法术在施法距离内一棵体型至少为大型的未活化植物与同位面上任意距离外的另一棵植物之间创造一道魔法连接。施法时，你必须见过或触碰过出口植物至少一次。在持续时间内，任何生物都可以花费5尺移动力进入目标植物内，然后从出口植物处出来。","duration":"1分钟","higherLevels":null,"id":"Transport_via_Plants","level":6,"nameEn":"Transport via Plants","nameZh":"木遁术","range":"10尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","术士","魔契师","法师"],"components":{"material":true,"materials":"价值25GP+的蘑菇粉，作为法术耗材","raw":"V、S、M（价值25GP+的蘑菇粉，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"法术持续时间内，你触碰的自愿生物具有120尺真实视觉。","duration":"1小时","higherLevels":null,"id":"True_Seeing","level":6,"nameEn":"True Seeing","nameZh":"真知术","range":"触碰","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一块石英","raw":"V、S、M（一块石英）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内一块坚实的地面上创造出一面冰墙。你可以将它塑成半球状或球状（半径最长10尺），也可以塑成一个由十个10尺×10尺的方板块构成的平面。每块板块都必须要和至少一块其他板块相连。不管形状如何，冰墙总是厚1尺并持续存在至法术终止。\n如果冰墙形成时穿过了某生物所占据的空间，则该生物会被推到冰墙的一侧（由你来决定是哪一侧）且必须进行一次敏捷豁免。豁免失败，受到10d6点寒冷伤害。豁免成功，则只受一半伤害。\n作为一个物件，冰墙可以因受到伤害而被打破。冰墙的AC为12，每段10尺长的冰墙有30点生命值，而且冰墙具有寒冷、毒素和心灵伤害的免疫，以及火焰伤害的易伤。当一段10尺长的冰墙的生命值降至0时，这段冰墙就会被摧毁，但原地会留下一片冰冷刺骨的空气。\n生物在一个回合内第一次通过这片寒气时，必须进行一次体质豁免。豁免失败，受到5d6点寒冷伤害。豁免成功，则只受一半伤害。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，冰墙产生时造成的伤害就提高2d6，穿越冰冷刺骨的空气造成的伤害就增加1d6。"},"id":"Wall_of_Ice","level":6,"nameEn":"Wall of Ice","nameZh":"冰墙术","range":"120尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":true,"materials":"一把荆棘","raw":"V、S、M（一把荆棘）","somatic":true,"verbal":true},"concentration":true,"description":"你创造出一面坚韧、纠缠、长满锐利棘刺的灌木之墙。棘墙出现在施法距离内一处固体表面上并且持续存在至法术终止。你可以选择创造长不过60尺、高不过10尺、厚不过5尺的直墙；或是直径不过20尺、高不过20尺、厚不过5尺的环形墙。此外，棘墙还会阻挡视线。\n棘墙出现时所有位于其内的生物要进行一次敏捷豁免。豁免失败，受到7d8点穿刺伤害。豁免成功，则只受一半伤害。\n生物可以移动穿过棘墙，但这是个十分缓慢且痛苦的过程。生物在棘墙中每移动 1 尺要消耗 4 尺的移动力。另外，生物在一个回合内首次进入棘墙或在棘墙所占据的区域内结束其回合时，必须进行一次敏捷豁免。豁免失败，受到7d8点挥砍伤害。豁免成功，则只受一半伤害。一名生物一回合只进行一次此豁免。","duration":"专注，至多10分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比六环高一环，造成的伤害就提高1d8。"},"id":"Wall_of_Thorns","level":6,"nameEn":"Wall of Thorns","nameZh":"棘墙术","range":"120尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["德鲁伊"],"components":{"material":true,"materials":"一根蜡烛","raw":"V、S、M（一根蜡烛）","somatic":true,"verbal":true},"concentration":false,"description":"你和施法距离内你能看见的至多十个自愿生物在法术持续时间内变为气化形态，其外观有如一团云雾。处于该云雾形态的生物具有 300 尺的飞行速度且能够悬浮，免疫倒地状态，并且具有钝击、挥砍、穿刺伤害的抗性。该形态下的生物除疾走和使用魔法动作变回原形以外不能执行其他动作。变回原形需要花1分钟的时间，在这段时间内该生物处于震慑状态。在法术终止前，该生物还可以再次变成云雾形态，而再次使用魔法 动作进行变形同样要花1分钟时间。\n如果法术终止时受术目标正以云雾形态飞行，则该目标将在1分钟内以每轮60尺的速度降落直至安全着陆。如果该生物降落1分钟后还没着陆，则在余下的距离中它将会如正常情况一样坠落。","duration":"8小时","higherLevels":null,"id":"Wind_Walk","level":6,"nameEn":"Wind Walk","nameZh":"御风而行","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你和你身边5尺内的至多五个自愿生物一起瞬间传送到一个你事先设置好的圣殿。你和与你一起传送的生物将出现在你准备圣殿时指定的地点（见下）旁边最近的未被占据位置。如果你在施展法术前没有事先准备好圣殿，则该法术将不产生任何效应。\n你必须指定一处地方（例如一座寺庙），在那里施展法术以将其设为圣殿。","duration":"立即","higherLevels":null,"id":"Word_of_Recall","level":6,"nameEn":"Word of Recall","nameZh":"回返真言","range":"5尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你将来自上层位面的精魂咒唤，精魂表现为照耀以施法距离内一点为中心半径10尺、高40尺的柱状区域的光之立柱。对位于柱状区域内的你可见的生物，分别选择下列哪种光芒照耀于它。\n治愈之光Healing Light。目标恢复等于 4d12+你的施法属性调整值的生命值。惩戒之光Searing Light。目标进行一次敏捷豁免检定，豁免失败者将受到6d12光耀伤害，豁免成功则只受一半伤害。\n直到法术结束为止，柱状区域内处于明亮光照，并且当你在你的回合移动时，你可以令柱状区域也移动至多30尺每当柱状区域在移动中进入了一名你可见的生物区域内时、一名你可见的生物进入柱状区域或是在该区域结束其回合时，你都可以令该生物沐浴其中一种光芒。一名生物一回合只能被该法术影响一次。升环施法。使用的法术位每比七环高一环，法术产生的治疗和造成的伤害就增加1d12。","duration":"专注，至多10分钟","higherLevels":null,"id":"Conjure_Celestial","level":7,"nameEn":"Conjure Celestial","nameZh":"咒唤圣光","range":"90 尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":true,"materials":"一颗蝙蝠粪和硫磺搓成的小球","raw":"V、S、M（一颗蝙蝠粪和硫磺搓成的小球）","somatic":true,"verbal":true},"concentration":true,"description":"一束黄光从你的指尖射向施法距离内你指定的一点，并在法术持续时间内在该点凝结成一颗珠子。法术终止时，珠子将伴着低吼炸裂成四窜的烈焰，位于目标点半径20尺球状区域内的每名生物都必须进行一次敏捷豁免。豁免失败者将承受全部累积的火焰伤害，豁免成功则只受到一半伤害。\n该法术的基础伤害为12d6，且若在你回合结束时法术尚未终止，则其伤害增加1d6。\n如果法术终止前红炽的珠子被生物触碰到，则该生物必须进行一次敏捷豁免。豁免失败则法术立即终止并触发爆炸效应。豁免成功则该生物可将珠子投掷至多40尺。如果这颗被投掷出去的珠子进入生物占据空间或撞击固态物件，法术立即终止并且触发爆炸效应。","duration":"专注，至多1分钟","higherLevels":{"kind":"升环施法","text":"使用的法术位每比七环高一环，基础伤害就提高1d6。"},"id":"Delayed_Blast_Fireball","level":7,"nameEn":"Delayed Blast Fireball","nameZh":"延迟爆裂火球","range":"150尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"附赠动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"圣言效应Divine Word Effects 生命值 效应 0~20 目标死亡。 21~30 目标陷入目盲、耳聋、震慑状态，持续1小时。 31~40 目标陷入目盲、耳聋状态，持续10分钟。 41~50 目标陷入耳聋状态，持续1分钟。","duration":"立即","higherLevels":null,"id":"Divine_Word","level":7,"nameEn":"Divine Word","nameZh":"圣言术","range":"30尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你进入当前所处位面与以太位面Ethereal Plane边缘的重叠空间。你在法术持续时间内一直呆在该以太边界Border Ethereal 。在此期间，你可以向任意方向移动。如果你向上或向下移动，则你移动的每尺距离需要额外消耗一尺的移动力。你可以观察原位面，但是所有事物都以灰度显示，而你也看不到60尺外的东西。\n处于以太位面期间，只有同样处在以太位面的其他生物、物件和效应才能被你影响或影响你。不在以太位面的生物无法察觉你，也无法与你互动，除非有一项特性允许他们这么做。\n法术终止时，你立刻回到原本所在的位面中与以太边界中你所处位置相对应的空间位置。若你出现于一处被占空间，则你立刻被弹到最靠近的一处未占空间中，并受到两倍于你因此被移动尺数点的力场伤害。\n如果你在施展法术时正处于以太位面，或所在位面与以太位面不相连（比如某个外层位面Outer Plane ），则法术立即结束。","duration":"8小时","higherLevels":{"kind":"升环施法","text":"使用八环施展此法术时，你可以指定至多三名自愿生物（包括你在内）；使用九环时，你可以指定至多六名自愿生物（包括你在内）。所有所选生物在你施法时必须距你10尺内。"},"id":"Etherealness","level":7,"nameEn":"Etherealness","nameZh":"以太化","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你向施法距离内的一个可见生物释放负能量。该生物必须进行一次体质豁免。豁免失败则受到7d8+30点暗蚀伤害，豁免成功则伤害减半。\n被该法术杀死的类人生物将在你下一回合开始时被唤起为一只受你操控的丧尸Zombie（见附录B），并在随后尽力遵循你的口头指令。","duration":"立即","higherLevels":null,"id":"Finger_of_Death","level":7,"nameEn":"Finger of Death","nameZh":"死亡一指","range":"60尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"一片烈焰风暴出现在施法距离内。风暴的区域由至多十个10尺立方区域组成。你可以自行安排各立方区域的组合方式。每个立方区域必须至少与一个其他的立方区域相连。区域内每个生物必须进行一次敏捷豁免。豁免失败者将受到7d10点火焰伤害，豁免成功则伤害减半。\n区域内所有未被着装或携带的可燃物件会开始燃烧。","duration":"立即","higherLevels":null,"id":"Fire_Storm","level":7,"nameEn":"Fire Storm","nameZh":"火焰风暴","range":"150尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师","法师"],"components":{"material":true,"materials":"价值1500GP+的红宝石尘，作为法术耗材","raw":"V、S、M（价值1500GP+的红宝石尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":true,"description":"你围绕施法距离内一处指定地点力场构筑出一个固定的立方状隐形Invisible监牢。你可以选择监牢的形式为笼状或盒状。\n笼状监牢为各边长至多20尺的立方体，其墙体由1/2寸粗的力场栅栏杆组成，每根杆子之间相距1/2寸。盒状监牢为各边长至多10尺的立方体，其墙体为由力场墙密封，并阻隔一切物质进出，也会阻挡任何从区域中向外界施展或从外界向区域中施展的法术。\n施展该法术时，所有完全在法术区域内的生物将被牢笼困住。部分处于区域内或者体型比区域更大的生物则被从区域中心向外推开，直至其完全离开该区域。\n牢笼内的生物不能以非魔法的手段离开。如果该生物试图使用传送或跨位面旅行来离开牢笼，则其必须先进行一次魅力豁免。豁免成功则该生物可以用该魔法离开牢笼。豁免失败者将无法以此离开牢笼并浪费掉该法术或效应。该牢笼同时延伸至以太位面Ethereal Plane 从而屏蔽途经以太位面的旅行。","duration":"专注，至多1小时","higherLevels":null,"id":"Forcecage","level":7,"nameEn":"Forcecage","nameZh":"力场监牢","range":"100尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["吟游诗人","德鲁伊","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"你使至多 1 里方形区域内的地形在视觉、听觉、嗅觉、甚至触觉上都像是某种其他的地形，不过其地形的大致形状仍保持不变。你可以让开阔的平原或者一条路可能变得像一片湿地，一座小山，一个裂谷或是其他困难或无法通行的地形。你还可以让一个池塘变得像一片茂盛的草地，一个悬崖变得像一个缓坡，或者让一个乱石沟变得像一条宽阔平坦的大路。\n另外，你还可以改变建筑物的外观，或者在本来没有建筑物的地方添上建筑物。该法术不可以伪装、隐藏或增添生物。\n该幻术是听觉、视觉、触觉和嗅觉的综合体，因而其可以把空旷的地面变成困难地形（反之亦然），乃至阻碍区域内的通行。幻象地形的任何一小部分（例如一块石头或者一根树枝）被移动到法术区域外时都会立刻消失不见。\n拥有真实视觉的生物可以看穿幻术，洞悉地形的真实形态；然而幻象的所有其他元素仍会得以保留，所以一个意识到这是幻象的生物仍然可以与该幻象进行物理互动。","duration":"10日","higherLevels":null,"id":"Mirage_Arcane","level":7,"nameEn":"Mirage Arcane","nameZh":"海市蜃楼","range":"视野","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一个价值15GP+的微缩模型门","raw":"V、S、M（一个价值15GP+的微缩模型门）","somatic":true,"verbal":true},"concentration":false,"description":"你在施法距离内召唤一扇微微发光的门，并维持至法术持续时间结束。门宽5尺，高10尺，指向一个异次元居所。只要该门保持开启，你和你施展该法术时指定的任意生物都可以进入该异次元居所中。你可以在距该门不超过 30 尺处开启或关闭之（无需动作）。门在关闭状态下其无法被发现。\n门的另一侧是一个连接着众多房间的华丽大厅。整个居所的空气洁净清新而温暖舒适。\n你可以随意创造自己喜欢的房间构造，但不得超出50个相连的边长10尺的立方体。空间内依你喜好配置好家具和装饰，其内储备的食材足以制作供至多100人享用的九菜大宴。由该法术创造的家具和其他物品如果被移出豪宅，就会化作烟雾消散。\n一组共100名的近乎透明的仆从会招待任何进入房间的人。仆从的外貌着装由你决定，它们无法受伤并服从你的命令。每个仆从都可以完成一个普通人程度的工作，但它们不能攻击或者进行任何直接伤害其他生物的行动。因而仆从可以完成的工作包括：取来物品、清洁、修理、叠衣服、生火、上菜、倒酒等等。仆从不能离开该居所。\n该法术终止时，任何仍处于该异次元空间内的生物或物件都将被移出空间内，并出现在距离入口最近未占据空间内。","duration":"24小时","higherLevels":null,"id":"Mordenkainen's_Magnificent_Mansion","level":7,"nameEn":"Mordenkainen's Magnificent Mansion","nameZh":"魔邓肯豪宅术","range":"300尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一把价值250GP+的微缩模型剑","raw":"V、S、M（一把价值250GP+的微缩模型剑）","somatic":true,"verbal":true},"concentration":true,"description":"你在施法距离内创造出一个悬浮的灵体剑刃，其在法术持续时间内持续存在。\n幽灵剑出现时，你可以对该剑 5 尺内的一个目标进行一次近战法术攻击。命中时，目标受到 4d12+你的施法属性调整值 点力场伤害。\n在你的后续回合内，你能够以一个附赠动作将剑移动至多30尺至一处可见位置。随后你可以对相同或不同目标再次发动该攻击。","duration":"专注，至多1分钟","higherLevels":null,"id":"Mordenkainen's_Sword","level":7,"nameEn":"Mordenkainen's Sword","nameZh":"魔邓肯之剑","range":"90尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士","魔契师","法师"],"components":{"material":true,"materials":"一根与一个存在位面调谐的价值250GP+的分叉金属棒","raw":"V、S、M（一根与一个存在位面调谐的价值250GP+的分叉金属棒）","somatic":true,"verbal":true},"concentration":false,"description":"你和至多八名手牵着手形成一个圆圈的自愿生物被转移到一个不同的存在位面。你可以概括地指名一个目的地，比如火元素位面Plane of Fire的黄铜之城City of Brass，或九层地狱Nine Hells第二层迪斯帕特Dispater 的宫殿，按照DM的判断，你将出现在目的地里或其附近。\n另外，如果你知道某个处于另一位面的传送法阵的印记序列，则该法术可以把你带到该法阵处。如果该传送法阵太小而装不下所有你转移的生物，则他们会出现在离传送法阵最近的未占据空间中。","duration":"立即","higherLevels":null,"id":"Plane_Shift","level":7,"nameEn":"Plane Shift","nameZh":"位面转移","range":"触碰","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你增强施法距离内你可见的至多六名生物的防御。此法术赋予受术者共计120点临时生命值 ，由你在受术者中任意分配。","duration":"立即","higherLevels":null,"id":"Power_Word_Fortify","level":7,"nameEn":"Power Word Fortify","nameZh":"律令巩固","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"八条光线从你的手上闪出，作用于60尺锥形范围。每名位于锥形之中的生物进行一次敏捷豁免。为每个目标掷一次1d8来决定影响到它的射线种类，参照虹光射线表。\n虹光射线Prismatic Rays 1d8 射线 1 红Red。豁免失败：12d6点火焰伤害。豁免成功：半伤。 2 橙Orange。豁免失败：12d6点强酸伤害。豁免成功：半伤。 3 黄Yellow。豁免失败：12d6点闪电伤害。豁免成功：半伤。 4 绿Green。豁免失败：12d6点毒素伤害。豁免成功：半伤。 5 蓝Blue。豁免失败：12d6点寒冷伤害。豁免成功：半伤。 6 靛Indigo。豁免失败：目标陷入束缚状态，且其每个回合结束进行一次体质豁免。在累计三次豁免成功后，状态终止。在累计三次豁免失败后，该生物被转化为石头陷入石化状态，直到此状态被高等复原术Greater Restoration 或类似效应解除为止。成功或失败的检定不需要连续；只要记录各情况的次数直至其中一方累计三次为止。 7 紫Violet。豁免失败：目标陷入目盲 状态且在下一个你的回合开始时进行一次感知豁免。豁免成功，状态终止。豁免失败，状态终止，且该生物会被传送到另一个存在位面（由DM选择）。 8 特殊Special。目标被两道射线击中。掷两次骰，若有骰子骰值为8则重骰那颗骰子。","duration":"立即","higherLevels":null,"id":"Prismatic_Spray","level":7,"nameEn":"Prismatic Spray","nameZh":"虹光喷射","range":"自身","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":true,"materials":"一尊价值5GP+的自塑像","raw":"V、S、M（一尊价值5GP+的自塑像）","somatic":true,"verbal":true},"concentration":true,"description":"你创造一个自己的幻象分身，并使其在法术持续时间内维持存在。该分身可以出现在施法距离内你曾见过的任何地点，而不论中间是否存在障碍物。该幻象看起来和听起来都与你一样，只是没有现实形体。幻象受到伤害时会立即消失，法术终止。\n你可以通过分身的眼睛视物，用分身的耳朵聆听，如同你处于它的位置一样。用一个魔法动作，你能使分身移动至多60尺，而其姿态、言语和行为均按照你的指定作表现。幻象可以完美地模仿你的举止。\n由于东西可以穿过幻象，任何与该幻象进行的物理互动都会暴露其幻觉本质。一名生物可以采取研究动作进行一次对抗你法术豁免DC的成功智力（调查）检定以看穿幻象。辨出幻象的生物可以看穿该影像，其产生的声响对该生物而言显得虚假。","duration":"专注，至多1日","higherLevels":null,"id":"Project_Image","level":7,"nameEn":"Project Image","nameZh":"投影术","range":"500里","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","牧师","德鲁伊"],"components":{"material":true,"materials":"一个转经筒","raw":"V、S、M（一个转经筒）","somatic":true,"verbal":true},"concentration":false,"description":"一名你触碰的生物恢复4d8+15点生命值。在持续时间内，目标在其每回合开始时恢复1点生命值，且其失去的任何身体部位都将在2分钟后重新长出。","duration":"1小时","higherLevels":null,"id":"Regenerate","level":7,"nameEn":"Regenerate","nameZh":"再生术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1小时","classes":["吟游诗人","牧师"],"components":{"material":true,"materials":"一颗价值1000GP+的钻石，作为法术耗材","raw":"V、S、M（一颗价值1000GP+的钻石，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名已死，但死亡时间不超过100年，并非死于年老，且死亡时并非亡灵的生物，使其回生。\n生物以生命值全满的状态重生。该法术同样会中和在该生物死亡时仍在生效的毒素。该法术能治愈所有致命伤，恢复所有失去的身体部位。\n死而复生是一个痛苦的体验。目标进行D20检定时具有-4减值。目标每完成一次长休，其减值就减少1，直至减值变为0。\n使用该法术复活一名已死去365日或更久的生物会使你耗费大量精力。在你完成一次长休前，你将无法再施展任何法术，且此时你进行的一切D20检定具有劣势。","duration":"立即","higherLevels":null,"id":"Resurrection","level":7,"nameEn":"Resurrection","nameZh":"复生术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":true,"materials":"一颗天然磁石和铁屑","raw":"V、S、M（一颗天然磁石和铁屑）","somatic":true,"verbal":true},"concentration":true,"description":"该法术以施法距离内一点为中心，创造一个半径50尺、高100尺的重力反转柱状区域。区域内所有未被固定在地面上的生物和物件都会向上落去，直到碰到该区域顶端为止。一名生物可以进行一次敏捷豁免以抓住一件他能触及的固定物件，从而避免向上坠落。\n如果目标在坠落过程中撞上任何固体（比如天花板或被固定的物件），则坠落的物件和生物会受到同样情况下正常坠落时所会受到的冲击。如果一个物件或生物到达该区域的顶部并且没有撞到任何东西，则它将在持续时间内悬浮在该处。法术终止时，所有受术物件和受术生物向下坠落。","duration":"专注，至多1分钟","higherLevels":null,"id":"Reverse_Gravity","level":7,"nameEn":"Reverse Gravity","nameZh":"反转重力","range":"100尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"价值5000GP+宝石粉尘，作为法术耗材","raw":"V、S、M（价值5000GP+宝石粉尘，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一个物件或自愿生物，以魔法将其隔离起来。在法术持续期间，目标具有隐形状态并且不会被预言系法术作为目标，不会被魔法侦测，也不会被魔法远程观察到。\n如果目标是一个生物，它会进入静滞。它陷入失能状态，不会衰老，也不需要进食、饮水或呼吸空气。\n你可以设置一个让该法术提前终止的条件。该条件由你自由设定，但必须是发生在目标周围 1 里范围内或能在目标周围1里范围内看到的事件。例如：“1000 年以后”或者“当泰拉斯奎苏醒时”。如果受术者受到任何伤害，则该法术立刻终止。","duration":"直至被解除","higherLevels":null,"id":"Sequester","level":7,"nameEn":"Sequester","nameZh":"隔离术","range":"触碰","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"12小时","classes":["法师"],"components":{"material":true,"materials":"价值1500GP+的红宝石粉末，作为法术耗材","raw":"V、S、M（价值1500GP+的红宝石粉末，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你创造一个野兽或类人生物的拟像，该生物在整段施法时间内必须一直在你的10尺内。结束施法时，你同时触碰该生物以及和该生物同样体型的一堆冰或者雪，然后冰雪变化为该生物的拟像。拟像是一个生物。它使用拟像对象本体在施法时的游戏数据，但其类别为构装，生命值上限为本体生命值上限的一半，并且它无法施展拟像术。\n拟像对你和你所选定的生物态度友善。它服从你的命令并在战斗中你的回合里行动。拟像不能升级，也不能进行短休和长休。\n如果拟像受到了伤害，想让其生命值恢复的唯一手段就是为其进行修理（作为长休 的一部分）。而若想要修理一个拟像，拟像必须在长休期间时刻处于你周围5尺内，且每为其恢复一点生命值就需要消耗你价值100GP的法术耗材。\n拟像会一直持续到其生命值降至0为止，在生命值降至0时它会变回冰雪并立刻融化。再次施展此法术时，任何你已用此法术创造出来的拟像都会立刻被摧毁。","duration":"直至被解除","higherLevels":null,"id":"Simulacrum","level":7,"nameEn":"Simulacrum","nameZh":"拟像术","range":"触碰","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","牧师","德鲁伊","法师"],"components":{"material":true,"materials":"价值1000GP+的钻石粉末，作为法术耗材","raw":"V、S、M（价值1000GP+的钻石粉末，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"施展该法术时，你在某个表面（诸如地板或墙的一部分）或某个能被关闭的物件里（诸如书本或宝箱）刻下一个伤害性的符纹。符纹可以覆盖周边不超过 10 尺直径的区域。如果你指定某个物件，则该物件必须待在其所在位置；如果该物件从你施法的位置被移动超过 10 尺，则其符纹被破坏且法术不被触发即告终止。\n该符纹近乎隐形，其需要成功以法术的豁免 DC 进行一次智力（调查）检定才能被发现。\n你在刻下符文时决定该符纹的触发条件并选择徽记承载的效应：死亡、争斗、恐惧、痛苦、睡眠或震慑。对应效应在下面详述。\n设置触发条件Set the Trigger。 你在施法时决定由什么来触发符纹。刻画于表面的符纹其通常的触发条件包括：触碰或站立在符纹上；拿掉覆盖在符纹上的物件；进入符纹一定施法距离。刻画在物件内的符纹其通常的触发条件包括：打开物件；看到该符纹等。\n你可以进一步细化触发条件以便特定生物种类才能激活之（例如将符纹设定为影响异怪）。你还可以将符合条件者排除在符纹触发者之外，例如说出特定口令的人。\n符纹一旦被触发就会开始变大，使其周围 60 尺半径的球状区域处于微光光照并持续 10 分钟，此后法术即告终止。符纹生效时，所有位于球状区域内的生物即成为法术效应的目标。生物在一个回合内第一次进入该区域内或在其中结束其回合时，也同样会成为符文效应的目标。一个生物每回合只能成为其目标一次。\n死亡Death。每个目标进行一次体质豁免，豁免失败者将受到 10d10 点暗蚀伤害，豁免成功则伤害减半。争斗Discord。每个目标进行一次感知豁免。豁免失败者将在接下来的 1 分钟内将不停地与其他生物争吵。期间它无法进行任何有意义的沟通，并且其进行的所有攻击检定和属性检定都具有劣势。恐惧Fear。每个目标进行一次感知豁免，豁免失败者将陷入 1 分钟的恐慌状态。被恐慌时，该生物只要可能，就必须在其回合内向远离符文的方向移动至少 30 尺。苦痛Pain。每个目标进行一次体质豁免，豁免失败者将陷入 1 分钟的失能状态。睡眠Sleep。每个目标进行一次感知豁免，豁免失败者将陷入 10 分钟的昏迷状态。该睡眠者受到伤害时将会被惊醒，也可以被其他人用一个动作摇醒。震慑Stunning。每个目标进行一次感知豁免，豁免失败者将陷入 1 分钟的震慑状态。","duration":"直到法术被解除或触发","higherLevels":null,"id":"Symbol","level":7,"nameEn":"Symbol","nameZh":"徽记术","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"此法术立即将你和至多八名施法距离内你可见的自愿生物，或者施法距离内你可见的一个物件转移至你选择的目的地。如果目标为一个物件，则其必须为大型Large或更小，且不能被一名非自愿生物持握或携带。\n你必须知道目的地，且目的地必须与你位于同一个存在位面。你对目的地的熟悉程度决定了你抵达目的地的成功率。DM骰1d100并参照传送结果表和其后的详述。\n传送结果Teleportation Outcome 熟悉程度 遇难 相似区域 偏离地点 抵达地点 永久法阵 - - - 01-00 相关物件 - - - 01-00 非常熟悉 01-05 06-13 14-24 25-00 偶尔见过 01-33 34-43 44-53 54-00 看过一次或听过描述 01-43 44-53 54-73 74-00 查无此地 01-50 51-00 - -\n熟悉程度Familiarity。 表中熟悉程度一列的词汇解释如下：\n“永久法阵” 指某处你知道其印记序列的永久传送法阵。 “相关物件”指你持有一件在过去六个月内从目标地点取来的物件，例如某个法师图书馆内的一本书。 “非常熟悉” 指你常去的地方，你仔细研究过的地方，或是你在施展该法术时能看见的地方。 “偶尔见过” 指你见过几次的地方，但你不是很熟悉。 “见过一次或听过描述”指你只见过一次的地方，包括通过魔法看到的地点，或你从别人那里听来位置和外观的地点，比如从地图上看来的地点。 “查无此地”指根本不存在的地点。也许你尝试探知敌人的密室但看到的只是幻象，或是你尝试传送至一个如今已不再存在的地点。\n遇难Mishap。该法术不可控的魔法效果导致这次旅行特别艰难。尝试传送的所有生物（或目标物件）受到3d10点力场伤害，随后DM重骰d100并查阅上表来决定你们出现在哪里（你们可能再次遇难，而每次遇难都要承受该伤害）。相似地区Similar Area。你和你的队伍（或目标物件）出现在一个和目的地外观或主题相似的不同地点。你出现在最近的相似地区。例如，如果你想回你自己的研究室去，则你可能会误打误撞出现在同一座城市其他法师的研究室里。偏离地点Off Target。 你和你的队伍（或目标物件）出现在目的地随机方向上2d12里距离的一点。骰1d8来判误差出现在目的地的哪个方向：1，正东；2，东南；3，正南；4，西南；5，正西；6，西北；7，正北；8，东北。抵达地点On Target。你和你的队伍（或目标物件）出现在你欲抵达的地点。","duration":"立即","higherLevels":null,"id":"Teleport","level":7,"nameEn":"Teleport","nameZh":"传送术","range":"10尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"选择施法距离内任意数量的自愿生物。每个目标都变形为一只挑战等级不超过4，体型不超过大型的野兽。你可以将每个目标变为不同的形态。在法术持续时间内之后的回合中，你可以使用一个魔法动作将这些目标再度变形。\n生物的游戏数据被选择的野兽资料卡替换，但目标保留其生物类型、生命值、生命骰、阵营、交流的能力以及智力、感知、魅力属性值。目标的动作受到新形态身体结构的限制，并且无法施法。目标的装备会融入其新形态，而且处于此形态时无法使用这些被融入的装备。\n目标获得等于其变形的首个形态生命值的临时生命值。法术结束时目标失去所有因此法术获得的临时生命值。该形态持续至持续时间结束，目标也能以一个附赠动作结束此法术。","duration":"24 小时","higherLevels":null,"id":"Animal_Shapes","level":8,"nameEn":"Animal Shapes","nameZh":"动物形态","range":"30 尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","法师"],"components":{"material":true,"materials":"一撮铁粉或铁屑","raw":"V、S、M（一撮铁粉或铁屑）","somatic":true,"verbal":true},"concentration":true,"description":"一道反魔法灵光环绕着你形成10尺光环区域。在灵光内部无法施展法术，使用魔法动作或创造魔法效应，并且这些事物也无法以灵光内的任何事物为目标或影响灵光内部的任何事物。魔法物品的魔法词条在灵光内部不起作用，也无法影响处于灵光内部的任何事物。\n法术和其他魔法效应产生的效应区域无法延伸至灵光内部。传送无法进出其范围，位面旅行在该范围内无法使用。当传送门处于灵光内部时，传送门会暂时关闭。\n正在持续中的法术在区域内会被压制，除非该法术为某个神器或某位神明所施展。压制的魔法效应不会生效，但该魔法效应受压制的时间仍然如常计入其总持续时间。","duration":"专注，至多 1 小时","higherLevels":null,"id":"Antimagic_Field","level":8,"nameEn":"Antimagic Field","nameZh":"反魔法场","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"1 小时","classes":["吟游诗人","德鲁伊","法师"],"components":{"material":true,"materials":"醋和蜂蜜的混合","raw":"V、S、M（醋和蜂蜜的混合）","somatic":true,"verbal":true},"concentration":false,"description":"当你施展此法术时，选择它是产生嫌恶还是关怀效应，并选择一个巨型或更小体型的生物或物件。然后指定特定类型的生物，比如红龙、地精或吸血鬼。当此类生物进入被选择的生物120尺内时，它必须进行一次感知豁免。你选择的嫌恶或关怀效应会决定当豁免失败时，这个生物身上产生的效应。\n嫌恶术Antipathy。该生物将陷入恐慌 状态。因此陷入恐慌的生物必须在其回合内使用其移动力尽可能远离目标，并沿着最安全的路线移动。关怀术Sympathy。该生物将陷入魅惑状态。因此陷入魅惑的生物必须在其回合内使用其移动力尽可能接近目标，并沿着最安全的路线移动。如果该生物位于目标的5尺内，它不能自主远离目标。如果目标伤害陷入魅惑 的生物，该生物能够如下文描述一样进行一次感知豁免来结束这一效应。\n结束效应Ending the Effect。如果陷入恐慌或魅惑 的生物在距离目标距离120尺以上结束时结束回合，该生物进行一次感知豁免。豁免成功的情况下，该生物不再被目标影响。在对抗该效应的豁免中成功的生物将不受此法术的效应影响，持续 1 分钟，随后仍可能受到该效应影响。","duration":"10天","higherLevels":null,"id":"AntipathySympathy","level":8,"nameEn":"Antipathy/Sympathy","nameZh":"嫌恶术/关怀术","range":"60 尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","德鲁伊","魔契师","法师"],"components":{"material":true,"materials":"一把没有钥匙的钥匙圈","raw":"V、S、M（一把没有钥匙的钥匙圈）","somatic":true,"verbal":true},"concentration":false,"description":"你将一个施法距离内你可见的生物的心灵爆破。该目标必须进行一次智力豁免。\n若豁免成功，则目标只会受到一半伤害。\n（注：本法术在PHB2014中原名弱智术Feeblemind）","duration":"立即","higherLevels":null,"id":"Befuddlement","level":8,"nameEn":"Befuddlement","nameZh":"摧心术","range":"150尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"1 小时","classes":["法师"],"components":{"material":true,"materials":"一枚价值1000GP+的钻石，作为法术耗材。以及一副价值2000GP+的可密封大容器，其尺寸必须足以存放即将要被克隆的生物","raw":"V、S、M（一枚价值1000GP+的钻石，作为法术耗材。以及一副价值2000GP+的可密封大容器，其尺寸必须足以存放即将要被克隆的生物）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名生物或其至少1立方寸的血肉。在施展法术使用的容器中，一具该生物的无意识克隆体在其中逐渐成形，并将在120日后完成。你可以选择完成后的克隆体是和目标生物相同年龄还是更为年轻的版本。在容器未被外界影响的情况下，其中的躯体会一直保持无意识的静止状态。\n如果本体生物在克隆体完成后死亡，则其灵魂会转移到克隆体中，前提是该灵魂自由且愿意归来。克隆体的肉体特质与原本躯体相同，并具有相同的个性、记忆和能力，但不会具有本体的随身装备。由于灵魂已经转移到别处，该生物原本的遗体（如果依然存在）将变得无意识，且不能被复活。","duration":"立即","higherLevels":null,"id":"Clone","level":8,"nameEn":"Clone","nameZh":"克隆术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"10分钟","classes":["牧师","德鲁伊","法师"],"components":{"material":true,"materials":"燃烧的熏香","raw":"V、S、M（燃烧的熏香）","somatic":true,"verbal":true},"concentration":true,"description":"你在法术持续时间内操控距你5里内的天气。你在施法时必须位于户外，并且若你回到室内，法术会提前终止。\n你施展此法术时，可以改变现有的天气状况（由DM决定）。你可以改变降水、气温和风势。新状况需要1d4×10分钟才能起效。一旦新状况起效，你便能再次改变天气状况。法术结束时，天气状况会逐渐回归正常。\n改变天气状况时，你可以从下述表格查明与目前状况对应的等级，再选择同一表格中高一级或低一级的状况作为其改变结果。改变风势时，你还可以同时改变其风向。 降水Precipitation 气温Temperature 风势Wind 阶段 状况 阶段 状况 阶段 状况 1 晴 1 酷热 1 无风 2 薄云 2 炎热 2 和风 3 多云或有雾 3 温暖 3 强风 4 雨、雹或雪 4 凉爽 4 大风 5 倾盆大雨、猛烈冰雹\n或漫天暴雪 5 寒冷 5 暴风 6 极寒","duration":"专注，至多8小时","higherLevels":null,"id":"Control_Weather","level":8,"nameEn":"Control Weather","nameZh":"操控天气","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"S","somatic":true,"verbal":false},"concentration":false,"description":"你在施法距离内你可见的一处平坦固体表面上创造一扇中型的通向半位面的虚幻门。这扇门可以被关闭和开启。半位面是一间各边均长30尺，木质或石质（由你选择）的空房间。\n法术终止时，门消失不见，任何仍然位于半位面中的物件会留在内部。任何仍然位于半位面中的生物也会留在那里，除非他们选择在门消失的时候被抛出，在距门先前占据的空间中最近的未占空间中落地，陷入倒地状态。\n你每次施展此法术时都可以创造一个新的半位面，也可以将门连向你先前用此法术创造的半位面。此外，如果你知晓了某个其他生物用此法术创造的半位面的本质和内容物，则你也可以通过此法术连接到那里。","duration":"1小时","higherLevels":null,"id":"Demiplane","level":8,"nameEn":"Demiplane","nameZh":"半位面","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"选择一名施法距离内你可见的生物，该生物必须成功于一次感知豁免，否则在持续时间内陷入魅惑状态。若你或你的盟友正在与其战斗，则目标在此豁免上具有优势。目标受到伤害时，可以重复进行豁免，豁免成功则其身上的此法术终止。\n目标被魅惑期间，只要你与其处于同一位面就可以与之保持心灵感应。在你的回合，你可以通过心灵感应命令该生物（无需动作），比如“攻击那个生物”“跑到那个位置”或是“去拿那个物品”。目标完成一项指令却未收到你的进一步指示时，将会凭自身喜好行动，尽可能的保护自己。\n你可以用自己的反应去要求目标执行一项反应。","duration":"专注，至多1小时","higherLevels":{"kind":"升环施法","text":"使用更高环阶法术位施展时，你的专注能持续更长时间，九环至多8小时。"},"id":"Dominate_Monster","level":8,"nameEn":"Dominate Monster","nameZh":"支配怪物","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士"],"components":{"material":true,"materials":"一块碎岩","raw":"V、S、M（一块碎岩）","somatic":true,"verbal":true},"concentration":true,"description":"选择施法距离内你可见的地面上一点。法术持续时间内，一股强烈的震颤在以震源为中心半径100尺的圆形范围内传递。处于此范围内的地面被视为困难地形 。\n你施展此法术时，以及法术持续时间内每个你的回合结束时，区域地面上的每个生物都必须进行一次敏捷豁免，豁免失败则其陷入倒地状态，且其专注被打断。\n你也可以应用下述的额外效应：\n裂缝Fissures。在你施展此法术的回合结束时，受法术影响的区域会撕开总计1d6条裂缝。你选择裂缝生成的地点，但裂缝的位置不可位于建筑物之下。每条裂缝深1d10×10尺，宽10尺，并由影响区域的一边向另一边延伸。裂缝撕开时，处于其位置上的生物必须成功通过一次敏捷豁免，否则将坠落其中。豁免成功则该生物在裂缝张开时随之移动到裂缝的边缘。建筑Structures。在你施展此法术时及法术终止前你的每个回合结束时，地震对影响区域内的所有与地面有接触的建筑都造成50点钝击伤害。建筑生命值降为0时立即崩塌。与该建筑距离不大于该建筑高度一半的生物进行一次敏捷豁免。豁免失败则受12d6点钝击伤害并陷入倒地状态且被埋于废墟之下。该生物可用一个动作通过一次DC20的力量（运动）检定来尝试逃离废墟。DM可根据废墟的情况调整DC高低。豁免成功则只受一半伤害。","duration":"专注，至多1分钟","higherLevels":null,"id":"Earthquake","level":8,"nameEn":"Earthquake","nameZh":"地震术","range":"500尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"直至法术终止前，你每次进行魅力检定时可以用15代替你掷出的数值。此外，无论你说什么，判断你是否说谎的魔法都会将你的话视为真实。","duration":"1小时","higherLevels":null,"id":"Glibness","level":8,"nameEn":"Glibness","nameZh":"花言巧语","range":"自身","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":true,"materials":"一个价值1000+GP 的小圣物箱","raw":"V、S、M（一个价值1000+GP 的小圣物箱）","somatic":true,"verbal":true},"concentration":true,"description":"你在持续时间中发出灵光形成半径30尺的光环。你可以指定若干生物，在光环内时，他们进行的所有豁免均具有优势，而其他生物对它们进行的攻击检定具有劣势。另外，当一个邪魔或亡灵生物以近战攻击命中受术生物时，攻击者必须进行一次体质豁免，豁免失败者将陷入目盲状态，持续至它的下一回合结束。","duration":"专注，至多1分钟","higherLevels":null,"id":"Holy_Aura","level":8,"nameEn":"Holy Aura","nameZh":"圣洁灵光","range":"自身","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"烟云出现时，每个处在其内的生物都必须通过一次敏捷豁免，豁免失败者将受到10d8点火焰伤害，豁免成功则受到一半伤害。该球状区域移动至生物所占据的空间，或者生物进入球状区域内，或者生物在球状 区域内结束其回合时，该生物也必须进行该豁免。一名生物每回合仅需进行一次该豁免。\n在你的每回合开始时，烟云会向你指定的、远离你的方向直线移动10尺。","duration":"专注，至多1分钟","higherLevels":null,"id":"Incendiary_Cloud","level":8,"nameEn":"Incendiary Cloud","nameZh":"焚云术","range":"150尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你将施法距离内一个你能看见的生物放逐到一个迷宫般错综复杂的半位面。目标将一直留在该处直至法术持续时间结束，或者直到它逃出该迷宫。\n目标可以使用研究动作尝试逃出迷宫。此时它可以进行一次DC20 （调查 ）的智力检定，检定成功将逃出迷宫，而该法术随之终止。\n法术终止时，目标将重新出现在它之前消失的位置。如果该位置被占据，则目标出现在最近的未占据位置。","duration":"专注，至多10分钟","higherLevels":null,"id":"Maze","level":8,"nameEn":"Maze","nameZh":"迷宫术","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"直到法术终止前，你所触碰的一个自愿生物对下列项目具有免疫：心灵伤害；魅惑状态；任何可以感知到其情绪、阵营或阅读其思想的效应；可以侦测其位置的魔法。任何法术，哪怕是祈愿术Wish，都不能收集目标信息、远程监视之或控制其心智。","duration":"24小时","higherLevels":null,"id":"Mind_Blank","level":8,"nameEn":"Mind Blank","nameZh":"心灵屏障","range":"触碰","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你压垮施法距离内一名你可见生物的心灵。若目标生命值不超过150点，则其陷入震慑状态；否则，目标的速度直至你下个回合开始前变为0。\n被震慑目标在每个其回合结束时进行一次体质豁免。豁免成功时其身上的此状态终止。","duration":"立即","higherLevels":null,"id":"Power_Word_Stun","level":8,"nameEn":"Power Word Stun","nameZh":"律令震慑","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","德鲁伊","术士","法师"],"components":{"material":true,"materials":"一块太阳石","raw":"V、S、M（一块太阳石）","somatic":true,"verbal":true},"concentration":false,"description":"指定施法距离内一点，以其为中心周围 60 尺半径的球状区域闪耀出灿烂的阳光。所有球状区域中的生物进行一次体质豁免。豁免失败者将受到12d6点光耀伤害，并陷入持续1分钟的目盲状态。豁免成功则仅受到一半伤害。\n因该法术陷入目盲的生物在其每回合结束时都可以再进行一次体质豁免。豁免成功则不再目盲。\n该法术将驱散法术区域内所有由法术所创造的黑暗。","duration":"立即","higherLevels":null,"id":"Sunburst","level":8,"nameEn":"Sunburst","nameZh":"阳炎爆","range":"150尺","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["法师"],"components":{"material":true,"materials":"一对银连环","raw":"V、S、M（一对银连环）","somatic":true,"verbal":true},"concentration":false,"description":"你与一个你熟识的自愿生物建起心灵连接。该生物可以身处你所在的存在位面的任意位置。一旦你与目标生物不再位于同一位面，则该法术随即终止。\n直至法术终止，你可以和目标生物通过心灵连接即时共享任何言语、图像、声音以及其他形式的感官信息，而目标也能够辨认出与之交流的对象正是你本人。该法术可以让目标生物理解你所发送的话语和任何感官信息。","duration":"24小时","higherLevels":null,"id":"Telepathy","level":8,"nameEn":"Telepathy","nameZh":"心灵感应","range":"无限","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"一面水墙从施法范围内你指定的一点成型。水墙至多长300尺，高300尺，厚50尺，且持续存在至法术终止。\n水墙出现时，所有位于范围内的生物进行一次力量豁免。豁免失败者受到6d10点钝击伤害，豁免成功则只受一半伤害。\n水墙出现后你的每回合开始时，水墙将带着其内的所有生物一起向远离你的方向移动50尺。当水墙进入一个体型不超过巨型的生物所占据的空间，或他们原本就处于墙内时，该生物必须进行一次力量豁免，豁免失败则受到5d10点钝击伤害。一名生物一轮只能受到一次此伤害。在你的回合结束时，水墙的高度减少50尺，且其随后每轮对生物造成的伤害也减少1d10。当水墙高度变为0尺时，法术终止。\n淹没在水墙中的生物可以用游泳的方式移动，由于波涛阻力影响，该生物必须成功于一次对抗你法术豁免DC的力量（运动）检定以决定其能否成功移动。检定失败者无法移动。移动离开水墙区域的生物会直接掉到地上。","duration":"专注，至多6轮","higherLevels":null,"id":"Tsunami","level":8,"nameEn":"Tsunami","nameZh":"海啸术","range":"1里","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1 小时","classes":["牧师","魔契师","法师"],"components":{"material":true,"materials":"你必须为此法术的每个目标准备一枚价值1000GP+的红锆石和一根价值100GP+的银棒，两者都作为此法术耗材","raw":"V、S、M（你必须为此法术的每个目标准备一枚价值1000GP+的红锆石和一根价值100GP+的银棒，两者都作为此法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你和施法距离内至多八名自愿的生物将星界躯体投影到星光位面Astral Plane（如果你已经在星光位面，则法术立即终止）。每个目标原本的躯体都会被留在原地陷入静止；每个躯体都会具有昏迷状态，但不需要空气、食物，也不会衰老。\n目标的星界躯体几乎完美的保持了原本的形态，并保留其本体的游戏资料和随身物。生物的星界躯体与本体有一个显著的区别，那就星界躯体从肩胛骨间向后伸出的一条银线。这条线的可见长度仅有一尺。\n如果目标的银线被切断（只有明确注明可以切断这种银线的效应才可以将其切断），目标的身体和星界躯体都会死亡。\n目标的星界躯体可以在星光位面任意旅行。当星界躯体离开星光位面时，你的本体和物品将沿着银线被传送，使你以本体的形态到达新位面。\n星界躯体承受的伤害或效应不会反映在你的本体上，反之亦然。如果某生物的本体或星界躯体的生命值降至0，则该生物自身的投影效应终止。你可以用魔法 动作消解此法术，以此结束此法术所有目标的星界投影效应。\n受术生物身上的法术效应终止时，如果其没有死亡，其会被拉回原本的躯体，并脱离静止。","duration":"直到被解除","higherLevels":null,"id":"Astral_Projection","level":9,"nameEn":"Astral Projection","nameZh":"星界投影","range":"10 尺","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["吟游诗人","德鲁伊","魔契师","法师"],"components":{"material":true,"materials":"一根蜂鸟羽毛","raw":"V、S、M（一根蜂鸟羽毛）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名自愿生物，并授予其预见近未来事件的有限能力。法术持续时间内，该目标进行的所有D20检定均具有优势，而其他生物对其进行攻击检定时具有劣势。此法术的效应会在你再次施展此法术时提前终止。","duration":"8小时","higherLevels":null,"id":"Foresight","level":9,"nameEn":"Foresight","nameZh":"预见术","range":"触碰","ritual":false,"school":"预言","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师","术士","魔契师","法师"],"components":{"material":true,"materials":"一颗价值5000GP+的钻石","raw":"V、S、M（一颗价值5000GP+的钻石）","somatic":true,"verbal":true},"concentration":true,"description":"你召唤一扇传送门将施法距离内你能看到的一处未占据空间与一个不同位面的准确地点连接在一起。传送门是你打开的一个直径5到20尺的圆形开口。其开口朝向你指定的任意方向，并持续至法术终止。传送门在法术持续时间内一直存在，且可以透过传送门看见其目的地。\n在两个位面上显现的传送门均有明确的正反面，只有穿过传送门的正面才能实现位面旅行。任何穿过传送门正面的事物将被瞬间转移至另一位面，随后显现在离另一道传送门周围最近的未占据空间中。\n神祇以及其他位面统治者均可以阻止该法术在其所在或属于其领域的任何地点创造传送门。\n施展该法术时，你可以说出某个特定生物的名字（不能是假名、头衔、绰号等）。如果该生物在与你不同的位面，则传送门会紧挨被指名生物打开并将该生物转移至你这一侧，出现在距传送门最近的未占空间。你不会获得任何用来控制被传送生物的特殊能力，而它此时可以自由的作任何DM认为合适的行动。它可能离开，也可以攻击你或协助你。","duration":"专注，至多1分钟","higherLevels":null,"id":"Gate","level":9,"nameEn":"Gate","nameZh":"异界之门","range":"60尺","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"1分钟","classes":["魔契师","法师"],"components":{"material":true,"materials":"一个价值5000GP+的与目标相似的小雕像","raw":"V、S、M（一个价值5000GP+的与目标相似的小雕像）","somatic":true,"verbal":true},"concentration":false,"description":"你创造一个魔法禁锢之牢，将施法距离内一个你能看见的生物监禁于其内。目标必须通过一次感知豁免，若成功通过豁免，生物将不受此法术影响，并且免疫于此法术24小时。而豁免失败则被该法术禁锢。禁锢期间，目标生物不需要呼吸，不需要吃喝，也不会变老。预言法术无法定位或感知到该目标，并且目标生物不能传送。\n直至法术结束前，该生物还将承受下述其中一项你所选择的效应：\n埋葬Burial。目标被深埋在地表以下的球体魔法力场内，其大小刚好能包覆住目标。任何事物都无法进入或离开这个球体魔法力场。锁链Chaining。沉重的锁链牢固地深植于大地，将目标禁锢在原地。目标陷入束缚状态，且任何手段都无法使目标被移动。避世监牢Hedged Prison。 该法术将目标传送至一个隔绝了传送和位面旅行的小型半位面。该半位面的结构由你选择，它可以是一个迷宫（labyrinth）、一间牢房、一座塔楼、或是其他类似的建筑。微缩牢笼Minimus Containment。 目标被缩小到1寸高，并囚禁于一块宝石或是类似的物件中。光线可以正常地穿透宝石（使目标得以看到外面，其他生物也可以看到里面），但其他任何事物仍无法以任何方式出入牢笼。沉睡Slumber。 目标陷入昏迷状态且无法被唤醒。\n终止法术Ending the Spell。当你施展此法术时，你需要配置一个使法术终止并释放目标的条件。此条件不论明确还是复杂都按你的意愿决定，但该条件在未来十年内必须有较高可能性发生（由DM判断并同意）。你配置的条件必须是一个可以被观测的行为，例如某人在你信仰神祇的神庙内献上了一份特殊的祭品，某人拯救了你的真爱，或者是击败了某只特定的怪物。尝试使用法术解除魔法Dispel Magic终止此法术时，施展者必须使用九环法术位，并对监牢或创造监牢效果所用的法术材料施展该法术，才能以此终止此法术。","duration":"直至解除","higherLevels":null,"id":"Imprisonment","level":9,"nameEn":"Imprisonment","nameZh":"禁锢术","range":"30尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["牧师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"如泉涌般的治愈能量从你流向周遭的生物。选择施法距离内任意数量的可见生物，你令它们恢复总计至多700点生命值，每个生物的具体治疗量则由你随意分配。受该法术所治疗的生物的目盲、耳聋、中毒状态也一并被移除。","duration":"立即","higherLevels":null,"id":"Mass_Heal","level":9,"nameEn":"Mass Heal","nameZh":"群体医疗术","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"炽热的焰球坠向地面上你指定的你所能看见的施法距离内四个不同地点。以每个指定点为中心，40尺半径球状 区域内的每个生物必须通过一次敏捷豁免。豁免失败者将受到 20d6 的火焰伤害和 20d6 的钝击伤害，豁免成功则受到一半伤害。即使生物同时处于多个球状火焰内的生物也只会受一次效应影响。\n法术区域内的未被着装或携带的非魔法物件也会承受该伤害，若其可燃则也会开始燃烧 。","duration":"立即","higherLevels":null,"id":"Meteor_Swarm","level":9,"nameEn":"Meteor Swarm","nameZh":"流星爆","range":"1里","ritual":false,"school":"塑能","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","牧师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"一股治疗能量冲刷着一名施法距离内你可见的生物。目标恢复其所有生命值。若目标具有魅惑、恐慌、麻痹、中毒、震慑状态，则目标身上的此类状态立刻结束。若目标处于倒地状态，则其还可以用其反应起身。","duration":"立即","higherLevels":null,"id":"Power_Word_Heal","level":9,"nameEn":"Power Word Heal","nameZh":"律令医疗","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","术士","魔契师","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你强迫一名施法距离内你可见的生物死亡。若目标的生命值 为低于或等于100点，目标立即死亡。否则，目标将受到12d12点心灵伤害。","duration":"立即","higherLevels":null,"id":"Power_Word_Kill","level":9,"nameEn":"Power Word Kill","nameZh":"律令死亡","range":"60尺","ritual":false,"school":"惑控","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":false,"description":"以施法距离内你一点为源点，各种色彩的光芒形成光面，再组合构成一道不透明的垂直墙壁。法墙至多长90尺，高30尺，厚1寸。作为另一种选项，你也能以施法距离内你能看到的一点为中心，将法墙塑造成一个直径至多30尺的球体。法墙在持续时间内一直存在。如果你指定法墙生成的空间已被生物占据，则法术立即结束且不产生任何效应。\n法墙发出100尺的明亮光照，以及其外100尺的微光光照。施展该法术时你可以指定任意数量的生物，法墙存在期间你与所指定的生物可以穿过法墙或停留在法墙附近而不受伤害。如果其他能看见法墙的生物移动到距墙20尺内或在该处开始其回合，则该生物必须进行一次体质豁免，豁免失败则陷入目盲 状态，持续1分钟。\n法墙由七层组成，每层都有不同颜色。生物试图进入或穿过法墙时，将逐层穿过法墙所有的光层。其每穿过一层就必须进行一次敏捷豁免，豁免失败则受虹光光层表中所述特性影响。\n虹光光层Prismatic Layers 顺序 效应 1 红Red。豁免失败：12d6火焰伤害。豁免成功：半伤。额外效应：非魔法远程攻击无法穿过此层，此层受到累计25寒冷伤害后被摧毁。 2 橙Orange。豁免失败：12d6强酸伤害。豁免成功：半伤。额外效应：魔法远程攻击无法穿过此层，此层受强风（如造风术Gust of Wind创造的风）吹袭后被摧毁。 3 黄Yellow。豁免失败：12d6闪电伤害。豁免成功：半伤。额外效应：此层受到累计60点力场伤害后被摧毁。 4 绿Green。豁免失败：12d6毒素伤害。豁免成功：半伤。额外效应：此层受穿墙术Passwall影响，或者其他相同或更高环阶法术在固态表面开口的效应影响时被摧毁。 5 蓝Blue。豁免失败：12d6寒冷伤害。豁免成功：半伤。额外效应：此层受到25点火焰伤害后被摧毁。 6 靛Indigo。豁免失败：目标陷入束缚状态，且其每个回合结束进行一次体质豁免。在累计三次豁免成功后，状态终止。在累计三次豁免失败后，该生物被转化为石头陷入石化状态，直到此状态被高等复原术Greater Restoration或类似效应解除为止。成功或失败的检定不需要连续；只要记录各情况的次数直至其中一方累计三次为止。额外效应：法术无法穿过此层，此层受到昼明术Daylight的明亮光照照射后被摧毁。 7 紫Violet。豁免失败：目标陷入目盲状态且在下一个你的回合开始时需要再进行一次感知豁免。若豁免成功，状态终止。若豁免失败，状态终止，且该生物会被传送到另一个存在位面（由DM选择）。额外效应：此层受解除魔法Dispel Magic解除后被摧毁。","duration":"10分钟","higherLevels":null,"id":"Prismatic_Wall","level":9,"nameEn":"Prismatic Wall","nameZh":"虹光法墙","range":"60尺","ritual":false,"school":"防护","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊","法师"],"components":{"material":true,"materials":"一只价值1500GP+的玉环","raw":"V、S、M（一只价值1500GP+的玉环）","somatic":true,"verbal":true},"concentration":true,"description":"在法术持续时间内，你变形为另一个生物。你还可以使用魔法动作来变形为另一个符合条件的形态。新形态生物的挑战等级必须不高于你的等级或挑战等级的生物。你必须在之前见过该类生物至少一次，并且该生物不能是构装或亡灵生物。\n当你施展此法术时，你获得数值等于你变形的首个形态生命值的临时生命值。法术结束时你失去所有因此法术获得的临时生命值。\n你的游戏资料卡替换为所选择形态的资料卡，但你保留你的生物类型、阵营、人格，智力、感知与魅力属性值、生命值、生命骰、熟练以及交流的能力。如果你具有施法特性，你同样保留它。\n进行变形的途中，你可以决定你的装备是落到地上，还是改变其尺寸和形状来适应你的新形态。","duration":"专注，至多1小时","higherLevels":null,"id":"Shapechange","level":9,"nameEn":"Shapechange","nameZh":"形体变化","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["德鲁伊"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"以施法距离内一点为中心，一团翻腾搅动的乌云在法术时间内成形，并扩散至半径300尺的区域。当云团出现时，所有位于云团下的生物必须进行一次体质豁免。豁免失败者将受到2d6点雷鸣伤害且在持续时间内陷入耳聋 状态。\n在持续时间内。后续的每个你的回合开始时，风暴会在产生一道不同的效应，如下所示：\n第2回合。 云层中降下酸雨。所有位于云团下方的生物和物件受到4d6点强酸伤害。第3回合。 你从云中召下六束闪电束击向六个位于云团下的不同生物/物件。这些目标必须通过一次敏捷豁免，豁免失败者将受到10d6点闪电伤害，豁免成功者受到一半伤害。第4回合。 冰雹从云团中倾泻而下。所有位于云团下方的生物将受到2d6点钝击伤害。第5回合~第10回合。狂风和冰雨冲袭着云团下的区域，该区域内的所有生物受到1d6点寒冷伤害。在法术结束前，使该区域变为困难地形、形成重度遮蔽 ，并刮起强风。该区域内无法使用武器发动远程攻击。","duration":"专注，至多 1 分钟","higherLevels":null,"id":"Storm_of_Vengeance","level":9,"nameEn":"Storm of Vengeance","nameZh":"复仇风暴","range":"1里","ritual":false,"school":"咒法","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"你短暂地停止其他所有人的时间流。你一次性进行1d4+1个回合，在此期间，时间对于其他生物而言是静止的，但你可以像正常一样移动和使用动作。\n在此期间，若你的一个动作或任何你创造出来的效应影响到除你之外的任何生物，或影响到其他生物着装或携带的物件时，法术将终止。此外，如果你在施法后移动到了距施法时位置1000尺以外的地方，则法术也将终止。","duration":"立即","higherLevels":null,"id":"Time_Stop","level":9,"nameEn":"Time Stop","nameZh":"时间停止","range":"自身","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"动作","classes":["吟游诗人","魔契师","法师"],"components":{"material":true,"materials":"一滴汞、一团阿拉伯胶和一缕烟","raw":"V、S、M（一滴汞、一团阿拉伯胶和一缕烟）","somatic":true,"verbal":true},"concentration":true,"description":"选择施法距离内你可见的一名生物或一个非魔法物件，你将那名生物变形成一名不同的生物或一个非魔法物件，或者那个物件变形成一名生物（物件必须并未被着装或携带）。这一转变会一直持续到持续时间结束或目标死亡/被摧毁为止；如果你为此法术维持了最长时间的专注，则法术的持续时间会延长为直至被解除。\n一名非自愿生物可以进行一次感知豁免，若豁免成功则不会受此法术影响。\n生物变生物Creature into Creature。如果你将生物变成另一种生物，则其新形态可以是你选择的挑战等级小于等于目标挑战等级或等级的任何种类。目标的游戏数据被新形态的数据所替代，但目标保留其生命值、生命骰 、阵营、性格。目标获得等于新形态生命值的临时生命值 。法术结束时其失去所有因此法术获得的临时生命值。该生物只可做出其新形态的生理结构所允许的动作，不能说话也不能施法。 目标的装备融入新形态中。目标不能使用装备或者通过其他方式从装备中获得增益。物件变生物Object into Creature。你可以将一个物件变成任何一种符合下列要求的生物：生物的体型不能大于原物件，且生物的挑战等级必须小于等于9。变形出的生物对你和你的同伴保持友善 。而战斗中它将会在你的回合之后立刻进行其回合，且遵循你的命令。如果该法术持续时间超过1小时，则你将不再控制该生物。此后，该生物将根据你对待它的方式决定是否对你保持友善。生物变物件Creature into Object。 如果你将一名生物变形成一个物件，则它连同其穿着与携带物一起变成新的形态。变成物件的体型不能大于原生物。受术者的数据变成和该物件一样，在法术终止而受术者变回原形后，它将不会记得在变成物件时所发生的任何事情。","duration":"专注，至多1小时","higherLevels":null,"id":"True_Polymorph","level":9,"nameEn":"True Polymorph","nameZh":"完全变形术","range":"30尺","ritual":false,"school":"变化","source":"玩家手册2024"},{"castingTime":"1小时","classes":["牧师","德鲁伊"],"components":{"material":true,"materials":"一颗价值25000GP+的钻石，作为法术耗材","raw":"V、S、M（一颗价值25000GP+的钻石，作为法术耗材）","somatic":true,"verbal":true},"concentration":false,"description":"你触碰一名已死，但死亡时间不超过200年，并非死于年老的生物，使其以生命值全满的状态回生。\n此法术将治愈该生物身上的所有伤口，中和所有该生物身上的毒素，结束所有该生物身上的魔法疫病，也会移除该生物死亡时仍在生效的所有诅咒。此法术能替换所有受损或失去的器官和肢体。若生物曾是亡灵生物，则其还会恢复到其成为亡灵前的形态。\n此法术还能为遗体已不存在的生物使用，并能为它再造一个新的身体。在这种情况下，你必须喊出该生物的名字。之后，该生物将出现在你指定的距你10尺内一处未占据空间中。","duration":"立即","higherLevels":null,"id":"True_Resurrection","level":9,"nameEn":"True Resurrection","nameZh":"完全复生术","range":"触碰","ritual":false,"school":"死灵","source":"玩家手册2024"},{"castingTime":"动作","classes":["魔契师","法师"],"components":{"material":false,"materials":"","raw":"V、S","somatic":true,"verbal":true},"concentration":true,"description":"你尝试在他人的心中创造出虚幻的恐怖之物。以施法距离内你所选择的一点为中心，半径30尺球状区域内的每一个生物进行一次感知豁免。豁免失败时，目标受到10d10点心灵伤害并陷入恐慌状态，持续直至法术结束为止。豁免成功时，目标仅受到一半伤害。\n在受恐慌的生物自己的每个回合结束时，该生物可以再进行一次感知豁免。若再次豁免失败，它将受到5d10点心灵伤害。豁免成功时，法术对该目标的效应终止。","duration":"专注，至多1分钟","higherLevels":null,"id":"Weird","level":9,"nameEn":"Weird","nameZh":"怪影杀手","range":"120尺","ritual":false,"school":"幻术","source":"玩家手册2024"},{"castingTime":"动作","classes":["术士","法师"],"components":{"material":false,"materials":"","raw":"V","somatic":false,"verbal":true},"concentration":false,"description":"祈愿术是凡间生物所能施展的最强大法术。你只需要大声说出自己的愿望就能改变现实世界本身。\n法术最基础的用法是用来模仿任意一个八环或更低环阶的法术。如果你以此种方式使用该法术，你不需要满足目标法术所需的任何前提条件（包括有价值的材料成分）就可以让该法术生效。\n作为另一种方式，你也可以选择让法术创造下列效应之一：\n创造物件Object Creation。 你创造出一个价值不超过25000GP的物件，令其出现在地面上你能看见的一处未占据空间中。该物件不能是魔法物品，其在任意方向上的长度都不能超过300尺。即刻治疗Instant Health。你让你自己和至多二十个你可见的生物恢复全部生命值，并且终止它们身上一切在高等复原术greater restoration中列举过的所有效应。伤害抗性Resistance。你让至多十个你能看见的生物获得你所指定的一种伤害类型的抗性。此抗性是永久存在的。免疫法术Spell Immunity。 你让最多十个你能看见的生物免疫于某道法术或某种其他魔法效应，持续8小时。突来学识Sudden Learning。 你将你的一个专长替换为符合条件的另一个专长。你失去旧专长带来的全部好处，并获得新专长的好处。你无法取代作为你其他专长或特性先决条件的专长。重新掷骰Roll Redo。你改变一件刚刚发生的事件。重掷前一轮（包括你的上一个回合）到现在期间的任意一次掷骰，并让现实随着你的新掷骰结果改变。例如，祈愿术Wish可以撤销队友的失败豁免或敌人的重击。你可以迫使重新进行的掷骰具有优势或劣势 ，并且可以选择是使用重骰后的结果还是使用原来的结果。重塑现实Reshape Reality。你可能会许愿一些没有包含在上述效应中的东西。为了做到这样的效果，请尽可能准确地向地下城主描述你的愿望。在这种情况下，地下城主有极高的自由来裁决究竟会发生什么。不过愿望越大，出错的概率就越大。法术可能会直接失败，也可能部分的达成你想要的结果，还有可能因表述愿望时措辞不当而遭到意想不到的结果。例如，许愿让一个坏人死去可能会让你穿越到多年后该人已死的一个时间段，使你相当于离开了游戏一样。此外，许愿获取一件传说中的魔法物品或神器可能会立即将你转移到该物品当前的持有者身边。如果你许的愿望太过庞大，其效应影响到了社群、区域或是世界，你可能会引来强大的敌人。如果你的愿望会影响神，这名神的神仆会立刻干涉，阻止它或是鼓励你以一种特殊的方式许愿。如果你的愿望将会撤销多元宇宙本身，或是威胁到了印记城City of Sigil，或是以某种方式影响到了痛苦女士Lady of Pain ，你的心灵中就会浮现出一段她的影像：她摇了摇自己的脑袋，然后你的愿望失效了。\n除了模仿其他法术外，施展该法术以达成的任何其他目的都会使你的身躯承受极大的负担，令你变得无比虚弱。承受负担后，直到你完成长休之前，你每次施展法术时都将受到一定伤害（伤害数值取决于你施展的法术的环阶，每环阶1d10点的暗蚀伤害），此伤害无法被任何方式减免。此外，你的力量属性值将变为3，持续2d4日。这段时间内，你每花一整日休息（不从事轻度活动以外的行为），恢复需要的日数就减少 2 日。最后，承受负担时，你将有33%的概率永远也无法再次施展祈愿术Wish 。","duration":"立即","higherLevels":null,"id":"Wish","level":9,"nameEn":"Wish","nameZh":"祈愿术","range":"自身","ritual":false,"school":"咒法","source":"玩家手册2024"}];
